set lock_timeout = '8s';

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000034', 1034, 'Topic 34', 'Local news', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 34, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe local news that people were interested in", "bullets": ["what the news was", "where you saw or heard it", "who was involved", "why people were interested in it"], "explain": "", "notes": ["What", "Where", "Who", "Why"], "rounding": {"q": "Do you think that news is still talked about today?", "model": {"answer": "Yes, in our neighbourhood it is. Bobur has since become a kind of local hero, and the chess club now has so many new members that they’ve had to move to a bigger room.", "phrases": [], "grammar": []}}, "model": {"answer": "One piece of news that got the whole town talking was about a fourteen-year-old boy from our neighbourhood, Bobur, who won a national chess championship last spring. Nobody had given him much of a chance, because he was one of the youngest players and had only taken up the game three years earlier. I first heard about it from my mother, who’d seen a post on our district’s Telegram channel. Within an hour, it was all over the group chats, and that evening the regional TV station ran a short report with an interview at the chess club. The people involved were Bobur himself, his coach, Mr Rustam, a retired maths teacher who ran the club out of a tiny room above a library, and the local mayor, who later presented him with a trophy and promised the club a proper space. People were so interested for a few reasons. For one thing, he was a local, so it felt as though we all had a stake in his success. For another, he was a real underdog; the club was short of funds and had nearly shut down the year before. What really caught people’s imagination was the story of how he’d practised on his phone on the bus to and from school. It struck a chord with parents, many of whom were hoping their own children would find something to be passionate about. To me it showed how local news can lift the mood of a whole community. A story like this will never make international headlines, yet it was all anyone talked about for days.", "sections": [{"label": "What", "text": "One piece of news that got the whole town talking was about a fourteen-year-old boy from our neighbourhood, Bobur, who won a national chess championship last spring. Nobody had given him much of a chance, because he was one of the youngest players and had only taken up the game three years earlier."}, {"label": "Where", "text": "I first heard about it from my mother, who’d seen a post on our district’s Telegram channel. Within an hour, it was all over the group chats, and that evening the regional TV station ran a short report with an interview at the chess club."}, {"label": "Who", "text": "The people involved were Bobur himself, his coach, Mr Rustam, a retired maths teacher who ran the club out of a tiny room above a library, and the local mayor, who later presented him with a trophy and promised the club a proper space."}, {"label": "Why", "text": "People were so interested for a few reasons. For one thing, he was a local, so it felt as though we all had a stake in his success. For another, he was a real underdog; the club was short of funds and had nearly shut down the year before. What really caught people’s imagination was the story of how he’d practised on his phone on the bus to and from school. It struck a chord with parents, many of whom were hoping their own children would find something to be passionate about."}, {"label": "Reflection", "text": "To me it showed how local news can lift the mood of a whole community. A story like this will never make international headlines, yet it was all anyone talked about for days."}], "phrases": [["get people talking", "become a topic of conversation everywhere"], ["take up", "start doing a hobby or activity"], ["be all over", "be spreading everywhere"], ["present someone with", "formally give someone a prize or gift"], ["have a stake in", "have a personal interest in the outcome"], ["underdog", "a person not expected to win"], ["shut down", "close permanently"], ["catch someone’s imagination", "make people excited and interested"], ["strike a chord", "create a feeling of recognition or sympathy"], ["lift the mood", "make people feel more cheerful"], ["make international headlines", "be reported in the news around the world"]], "grammar": [{"pattern": "Past perfect", "use": "had + past participle: an earlier past fact", "example": "Nobody had given him much of a chance", "try": "Nobody had ______ him."}, {"pattern": "Non-defining relative clause", "use": "name + , who + verb + ,", "example": "Bobur, who won a national chess championship last spring", "try": "My neighbour, who ______, …"}, {"pattern": "As though", "use": "it felt as though + clause", "example": "it felt as though we all had a stake in his success", "try": "It felt as though ______."}, {"pattern": "Cleft sentence", "use": "What + subject + verb + was + noun phrase", "example": "What really caught people’s imagination was the story of how he’d practised on his phone", "try": "What really impressed me was ______."}, {"pattern": "Many of whom", "use": "clause + , many of whom + verb", "example": "many of whom were hoping their own children would find something to be passionate about", "try": "…neighbours, many of whom ______."}, {"pattern": "Future with will for a general truth", "use": "A + noun + will never + verb, yet + clause", "example": "A story like this will never make international headlines, yet it was all anyone talked about for days", "try": "A story like this will never ______, yet ______."}]}}, "part3": {"intro": "We’ve been talking about local news that people were interested in, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Local news", "title": "Local news", "questions": [{"q": "Why do people like to read local news?", "model": {"answer": "Because it affects them directly. A road closure, a new school or a rise in bus fares changes daily life in a way that distant events rarely do. There’s also familiarity: you might know the people involved or recognise the street in the photo. And local stories spark conversation, giving you something to chat about with neighbours and feel part of the community.", "phrases": [["affect (someone) directly", "have an immediate personal impact"], ["know the people", "be personally acquainted with those in the story"], ["spark conversation", "start people talking"], ["chat about", "talk casually about"], ["feel part of", "feel that you belong to a group"]], "grammar": [{"pattern": "", "use": "Relative clause: in a way that clause + in a way that + clause", "example": "changes daily life in a way that distant events rarely do", "try": "It changes my routine in a way that ______."}, {"pattern": "Participle clause", "use": "comma + -ing phrase: an added result", "example": "giving you something to chat about with neighbours", "try": "______, giving people something to ______."}]}}, {"q": "Do people prefer local news to international news?", "model": {"answer": "It depends on age and interests. Older people often keep an eye on local affairs because they’re settled in their community, whereas many young people follow global stories about technology, music or sport. Personally, I like a good balance of the two. International news gives you the big picture, but it’s the local stories that tell you what is going on around you.", "phrases": [["keep an eye on", "watch and stay informed about"], ["local affairs", "events and issues in your own area"], ["settled in", "comfortable and established in a place"], ["the big picture", "the general situation as a whole"], ["go on", "happen"]], "grammar": [{"pattern": "It depends on", "use": "It depends on + noun + and + noun", "example": "It depends on age and interests", "try": "It depends on ______ and ______."}, {"pattern": "Cleft sentence", "use": "it’s + the + noun + that + verb", "example": "it’s the local stories that tell you what is going on around you", "try": "It’s the small details that ______."}]}}, {"q": "How do people in your country usually get their news these days?", "model": {"answer": "Mostly through their phones. Telegram channels and Instagram have overtaken television and newspapers for people under forty, and many get headlines as push notifications before they even open an app. Older generations still tune in to the evening news on TV, so there’s a clear generation gap. Quite often, families learn about big stories second-hand, from a relative’s message in the family chat.", "phrases": [["overtake", "become more popular than something else"], ["push notification", "an automatic alert that appears on your phone"], ["tune in", "watch or listen to a broadcast"], ["generation gap", "difference in attitudes between old and young people"], ["second-hand", "indirectly, from another person"]], "grammar": [{"pattern": "Present perfect for change", "use": "have + past participle", "example": "Telegram channels and Instagram have overtaken television and newspapers", "try": "Online shopping has ______."}, {"pattern": "Before + even", "use": "before + subject + even + verb", "example": "before they even open an app", "try": "before I even ______."}]}}, {"q": "What do you think of getting news from social media?", "model": {"answer": "It’s a double-edged sword. On the one hand, it’s fast and free, and you can see events through the eyes of people who are actually there. On the other hand, there’s no editor, so rumours spread faster than corrections. Anyone relying on it should double-check a story with a reliable source before sharing it, because a false headline can go viral within hours.", "phrases": [["double-edged sword", "something with both good and bad effects"], ["rumours spread", "unconfirmed stories pass quickly from person to person"], ["double-check", "check again to be sure"], ["share", "post something so others can see it"], ["go viral", "spread very quickly online"]], "grammar": [{"pattern": "On the one hand… on the other", "use": "hand… two sides of a view", "example": "On the one hand, it’s fast and free", "try": "On the one hand, ______. On the other hand, ______."}, {"pattern": "", "use": "Comparative: faster than verb + faster than", "example": "rumours spread faster than corrections", "try": "News travels faster than ______."}]}}, {"q": "Is it important for people to have a national identity?", "model": {"answer": "To a certain extent, yes. A shared identity gives people a sense of belonging, and it brings a country together in difficult times, for instance after a natural disaster, when people instinctively help one another. The danger is when pride turns into exclusion of others. Ideally, it should be something people feel comfortable with, not something that is forced on them.", "phrases": [["a sense of belonging", "the feeling that you are part of a group"], ["bring together", "unite"], ["turn into", "change into"], ["comfortable with", "relaxed and at ease about"], ["force on", "make someone accept something unwillingly"]], "grammar": [{"pattern": "Noun clause with when", "use": "The danger is when + clause", "example": "The danger is when pride turns into exclusion of others", "try": "The problem is when ______."}, {"pattern": "Contrast with not + passive", "use": "relative not something that is + past participle", "example": "not something that is forced on them", "try": "It should be something people ______, not something that is ______."}]}}, {"q": "How can people develop a sense of national identity?", "model": {"answer": "Largely through shared experiences and, of course, education. Schools can teach history and literature, but festivals such as Navruz probably do more, because people take part in them together and take pride in the result. Families matter as well, since traditions are passed down through cooking, music and stories. The more visible a culture is in everyday life, the stronger the identity feels.", "phrases": [["shared experiences", "things many people go through together"], ["take part", "participate"], ["take pride in", "feel proud of"], ["pass down", "give to the next generation"], ["visible", "easy to see or notice"]], "grammar": [{"pattern": "The more… the…", "use": "The more + adjective + clause, the + comparative + clause", "example": "The more visible a culture is in everyday life, the stronger the identity feels", "try": "The more ______, the ______."}, {"pattern": "Passive", "use": "traditions are + past participle", "example": "traditions are passed down through cooking, music and stories", "try": "Customs are ______ from ______."}]}}, {"q": "Do you think photographs and videos make news more convincing?", "model": {"answer": "Up to a point. A video carries more weight than text because we trust our own eyes, particularly when it shows an event live. Even short footage can settle arguments. However, editing software and AI have made fakes so realistic that seeing is no longer believing. That’s why it’s worth checking where a clip comes from and whether other sources confirm it.", "phrases": [["up to a point", "partly, but not completely"], ["carry weight", "be taken seriously"], ["trust your own eyes", "believe what you see yourself"], ["where a clip comes from", "the origin of a video"], ["sources confirm", "other reports show that it is true"]], "grammar": [{"pattern": "So + adjective + that", "use": "so + adjective + that + result", "example": "fakes so realistic that seeing is no longer believing", "try": "The picture was so ______ that ______."}, {"pattern": "That’s why", "use": "That’s why + it’s worth + -ing", "example": "That’s why it’s worth checking", "try": "That’s why it’s worth ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Things & ideas"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000035', 1035, 'Topic 35', 'Person who is good at learning new languages', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 35, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a person who is good at learning and speaking new languages", "bullets": ["how you know this person", "how this person learns new languages", "how many languages this person can speak", "how you feel about this person"], "explain": "", "notes": ["Who", "How", "How Many", "Feelings"], "rounding": {"q": "Have you ever tried learning a language the way he does?", "model": {"answer": "I’ve tried, actually. I started watching German series with subtitles, and it’s working, slowly. The hardest part is staying consistent when I’m tired.", "phrases": [], "grammar": []}}, "model": {"answer": "A name that immediately springs to mind is Aziz, a classmate of mine at university who has a real gift for languages. We met on the first day, when he was the only one who could strike up a conversation with the exchange students from Korea, and we’ve been friends ever since. What fascinates me is his method. He never crams grammar rules. Instead, he immerses himself in the language: he watches series without subtitles, listens to podcasts on the way to class and, most importantly, talks to himself in the mirror. He also keeps a small notebook in which he jots down any phrase he overhears, and he reviews it every evening. When he gets something wrong, he simply laughs and keeps at it. As far as I know, he speaks five languages: Uzbek and Russian from childhood, English, which he picked up at school, and more recently German and Korean. His Korean is still basic, but he can already get by in a restaurant and hold a conversation about everyday topics without much trouble. I feel a mixture of admiration and, I must admit, a little envy. Whenever I struggle with vocabulary, I think of him. But mostly he inspires me, because he proves that languages are less about talent than about daily habits. Were it not for him, I’d probably have given up on German long ago. What I’ve taken away from watching him is that confidence matters as much as intelligence. He isn’t afraid to make a fool of himself, and that, more than anything, is why he makes such rapid progress.", "sections": [{"label": "Who", "text": "A name that immediately springs to mind is Aziz, a classmate of mine at university who has a real gift for languages. We met on the first day, when he was the only one who could strike up a conversation with the exchange students from Korea, and we’ve been friends ever since."}, {"label": "How", "text": "What fascinates me is his method. He never crams grammar rules. Instead, he immerses himself in the language: he watches series without subtitles, listens to podcasts on the way to class and, most importantly, talks to himself in the mirror. He also keeps a small notebook in which he jots down any phrase he overhears, and he reviews it every evening. When he gets something wrong, he simply laughs and keeps at it."}, {"label": "How Many", "text": "As far as I know, he speaks five languages: Uzbek and Russian from childhood, English, which he picked up at school, and more recently German and Korean. His Korean is still basic, but he can already get by in a restaurant and hold a conversation about everyday topics without much trouble."}, {"label": "Feelings", "text": "I feel a mixture of admiration and, I must admit, a little envy. Whenever I struggle with vocabulary, I think of him. But mostly he inspires me, because he proves that languages are less about talent than about daily habits. Were it not for him, I’d probably have given up on German long ago."}, {"label": "Reflection", "text": "What I’ve taken away from watching him is that confidence matters as much as intelligence. He isn’t afraid to make a fool of himself, and that, more than anything, is why he makes such rapid progress."}], "phrases": [["have a gift for", "have a natural talent for"], ["strike up a conversation", "start talking to someone, often a stranger"], ["cram", "study a lot of facts in a short time"], ["immerse yourself in", "become completely involved in something"], ["jot down", "write something quickly"], ["keep at it", "continue trying and not give up"], ["pick up", "learn naturally without formal study"], ["get by", "manage to cope with basic knowledge"], ["hold a conversation", "talk with someone for a while"], ["give up on", "stop trying to do something"], ["take away", "learn or keep as a lesson"], ["make a fool of yourself", "do something that makes you look silly"], ["make rapid progress", "improve very quickly"]], "grammar": [{"pattern": "Relative clause with who", "use": "noun + who + has + noun", "example": "a classmate of mine at university who has a real gift for languages", "try": "a friend of mine who has ______."}, {"pattern": "The only one who", "use": "the only one who + could + verb", "example": "he was the only one who could strike up a conversation", "try": "She was the only one who could ______."}, {"pattern": "Preposition + which", "use": "a notebook in which + clause", "example": "a small notebook in which he jots down any phrase he overhears", "try": "a diary in which she ______."}, {"pattern": "Non-defining relative clause", "use": "word + , which + subject + verb + ,", "example": "English, which he picked up at school,", "try": "Russian, which ______,"}, {"pattern": "Less … than …", "use": "less about X than about Y", "example": "languages are less about talent than about daily habits", "try": "Success is less about ______ than about ______."}, {"pattern": "", "use": "Inverted conditional: Were it not for Were it not for + noun, I’d probably have + past participle", "example": "Were it not for him, I’d probably have given up on German long ago", "try": "Were it not for ______, I’d probably have ______."}]}}, "part3": {"intro": "We’ve been talking about a person who is good at learning and speaking new languages, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Person who is good at learning new languages", "title": "Person who is good at learning new languages", "questions": [{"q": "Why are some people better at learning languages than others?", "model": {"answer": "A mix of factors. Motivation is probably the biggest: someone who needs a language for a job or a relationship will put in more effort. A good ear helps too, as does being willing to make mistakes without feeling embarrassed. Then there’s opportunity. A child brought up in a bilingual home picks up two languages without trying, whereas the rest of us have to work at it.", "phrases": [["put in effort", "work hard at something"], ["make mistakes", "get things wrong"], ["bring up", "raise a child"], ["pick up", "learn naturally without formal study"], ["work at it", "make a sustained effort to improve"]], "grammar": [{"pattern": "Relative clause with who", "use": "someone who + verb + will + verb", "example": "someone who needs a language for a job or a relationship will put in more effort", "try": "Someone who ______ will ______."}, {"pattern": "Contrast with whereas", "use": "clause + , whereas + clause", "example": "whereas the rest of us have to work at it", "try": ", whereas the rest of us ______."}]}}, {"q": "Is it more important to learn foreign languages now than in the past?", "model": {"answer": "Yes, mainly because the world is far more connected than it used to be. A few decades ago most people studied and worked within their own borders, whereas now a client, a lecture or an email can come from anywhere. That said, translation apps are improving, so the pressure to be fluent may ease. Even so, speaking someone’s language builds trust in a way no device can.", "phrases": [["come from anywhere", "originate in any part of the world"], ["connected", "linked with other people and places"], ["that said", "however, despite that"], ["ease", "become less severe"], ["build trust", "make people feel they can rely on you"]], "grammar": [{"pattern": "Comparative + than it used to be", "use": "far more + adjective + than it used to be", "example": "far more connected than it used to be", "try": "Life is far more ______ than it used to be."}, {"pattern": "In a way that", "use": "in a way (that) + subject + can", "example": "builds trust in a way no device can", "try": "It works in a way no ______ can."}]}}, {"q": "Do you think children learn new things more easily than adults?", "model": {"answer": "In some respects, yes. Children are less self-conscious, so they’re happy to have a go and get things wrong, and they absorb pronunciation almost effortlessly. Adults, on the other hand, have better study skills and a clearer sense of why they’re learning. So while kids may have the edge with accent, a motivated adult can often make faster progress in the early stages.", "phrases": [["self-conscious", "embarrassed about how others see you"], ["have a go", "try something"], ["have the edge", "have a small advantage"], ["make progress", "improve"], ["in some respects", "in certain ways"]], "grammar": [{"pattern": "So while", "use": "So while + clause, + clause", "example": "So while kids may have the edge with accent, a motivated adult can often make faster progress", "try": "So while ______, ______."}, {"pattern": "", "use": "Comparative: less … so less + adjective, so + clause", "example": "Children are less self-conscious, so they’re happy to have a go", "try": "Children are less ______, so ______."}]}}, {"q": "What can parents do to help their children learn languages?", "model": {"answer": "The most useful thing is to make it enjoyable. Reading bedtime stories in the target language, playing word games or putting on cartoons in English can do more than any workbook. Parents should also resist the urge to correct every mistake, since that can put children off. If they show interest in the language themselves, kids will usually follow their lead.", "phrases": [["make it enjoyable", "turn it into something fun"], ["put on", "start playing a film or programme"], ["resist the urge", "stop yourself from doing something tempting"], ["put someone off", "discourage someone"], ["follow someone’s lead", "copy what someone else does"]], "grammar": [{"pattern": "", "use": "Cleft: The most useful thing is to The + superlative + thing + is to + base verb", "example": "The most useful thing is to make it enjoyable", "try": "The most important thing is to ______."}, {"pattern": "First conditional", "use": "If + present simple, will + base verb", "example": "If they show interest in the language themselves, kids will usually follow their lead", "try": "If parents ______, children will ______."}]}}, {"q": "How do you think people will learn languages in the future?", "model": {"answer": "I’d expect technology to play a much bigger role. Real-time translation earphones will probably become so accurate, within a decade or so, that tourists won’t need to learn anything. But serious learners will still be around, using AI tutors that adapt to each person’s level and are available around the clock. Classes may shift towards conversation, with the boring drills left to apps.", "phrases": [["play a much bigger role", "become far more important"], ["left to", "handed over to someone or something else"], ["adapt to", "change to suit something"], ["available around the clock", "ready to use at any hour of the day or night"], ["shift towards", "gradually move towards"]], "grammar": [{"pattern": "", "use": "Prediction: would expect I’d expect + noun + to + infinitive", "example": "I’d expect technology to play a much bigger role", "try": "I’d expect prices to ______."}, {"pattern": "Absolute with participle", "use": "with + noun + past participle", "example": "with the boring drills left to apps", "try": "with the paperwork ______ to computers."}]}}, {"q": "Is it necessary to live in a country in order to master its language?", "model": {"answer": "Not strictly, but it certainly helps. Living abroad forces you to use the language every day, and you absorb slang and humour you’d never find in a textbook. Yet I know people who reached a very high level at home by surrounding themselves with the language through films, podcasts and calls with native speakers. What matters most is how much you use it, not where you are.", "phrases": [["absorb", "take in information naturally"], ["slang", "very informal words used in everyday speech"], ["surround yourself with", "fill your environment with"], ["reach a very high level", "achieve a very good standard"], ["native speaker", "person who has spoken the language since birth"]], "grammar": [{"pattern": "Object relative clause (no pronoun)", "use": "noun + (that) + subject + would never find", "example": "slang and humour you’d never find in a textbook", "try": "a word you’d never find in ______."}, {"pattern": "", "use": "Cleft: What matters most is What + verb + most + is + noun clause", "example": "What matters most is how much you use it", "try": "What matters most is ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "People"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000036', 1036, 'Topic 36', 'City you’ve been to and want to visit again', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 36, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a city you’ve been to and want to visit again", "bullets": ["what city it was", "when you went there", "what you did there", "why you liked it"], "explain": "", "notes": ["What", "When", "Did", "Why"], "rounding": {"q": "What would you do differently on a second visit?", "model": {"answer": "I’d stay longer and plan less. I’d cross over to the Asian side and simply spend a few days wandering, without a checklist.", "phrases": [], "grammar": []}}, "model": {"answer": "The city I’d love to go back to is Istanbul. I spent a week there with my best friend, Jahongir, three springs ago, and I still can’t believe how much we packed in during such a short stay. We went in April, just after I’d finished my exams, so we were both in need of a break. The weather was ideal: warm enough to sit outside but not scorching, and tulips were blooming in every park. In the mornings we’d wander around the old town, visiting Hagia Sophia and the Blue Mosque, and then have lunch at a tiny place near the Grand Bazaar. My favourite moment was a ferry ride across the Bosphorus at sunset, with seagulls following the boat and the sky turning orange. We bought a simit from a street seller and shared it, leaning on the railing. We never got round to visiting the Asian side, which is partly why I want to return. What I loved most was the atmosphere. It’s a city where East meets West, and you can feel the buzz on every street, from the call to prayer to the bustling cafés. People were friendly, and the food was outstanding. Honestly, I fell for the place within a day. Had we had more time, we’d have got off the beaten track and explored the neighbourhoods tourists rarely see. Looking back, Istanbul taught me that the best trips aren’t about ticking off sights; they’re about soaking up the atmosphere. I’m hoping to return next spring, and this time I’ll take it slow.", "sections": [{"label": "What", "text": "The city I’d love to go back to is Istanbul. I spent a week there with my best friend, Jahongir, three springs ago, and I still can’t believe how much we packed in during such a short stay."}, {"label": "When", "text": "We went in April, just after I’d finished my exams, so we were both in need of a break. The weather was ideal: warm enough to sit outside but not scorching, and tulips were blooming in every park."}, {"label": "Did", "text": "In the mornings we’d wander around the old town, visiting Hagia Sophia and the Blue Mosque, and then have lunch at a tiny place near the Grand Bazaar. My favourite moment was a ferry ride across the Bosphorus at sunset, with seagulls following the boat and the sky turning orange. We bought a simit from a street seller and shared it, leaning on the railing. We never got round to visiting the Asian side, which is partly why I want to return."}, {"label": "Why", "text": "What I loved most was the atmosphere. It’s a city where East meets West, and you can feel the buzz on every street, from the call to prayer to the bustling cafés. People were friendly, and the food was outstanding. Honestly, I fell for the place within a day. Had we had more time, we’d have got off the beaten track and explored the neighbourhoods tourists rarely see."}, {"label": "Reflection", "text": "Looking back, Istanbul taught me that the best trips aren’t about ticking off sights; they’re about soaking up the atmosphere. I’m hoping to return next spring, and this time I’ll take it slow."}], "phrases": [["pack in", "fit a lot of activities into a short time"], ["in need of a break", "really requiring a rest"], ["scorching", "extremely hot"], ["wander around", "walk without a fixed plan"], ["get round to", "finally find the time to do something"], ["feel the buzz", "sense the excitement and energy of a place"], ["bustling", "full of busy activity"], ["fall for", "fall in love with"], ["get off the beaten track", "go to places that tourists rarely visit"], ["tick off", "mark something as done"], ["soak up", "absorb and enjoy"], ["take it slow", "not rush"]], "grammar": [{"pattern": "Past perfect", "use": "just after + subject + had + past participle", "example": "just after I’d finished my exams", "try": "just after I’d ______."}, {"pattern": "Would for past habit", "use": "we’d + base verb: repeated actions in the past", "example": "In the mornings we’d wander around the old town", "try": "Every morning we’d ______."}, {"pattern": "Participle clause with with", "use": "with + noun + -ing", "example": "with seagulls following the boat and the sky turning orange", "try": "with the sun ______ and the crowds ______."}, {"pattern": "Non-defining which clause", "use": "clause + , which is partly why + clause", "example": "which is partly why I want to return", "try": "______, which is partly why ______."}, {"pattern": "Inverted third conditional", "use": "Had + subject + past participle, would have + past participle", "example": "Had we had more time, we’d have got off the beaten track", "try": "Had we had more time, we’d have ______."}, {"pattern": "Not about … but about", "use": "aren’t about + -ing; they’re about + -ing", "example": "the best trips aren’t about ticking off sights; they’re about soaking up the atmosphere", "try": "The best trips aren’t about ______; they’re about ______."}]}}, "part3": {"intro": "We’ve been talking about a city you’ve been to and want to visit again, and now I’d like to discuss with you one or two general questions related to this.", "theme": "City you’ve been to and want to visit again", "title": "City you’ve been to and want to visit again", "questions": [{"q": "What is the difference between living in a city and living in the countryside?", "model": {"answer": "The pace of life is the biggest contrast. Cities offer jobs, hospitals, universities and endless entertainment, but they’re also noisy, crowded and expensive. The countryside, by contrast, is quieter and cleaner, and neighbours know each other, although services can be thin on the ground. In short, cities offer convenience, while villages offer peace of mind and a slower, more close-knit way of life.", "phrases": [["by contrast", "on the other hand"], ["thin on the ground", "few in number, hard to find"], ["convenience", "easy access to useful things"], ["peace of mind", "a calm feeling of not worrying"], ["close-knit", "where people know and support each other"]], "grammar": [{"pattern": "Not only… but also (adjectives)", "use": "both… and / also + adjective list", "example": "they’re also noisy, crowded and expensive", "try": "They’re also ______, ______ and ______."}, {"pattern": "Comparative adjectives", "use": "adjective + er + and + adjective + er", "example": "quieter and cleaner", "try": "quieter and ______."}]}}, {"q": "Which would you prefer, living in a city or in the countryside?", "model": {"answer": "Personally, I’d choose the city, at least while I’m young. I thrive on the energy, and being able to reach work, friends and a good gym within twenty minutes is a huge plus. That said, if I had the choice later in life, I’d probably settle down somewhere greener, where I could grow vegetables and escape the rat race at weekends.", "phrases": [["thrive on", "enjoy and do well in a situation"], ["a huge plus", "a big advantage"], ["have the choice", "be free to decide"], ["settle down", "start a stable life in one place"], ["escape the rat race", "get away from the stress of competitive city life"]], "grammar": [{"pattern": "Second conditional", "use": "if + past simple, I’d + base verb", "example": "if I had the choice later in life, I’d probably settle down somewhere greener", "try": "If I had the choice, I’d ______."}, {"pattern": "Gerund subject", "use": "being able to + verb + is", "example": "being able to reach work, friends and a good gym within twenty minutes is a huge plus", "try": "Being able to ______ is a huge plus."}]}}, {"q": "Do you think modern cities are suitable for elderly people?", "model": {"answer": "To a degree, but there’s room for improvement. Cities have hospitals and pharmacies nearby, which matters enormously with age. Yet busy crossings, high-rise flats without lifts and fast traffic can make daily life far more stressful than it should be. If cities provided more benches, ramps and accessible public transport, older residents would feel far more independent. It’s a question of design, not of age.", "phrases": [["room for improvement", "things that could be made better"], ["high-rise", "very tall"], ["ramp", "a sloping surface that replaces steps"], ["accessible", "easy to reach and use"], ["independent", "able to manage without help"]], "grammar": [{"pattern": "Second conditional", "use": "If + past simple, would + base verb", "example": "If cities provided more benches, ramps and accessible public transport, older residents would feel far more independent", "try": "If cities provided ______, older people would ______."}, {"pattern": "Not… but contrast", "use": "It’s a question of X, not of Y", "example": "It’s a question of design, not of age", "try": "It’s a question of ______, not of ______."}]}}, {"q": "What changes have taken place in your city in recent years?", "model": {"answer": "Quite a lot. The skyline has changed noticeably, with new high-rise buildings, wider roads and many more parks and cafés than a decade ago. Public transport has also come a long way, which eases congestion. On the downside, traffic and air quality have worsened in some districts, and older neighbourhoods have given way to apartment blocks, so some of the city’s character has been lost.", "phrases": [["the skyline", "the outline of buildings against the sky"], ["come a long way", "make great progress"], ["ease congestion", "reduce traffic jams"], ["worsen", "get worse"], ["give way to", "be replaced by"]], "grammar": [{"pattern": "Present perfect passive", "use": "has been + past participle", "example": "some of the city’s character has been lost", "try": "A lot of the old charm has been ______."}, {"pattern": "Comparative with many more…", "use": "than many more + noun + than + time", "example": "many more parks and cafés than a decade ago", "try": "many more ______ than ten years ago."}]}}, {"q": "What should the government do to make cities safer?", "model": {"answer": "Better street lighting would be a good start, because poorly lit areas are where most people feel vulnerable. More cameras and visible police patrols can deter crime too, as long as privacy is respected. Safety isn’t only about crime, though: well-marked crossings and strict speed limits would save lives on the road every year. Ultimately, prevention matters far more than punishment.", "phrases": [["deter", "discourage someone from doing something"], ["as long as", "provided that"], ["well-marked", "clearly shown with lines or signs"], ["save lives", "stop people from dying"], ["prevention", "stopping something before it happens"]], "grammar": [{"pattern": "Where + clause", "use": "areas are where + subject + verb", "example": "poorly lit areas are where most people feel vulnerable", "try": "______ is where people ______."}, {"pattern": "As long as", "use": "as long as + passive", "example": "as long as privacy is respected", "try": "as long as ______ is respected."}]}}, {"q": "Do you think more people will live in the countryside in the future?", "model": {"answer": "I suspect the opposite, at least in my country, as young people keep moving to the city for jobs and education. That said, remote work might change the picture: if more people can do their jobs from anywhere, some will opt for quieter villages with cheaper housing. So I’d expect a modest shift rather than a mass exodus, and cities will still draw in most graduates.", "phrases": [["move to the city", "relocate from a village or town to a city"], ["change the picture", "alter the situation"], ["opt for", "choose"], ["mass exodus", "a large number of people leaving at once"], ["draw in", "attract"]], "grammar": [{"pattern": "Keep + -ing", "use": "keep + -ing: a continuing trend", "example": "young people keep moving to the city", "try": "Prices keep ______."}, {"pattern": "Rather than", "use": "noun + rather than + noun", "example": "a modest shift rather than a mass exodus", "try": "a gradual change rather than ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Places"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000037', 1037, 'Topic 37', 'Gift you want to buy', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 37, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a gift you’d like to buy for your friend", "bullets": ["what gift you want to buy", "who you’d like to give it to", "why you’d like to buy this gift", "why you’ve chosen that gift"], "explain": "", "notes": ["What", "Who", "Why", "Choice"], "rounding": {"q": "Do you think your friend will like the gift?", "model": {"answer": "I’m fairly sure he will, because he’s hinted at it more than once. Even if the camera isn’t perfect, I think he’ll appreciate that I remembered his passion for old photographs.", "phrases": [], "grammar": []}}, "model": {"answer": "The first thing that comes to mind is a gift I’ve been turning over in my head for weeks: a secondhand film camera, ideally an old Soviet Zenit in decent condition, with a few rolls of black-and-white film thrown in. It’s for my closest friend, Timur, who’s turning thirty next month. We’ve known each other since primary school, and he’s the kind of person who gives without keeping score. Last year, when I was short of cash after changing jobs, he quietly paid for my train ticket home and never mentioned it again. So I’d love to return the favour, but not with something forgettable. Timur has always been fascinated by old photographs. He once spent a whole afternoon at a flea market in Tashkent, leafing through boxes of faded family pictures and wondering who those people were. If I’d had a camera on me that day, I’d have photographed him doing it. As for why I’ve chosen this particular gift, it fits him like a glove. He’s always complaining that his phone makes every picture look the same, and a film camera forces you to think before you shoot, because every frame costs money. It isn’t cheap, so I’ve been putting aside a little each week. I’m also planning to develop the first roll together with him, so the present becomes an afternoon we share rather than an object that ends up gathering dust. To my mind, a gift works best when it proves you’ve been paying attention to the person, and that matters far more than the price.", "sections": [{"label": "What", "text": "The first thing that comes to mind is a gift I’ve been turning over in my head for weeks: a secondhand film camera, ideally an old Soviet Zenit in decent condition, with a few rolls of black-and-white film thrown in."}, {"label": "Who", "text": "It’s for my closest friend, Timur, who’s turning thirty next month. We’ve known each other since primary school, and he’s the kind of person who gives without keeping score. Last year, when I was short of cash after changing jobs, he quietly paid for my train ticket home and never mentioned it again."}, {"label": "Why", "text": "So I’d love to return the favour, but not with something forgettable. Timur has always been fascinated by old photographs. He once spent a whole afternoon at a flea market in Tashkent, leafing through boxes of faded family pictures and wondering who those people were. If I’d had a camera on me that day, I’d have photographed him doing it."}, {"label": "Choice", "text": "As for why I’ve chosen this particular gift, it fits him like a glove. He’s always complaining that his phone makes every picture look the same, and a film camera forces you to think before you shoot, because every frame costs money. It isn’t cheap, so I’ve been putting aside a little each week. I’m also planning to develop the first roll together with him, so the present becomes an afternoon we share rather than an object that ends up gathering dust."}, {"label": "Reflection", "text": "To my mind, a gift works best when it proves you’ve been paying attention to the person, and that matters far more than the price."}], "phrases": [["turn something over in your head", "think about something carefully and for a long time"], ["give without keeping score", "help others generously without expecting anything back"], ["short of cash", "having too little money at the moment"], ["return the favour", "do something kind for someone who once helped you"], ["leaf through", "turn the pages of something quickly, without reading everything"], ["fit someone like a glove", "suit a person perfectly"], ["think before you shoot", "consider carefully before taking each photo"], ["put aside", "save a small amount of money regularly"], ["gather dust", "stay unused for a long time"], ["pay attention to", "notice and care about the details of someone or something"]], "grammar": [{"pattern": "Relative clause with who", "use": "noun + who + clause", "example": "Timur, who’s turning thirty next month", "try": "My cousin, who ______, is ______."}, {"pattern": "Past perfect for earlier events", "use": "had + past participle", "example": "when I was short of cash after changing jobs, he quietly paid", "try": "When I ______, he ______."}, {"pattern": "Second/third conditional mix", "use": "If + past perfect, would have + past participle", "example": "If I’d had a camera on me that day, I’d have photographed him", "try": "If I’d ______, I’d have ______."}, {"pattern": "Participle clause", "use": "-ing phrase replacing a clause", "example": "leafing through boxes of faded family pictures and wondering who those people were", "try": "He spent an hour ______ing through ______ and ______ing ______."}, {"pattern": "Rather than", "use": "A rather than B", "example": "rather than an object that ends up gathering dust", "try": "I want a gift that is ______ rather than ______."}]}}, "part3": {"intro": "We’ve been talking about a gift you’d like to buy for your friend, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Gift you want to buy", "title": "Gift you want to buy", "questions": [{"q": "Why is it sometimes difficult to choose a gift for someone?", "model": {"answer": "Mostly because you’re trying to guess what goes on in someone else’s head. Unless you know a person very well, it’s hard to tell what they already own or would actually use. There’s also the pressure of striking the right balance, being thoughtful without being intrusive. I once ended up buying perfume for a colleague who turned out to be allergic, which taught me to ask a mutual friend first.", "phrases": [["Unless", "if not; except when"], ["strike the right balance", "find a sensible middle point between two things"], ["end up doing", "finally do something, often unplanned"], ["turn out to be", "prove to be, as discovered later"], ["a mutual friend", "a friend both people know"]], "grammar": [{"pattern": "Unless", "use": "Unless + present simple, main clause", "example": "Unless you know a person very well, it’s hard to tell", "try": "Unless ______, it’s hard to ______."}, {"pattern": "Non-defining which", "use": "..., which + verb (comment on whole clause)", "example": "which taught me to ask a mutual friend first", "try": "..., which taught me ______."}]}}, {"q": "Is the price of a gift important?", "model": {"answer": "Less than people assume. A present that’s clearly well thought out will always beat something expensive picked up in a hurry. That said, price isn’t irrelevant: turning up to a wedding with something very cheap can look careless. The real skill is finding a gift that stays within your budget yet still feels personal, such as a book the person once mentioned in passing. It’s the effort that people remember.", "phrases": [["well thought out", "carefully planned and considered"], ["pick up in a hurry", "buy quickly without much care"], ["look careless", "seem as if you didn’t take enough care"], ["stay within your budget", "not spend more than you planned"], ["mention in passing", "say briefly, without making a point of it"]], "grammar": [{"pattern": "Comparative with less/than", "use": "less than + clause", "example": "Less than people assume", "try": "It matters less than ______."}, {"pattern": "Past participle as adjective", "use": "noun + past participle", "example": "something expensive picked up in a hurry", "try": "Something ______ picked up ______."}]}}, {"q": "Do people feel happier when they receive an expensive gift?", "model": {"answer": "Only briefly, in my experience. The excitement of unwrapping something costly wears off quickly, whereas a gift that shows real attention is remembered for years. If an acquaintance handed me an expensive watch, I’d feel awkward rather than happy, because it would seem like a status symbol rather than a gesture. Happiness comes from feeling understood, which is not something a price tag can guarantee.", "phrases": [["wear off", "gradually disappear or become weaker"], ["hand someone something", "give something to someone directly"], ["status symbol", "an object that shows wealth or social position"], ["a gesture", "a kind action that expresses a feeling"], ["price tag", "the cost of something"]], "grammar": [{"pattern": "Second conditional", "use": "If + past simple, would + verb", "example": "If an acquaintance handed me an expensive watch, I’d feel awkward", "try": "If someone ______, I’d feel ______."}, {"pattern": "Contrast with whereas", "use": "clause 1, whereas clause 2", "example": "whereas a gift that shows real attention is remembered for years", "try": "______, whereas ______."}]}}, {"q": "On what occasions do people in your country usually give gifts?", "model": {"answer": "Birthdays and weddings are the obvious ones, but in Uzbekistan the Eid holidays and Navruz matter just as much, along with housewarmings and the birth of a baby. At weddings, guests are expected to bring money or something useful for the new couple. Smaller milestones, like graduating or returning from a long trip, also call for a modest present, usually sweets or little souvenirs for the family.", "phrases": [["matter just as much", "be equally important"], ["housewarming", "a party to celebrate moving into a new home"], ["be expected to", "be required by custom"], ["call for", "make something necessary or appropriate"], ["a milestone", "an important event in life"]], "grammar": [{"pattern": "Passive with expected", "use": "be expected to + verb", "example": "guests are expected to bring money", "try": "Guests are expected to ______."}, {"pattern": "Participle after like", "use": "like + -ing", "example": "like graduating or returning from a long trip", "try": "Smaller occasions, like ______ing, also ______."}]}}, {"q": "What gifts are popular in your country?", "model": {"answer": "Flowers, perfume and sweets top the list, particularly for women, while men tend to receive watches, wallets or electronics. Among younger people, gift cards and experiences, such as a meal at a nice restaurant, are catching on. Traditional presents haven’t disappeared, though: an embroidered suzani, a ceramic plate or a box of dried fruit and nuts still goes down well, especially when visiting relatives, because they feel sincere.", "phrases": [["top the list", "be the most common or popular"], ["catch on", "become popular"], ["go down well", "be received happily"], ["sincere", "honest and genuinely felt"], ["tend to", "usually do something"]], "grammar": [{"pattern": "Tend to", "use": "tend to + verb", "example": "men tend to receive watches, wallets or electronics", "try": "People tend to ______."}, {"pattern": "Present perfect negative", "use": "haven’t + past participle", "example": "Traditional presents haven’t disappeared, though", "try": "______ haven’t ______, though."}]}}, {"q": "What do parents consider when they choose a gift for a child?", "model": {"answer": "Safety and age come first, no question. Parents avoid toys with small parts for toddlers, and they look for something age-appropriate. Beyond that, many hope a gift will be educational, such as building sets, books or puzzles instead of screens. Not only does this keep children busy, but it also sparks their imagination. Of course, what the child actually wants matters too, otherwise the present ends up in a drawer.", "phrases": [["age-appropriate", "suitable for a child’s age"], ["come first", "be the top priority"], ["keep someone busy", "give someone something to do"], ["spark imagination", "make creative thinking start"], ["end up in a drawer", "stay forgotten and unused"]], "grammar": [{"pattern": "Inversion with not only", "use": "Not only + auxiliary + subject ..., but also", "example": "Not only does this keep children busy, but it also sparks their imagination", "try": "Not only does it ______, but it also ______."}, {"pattern": "Otherwise", "use": "..., otherwise + clause", "example": "otherwise the present ends up in a drawer", "try": "______, otherwise ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Things & ideas"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000038', 1038, 'Topic 38', 'Person you met once and want to know more about', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 38, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a person you met only once and you want to know more about", "bullets": ["who this person is", "how you met this person", "when you met this person", "why you want to know more about this person"], "explain": "", "notes": ["Who", "How", "When", "Why"], "rounding": {"q": "Do you think you will ever meet him again?", "model": {"answer": "Honestly, it’s unlikely, but I haven’t given up. I sometimes ask geology students whether they know a veteran called Anvar, and one day somebody might recognise the description.", "phrases": [], "grammar": []}}, "model": {"answer": "If I had to pick one person, it would be an elderly geologist called Anvar, whom I met exactly once and whose surname I never even learnt. We met on a night train from Bukhara to Tashkent. My seat had been double-booked, so I ended up in his compartment until he offered me tea from a battered old thermos and we struck up a conversation. That was about two winters ago, in late February. It was snowing heavily, and the train kept grinding to a halt in the middle of nowhere, so we had plenty of time to kill. Somewhere around midnight he started describing his expeditions across the Kyzylkum desert in the seventies, where he’d once spent three weeks sleeping in a tent and mapping rocks. He spoke so vividly that I forgot to check my phone for hours. Rarely had a stranger held my attention so completely. Just as he was getting to the best part, an announcement told us we’d arrived. He shook my hand, wished me luck with my studies and disappeared into the crowd. I’ve been kicking myself for not asking for a phone number ever since. I want to know more because he’d clearly lived a remarkable life, and I only heard fragments of it. What made him choose that career? What struck me was how down-to-earth he was, as if those adventures were nothing special. Had I been a little braver, I’d have jotted down his address. Looking back, he left a lasting impression on me, and I’m convinced that interesting people cross our paths only briefly, so it costs nothing to ask for a name and keep in touch.", "sections": [{"label": "Who", "text": "If I had to pick one person, it would be an elderly geologist called Anvar, whom I met exactly once and whose surname I never even learnt."}, {"label": "How", "text": "We met on a night train from Bukhara to Tashkent. My seat had been double-booked, so I ended up in his compartment until he offered me tea from a battered old thermos and we struck up a conversation."}, {"label": "When", "text": "That was about two winters ago, in late February. It was snowing heavily, and the train kept grinding to a halt in the middle of nowhere, so we had plenty of time to kill. Somewhere around midnight he started describing his expeditions across the Kyzylkum desert in the seventies, where he’d once spent three weeks sleeping in a tent and mapping rocks. He spoke so vividly that I forgot to check my phone for hours. Rarely had a stranger held my attention so completely."}, {"label": "Why", "text": "Just as he was getting to the best part, an announcement told us we’d arrived. He shook my hand, wished me luck with my studies and disappeared into the crowd. I’ve been kicking myself for not asking for a phone number ever since. I want to know more because he’d clearly lived a remarkable life, and I only heard fragments of it. What made him choose that career? What struck me was how down-to-earth he was, as if those adventures were nothing special. Had I been a little braver, I’d have jotted down his address. Looking back, he left a lasting impression on me, and I’m convinced that interesting people cross our paths only briefly, so it costs nothing to ask for a name and keep in touch."}], "phrases": [["double-booked", "reserved for two people by mistake"], ["ended up", "finally found myself somewhere, often unplanned"], ["struck up a conversation", "started talking to someone casually"], ["grinding to a halt", "slowly coming to a stop"], ["plenty of time to kill", "a lot of spare time with nothing to do"], ["getting to the best part", "reaching the most exciting point of a story"], ["kicking myself for", "feeling annoyed with myself about a mistake"], ["down-to-earth", "modest, practical and natural"], ["jotted down", "wrote quickly and briefly"], ["left a lasting impression", "made a strong effect that lasted for a long time"], ["cross our paths", "meet us by chance"], ["keep in touch", "stay in contact"]], "grammar": [{"pattern": "Relative clause with whom / whose", "use": "noun + whom/whose + clause", "example": "whom I met exactly once and whose surname I never even learnt", "try": "a teacher whom I ______ and whose ______."}, {"pattern": "Past perfect passive", "use": "had been + past participle", "example": "My seat had been double-booked", "try": "My ______ had been ______, so I ______."}, {"pattern": "so ... that", "use": "so + adverb + that + result", "example": "He spoke so vividly that I forgot to check my phone", "try": "She spoke so ______ that I ______."}, {"pattern": "Inversion with rarely", "use": "Rarely + had + subject + past participle", "example": "Rarely had a stranger held my attention so completely", "try": "Rarely had I ______."}, {"pattern": "Third conditional (inverted)", "use": "Had + subject + past participle, would have + past participle", "example": "Had I been a little braver, I’d have jotted down his address", "try": "Had I ______, I’d have ______."}, {"pattern": "Cleft sentence with what", "use": "What + subject + verb + was ...", "example": "What struck me was how down-to-earth he was", "try": "What struck me was ______."}]}}, "part3": {"intro": "We’ve been talking about a person you met only once and you want to know more about, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Person you met once and want to know more about", "title": "Person you met once and want to know more about", "questions": [{"q": "What do you think of making friends online?", "model": {"answer": "On the one hand, it’s a great way to meet people who share a niche interest, whether that’s chess or learning Korean. On the other hand, you can’t read body language through a screen, so it takes longer to build trust. I’d treat online friendships as a good starting point, as long as they eventually move beyond messages to voice calls or real meetings.", "phrases": [["a great way to", "a very good method for doing something"], ["read body language", "understand feelings from posture and gestures"], ["build trust", "gradually make someone believe in you"], ["a good starting point", "a useful way to begin"], ["move beyond", "go further than"]], "grammar": [{"pattern": "Two-sided contrast", "use": "On the one hand ... On the other hand ...", "example": "On the one hand, it’s a great way to meet people", "try": "On the one hand, ______. On the other hand, ______."}, {"pattern": "as long as", "use": "as long as + present simple (condition)", "example": "as long as they eventually move beyond messages", "try": "It’s fine as long as ______."}]}}, {"q": "Is it easy to find real friends on social networking sites?", "model": {"answer": "Not really, because these platforms reward quantity over quality. You can collect hundreds of followers, but few of them would be there for you at two in the morning. People also curate their lives online, so you rarely see someone’s real personality. If I were looking for genuine friends, I’d use the sites only to arrange meetings in person, never as a substitute for them.", "phrases": [["reward quantity over quality", "favour having many things rather than good ones"], ["be there for you", "give you support when you need it"], ["curate their lives", "show only a carefully chosen version of their lives"], ["genuine friends", "sincere, honest friends"], ["a substitute for", "something used instead of something else"]], "grammar": [{"pattern": "Second conditional", "use": "If + past simple, would + verb", "example": "If I were looking for genuine friends, I’d use the sites only to arrange meetings", "try": "If I were ______, I’d ______."}, {"pattern": "Quantifier few of them", "use": "few of + them + would", "example": "few of them would be there for you", "try": "Few of them would ______."}]}}, {"q": "Is it important for friends to share the same interests?", "model": {"answer": "It helps at the start, but it isn’t essential. Shared hobbies give people an easy icebreaker. However, the friendships that stand the test of time usually rest on shared values, such as honesty and respect. My closest friend couldn’t care less about football, which I love, yet we’ve never run out of things to say. What matters is seeing eye to eye on the big questions.", "phrases": [["icebreaker", "something that makes it easier to start talking"], ["stand the test of time", "last for a long time"], ["couldn’t care less about", "has no interest at all in"], ["run out of", "have no more of something"], ["seeing eye to eye", "agreeing"]], "grammar": [{"pattern": "Present perfect with never", "use": "have/has never + past participle", "example": "we’ve never run out of things to say", "try": "We’ve never ______."}, {"pattern": "Cleft sentence", "use": "What matters is + -ing/clause", "example": "What matters is seeing eye to eye on the big questions", "try": "What matters is ______."}]}}, {"q": "Do we benefit from having friends with different personalities?", "model": {"answer": "Definitely, because different personalities balance each other out. A cautious friend will make you think twice before a risky decision, while an outgoing one will drag you out of your comfort zone. The more varied your circle is, the more perspectives you’re exposed to, and that makes you more flexible. Surrounding yourself with people exactly like you may feel comfortable, but it limits your growth.", "phrases": [["balance each other out", "reduce each other’s extremes"], ["think twice", "consider carefully before acting"], ["comfort zone", "situations where you feel safe and at ease"], ["exposed to", "given the chance to experience"], ["limits your growth", "stops you developing"]], "grammar": [{"pattern": "The more ... the more", "use": "The more + adjective ..., the more ...", "example": "The more varied your circle is, the more perspectives you’re exposed to", "try": "The more ______, the more ______."}, {"pattern": "Gerund as subject", "use": "-ing phrase + may/can + verb", "example": "Surrounding yourself with people exactly like you may feel comfortable", "try": "Surrounding yourself with ______ may ______."}]}}, {"q": "Where and how do people in your country usually meet new friends?", "model": {"answer": "Traditionally, most friendships take shape in the neighbourhood, at school or university, and through relatives, since families here are close-knit. Nowadays, though, many people meet through sports clubs, language courses or work, and Telegram groups have become a hub for shared interests. A friend of a friend is probably the commonest route: you’re introduced at a gathering, and the friendship grows from there.", "phrases": [["take shape", "gradually develop"], ["close-knit", "having strong, friendly bonds"], ["a hub for", "a central place for an activity"], ["a friend of a friend", "someone you know through another person"], ["grows from there", "develops naturally afterwards"]], "grammar": [{"pattern": "Present perfect for change", "use": "have/has + become", "example": "Telegram groups have become a hub for shared interests", "try": "______ have become ______."}, {"pattern": "Passive", "use": "be + past participle", "example": "you’re introduced at a gathering", "try": "You’re introduced ______."}]}}, {"q": "In what situations are people willing to get to know strangers?", "model": {"answer": "When there’s a shared purpose: travelling, studying in the same class or working on an event together. If you’re stuck on a delayed train, for instance, you’re far more likely to start chatting, because the situation breaks the ice. People also open up when they feel safe. Otherwise, most of us keep to ourselves, especially in big cities where everyone seems to be in a hurry.", "phrases": [["shared purpose", "a common aim people work towards"], ["breaks the ice", "makes people feel relaxed enough to talk"], ["open up", "start talking about yourself freely"], ["keep to ourselves", "avoid talking to other people"], ["in a hurry", "rushing; in a rush"]], "grammar": [{"pattern": "Conditional with if + present", "use": "If + present simple, you’re likely to ...", "example": "If you’re stuck on a delayed train, for instance, you’re far more likely to start chatting", "try": "If you’re ______, you’re more likely to ______."}, {"pattern": "Relative where", "use": "place + where + clause", "example": "especially in big cities where everyone seems to be in a hurry", "try": "______ where everyone ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "People"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000039', 1039, 'Topic 39', 'Course that impressed you', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 39, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a course that impressed you", "bullets": ["what the course was about", "where you took the course", "what you did during the course", "why it impressed you"], "explain": "", "notes": ["What", "Where", "Do", "Why"], "rounding": {"q": "Would you recommend this course to other people?", "model": {"answer": "Without hesitation, especially to anyone who dreads speaking in front of others. It’s not about becoming a perfect speaker; it’s about learning that you can survive being nervous.", "phrases": [], "grammar": []}}, "model": {"answer": "One occasion I’ll never forget is a six-week course in public speaking that I signed up for on a whim, after I froze completely during a presentation at university. My mind simply went blank in front of forty classmates. It took place at a small training centre in Tashkent, in a bright room on the third floor with mismatched chairs and a whiteboard covered in old marker stains. Nothing about the place looked impressive. The teacher, Ms Nodira, was a former radio presenter whose calm, unhurried voice put everyone at ease the moment she started speaking. Each week we had to prepare a two-minute talk and deliver it standing up, with no notes. She filmed us on a phone, and we watched the recordings together, which was excruciating at first. We also practised pausing on purpose, which felt unnatural but turned out to be the secret. By week four, I was thinking on my feet when the group threw surprise questions at me, something I would never have imagined doing. What impressed me most was the feedback. Instead of vague praise, she would point to one specific habit, such as rushing the opening or fiddling with my sleeve, and suggest a practical fix. Had I not taken that course, I’d probably still be dreading every presentation. It rebuilt my confidence from the ground up, and the lesson I took away is that nerves never disappear completely; you simply learn to work with them. Not only did my marks improve, but I also volunteered to speak at a student conference, which would have been unthinkable before.", "sections": [{"label": "What", "text": "One occasion I’ll never forget is a six-week course in public speaking that I signed up for on a whim, after I froze completely during a presentation at university. My mind simply went blank in front of forty classmates."}, {"label": "Where", "text": "It took place at a small training centre in Tashkent, in a bright room on the third floor with mismatched chairs and a whiteboard covered in old marker stains. Nothing about the place looked impressive. The teacher, Ms Nodira, was a former radio presenter whose calm, unhurried voice put everyone at ease the moment she started speaking."}, {"label": "Do", "text": "Each week we had to prepare a two-minute talk and deliver it standing up, with no notes. She filmed us on a phone, and we watched the recordings together, which was excruciating at first. We also practised pausing on purpose, which felt unnatural but turned out to be the secret. By week four, I was thinking on my feet when the group threw surprise questions at me, something I would never have imagined doing."}, {"label": "Why", "text": "What impressed me most was the feedback. Instead of vague praise, she would point to one specific habit, such as rushing the opening or fiddling with my sleeve, and suggest a practical fix. Had I not taken that course, I’d probably still be dreading every presentation. It rebuilt my confidence from the ground up, and the lesson I took away is that nerves never disappear completely; you simply learn to work with them. Not only did my marks improve, but I also volunteered to speak at a student conference, which would have been unthinkable before."}], "phrases": [["on a whim", "suddenly, without planning"], ["froze", "became unable to speak or move because of nerves"], ["went blank", "became empty; I couldn’t remember anything"], ["put everyone at ease", "made everyone feel relaxed"], ["mismatched", "not matching; all different"], ["excruciating", "extremely uncomfortable or painful"], ["turned out to be", "proved to be, as we later found"], ["thinking on my feet", "responding quickly without preparation"], ["fiddling with", "touching something nervously"], ["from the ground up", "starting from the basics"], ["took away", "learnt and kept as a main message"], ["work with them", "manage them rather than fight them"]], "grammar": [{"pattern": "Relative clause with whose", "use": "noun + whose + noun + verb", "example": "whose calm, unhurried voice put everyone at ease", "try": "a teacher whose ______ ______."}, {"pattern": "Reduced relative / participle", "use": "noun + -ing/-ed phrase", "example": "a whiteboard covered in old marker stains", "try": "a room filled with ______."}, {"pattern": "Would for past habits", "use": "would + verb", "example": "she would point to one specific habit", "try": "Every week she would ______."}, {"pattern": "Third conditional (inverted)", "use": "Had + subject + past participle ..., would have ...", "example": "Had I not taken that course, I’d probably still be dreading every presentation", "try": "Had I not ______, I’d ______."}, {"pattern": "Not only ... but also (inversion)", "use": "Not only did + subject + verb, but ... also", "example": "Not only did my marks improve, but I also volunteered", "try": "Not only did ______, but I also ______."}, {"pattern": "Would have + past participle", "use": "would have + p.p. (unreal past)", "example": "would have been unthinkable before", "try": "It would have been ______ before."}]}}, "part3": {"intro": "We’ve been talking about a course that impressed you, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Course that impressed you", "title": "Course that impressed you", "questions": [{"q": "Why do some people take extra courses after they finish school?", "model": {"answer": "Often it’s about keeping up with a competitive job market. A degree gives you the basics, but employers increasingly want practical skills, such as coding or a foreign language. Others take courses simply out of curiosity, or because they feel their schooling left gaps. And for people planning a career change, a short course is a cost-effective way to test the water before committing to a new field.", "phrases": [["keeping up with", "staying at the same level as others"], ["out of curiosity", "because you want to know or learn"], ["left gaps", "did not cover some areas"], ["a career change", "moving to a different type of job"], ["test the water", "try something before fully deciding"]], "grammar": [{"pattern": "Participle after for", "use": "for + people + -ing", "example": "for people planning a career change", "try": "For people ______ing, a course is ______."}, {"pattern": "Because clause", "use": "because + subject + verb", "example": "because they feel their schooling left gaps", "try": "______ because they feel ______."}]}}, {"q": "What are the advantages of online courses compared with classroom courses?", "model": {"answer": "The biggest advantage is flexibility: you can learn at your own pace, even at midnight, and replay a lecture you didn’t follow. Online courses are usually cheaper, and they open doors for people living far from big cities. Having said that, they demand self-discipline. Without a teacher watching, it’s easy to put things off, which explains why so many learners never finish them.", "phrases": [["at your own pace", "as fast or slowly as you like"], ["open doors", "create new opportunities"], ["having said that", "however; despite what I just said"], ["self-discipline", "ability to make yourself do things"], ["put things off", "delay doing things"]], "grammar": [{"pattern": "Concession", "use": "Having said that, ...", "example": "Having said that, they demand self-discipline", "try": "Having said that, ______."}, {"pattern": "Non-defining which", "use": "..., which explains why ...", "example": "which explains why so many learners never finish them", "try": "..., which explains why ______."}]}}, {"q": "What makes a course interesting for students?", "model": {"answer": "Interaction, above all. A course comes alive when students are asked to discuss, solve problems or present, rather than simply copy from slides. It also helps if the content feels relevant to their lives and the teacher is clearly passionate. Nothing kills motivation faster than a monotone lecture, whereas a little humour and real examples can turn an ordinary lesson into one people look forward to.", "phrases": [["comes alive", "becomes exciting and full of energy"], ["copy from slides", "write down what is on the screen without thinking"], ["relevant to", "connected to what matters to someone"], ["kills motivation", "destroys the desire to work"], ["look forward to", "feel happy about something in the future"]], "grammar": [{"pattern": "Nothing + comparative", "use": "Nothing + verb + comparative + than", "example": "Nothing kills motivation faster than a monotone lecture", "try": "Nothing ______ faster than ______."}, {"pattern": "Relative clause with one", "use": "turn A into one (that) + clause", "example": "into one people look forward to", "try": "... into one ______ look forward to."}]}}, {"q": "Why do some people have a better memory than others?", "model": {"answer": "Partly genetics, but habits probably matter more. People who sleep well, stay focused and review information regularly tend to remember more. Some also use techniques such as linking facts to vivid images, which makes details stick. Stress plays a part too, since an anxious mind struggles to take things in. So a good memory isn’t only a gift; to a large extent, it can be trained.", "phrases": [["matter more", "be more important"], ["stay focused", "keep your attention on one thing"], ["makes details stick", "help you remember small facts"], ["take things in", "absorb and understand information"], ["to a large extent", "mostly"]], "grammar": [{"pattern": "Relative clause with who", "use": "people + who + verb", "example": "People who sleep well, stay focused and review information regularly", "try": "People who ______ tend to ______."}, {"pattern": "Not only (passive modal)", "use": "can + be + past participle", "example": "it can be trained", "try": "It can be ______."}]}}, {"q": "Should adults continue studying throughout their lives?", "model": {"answer": "Yes, I’d say it’s almost a necessity now. Jobs change so fast that skills learnt at twenty can be out of date by forty. Beyond work, learning keeps the mind sharp and gives older people a sense of purpose. If I could, I’d make time every year for a course in something unrelated to my job, just to broaden my horizons. Education shouldn’t end with a diploma.", "phrases": [["out of date", "no longer modern or useful"], ["keeps the mind sharp", "keeps thinking quick and clear"], ["a sense of purpose", "a feeling that life has meaning"], ["unrelated to", "not connected with"], ["broaden my horizons", "experience new ideas"]], "grammar": [{"pattern": "Second conditional", "use": "If + past simple, would + verb", "example": "If I could, I’d make time every year for a course", "try": "If I could, I’d ______."}, {"pattern": "so ... that", "use": "so + adverb + that", "example": "Jobs change so fast that skills learnt at twenty can be out of date", "try": "______ so fast that ______."}]}}, {"q": "What can teachers do to make lessons more memorable?", "model": {"answer": "Stories and surprises work wonders. If a teacher links a grammar rule to a funny real-life situation, students will recall it long after the exam. Hands-on activities, such as role-plays or small projects, beat rote learning every time. Revision matters too, but spread over several weeks rather than crammed into one night. What students remember most is how a lesson made them feel.", "phrases": [["work wonders", "be very effective"], ["hands-on", "involving doing things practically"], ["rote learning", "learning by repeating without understanding"], ["spread over", "done across a period of time"], ["crammed into", "squeezed into a short time"]], "grammar": [{"pattern": "First conditional", "use": "If + present simple, will + verb", "example": "If a teacher links a grammar rule to a funny real-life situation, students will recall it", "try": "If a teacher ______, students will ______."}, {"pattern": "Cleft with what", "use": "What + subject + verb + is ...", "example": "What students remember most is how a lesson made them feel", "try": "What students remember most is ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Things & ideas"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000040', 1040, 'Topic 40', 'Noisy place', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 40, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a noisy place you have been to", "bullets": ["where it was", "when you went there", "what kinds of noise you could hear", "and explain how you felt about the noise"], "explain": "", "notes": ["Where", "When", "Noise", "Feelings"], "rounding": {"q": "Would you like to go back there?", "model": {"answer": "Definitely, but at a quieter hour, perhaps. The bazaar is the best place to feel the real pulse of the city, and it would be a shame to miss it just because it’s loud.", "phrases": [], "grammar": []}}, "model": {"answer": "Let me tell you about the noisiest place I’ve ever been to: Chorsu Bazaar in Tashkent on a Saturday morning. I went there last spring, a few days before Navruz, with my cousin Aziza, who wanted to buy dried fruit and ingredients for her family’s celebration. We arrived around nine, just as the market was in full swing. The first thing that hit me was the sheer volume. Vendors were calling out their prices at the top of their voices, each one trying to be heard over the next. Somewhere behind us, a loudspeaker was blasting pop music, and motorbikes kept weaving through the narrow aisles, honking at anyone in their way. Beneath it all ran a constant hum of bargaining and laughter, with the clang of a metalworker hammering a copper pot every few seconds. Not a single minute passed without a new sound competing for my attention. At first I felt completely overwhelmed. I had to shout just to make myself heard, and I was on edge because I kept worrying about losing Aziza in the crowd. Strangely, though, after half an hour I had got used to it, and the noise began to feel like energy rather than a nuisance. It reminded me that a city’s sounds are part of its character. As much as I love peace and quiet, I’d choose that kind of buzz over a silent supermarket any day, although I did need a quiet cup of tea afterwards.", "sections": [{"label": "Where", "text": "Let me tell you about the noisiest place I’ve ever been to: Chorsu Bazaar in Tashkent on a Saturday morning."}, {"label": "When", "text": "I went there last spring, a few days before Navruz, with my cousin Aziza, who wanted to buy dried fruit and ingredients for her family’s celebration. We arrived around nine, just as the market was in full swing."}, {"label": "Noise", "text": "The first thing that hit me was the sheer volume. Vendors were calling out their prices at the top of their voices, each one trying to be heard over the next. Somewhere behind us, a loudspeaker was blasting pop music, and motorbikes kept weaving through the narrow aisles, honking at anyone in their way. Beneath it all ran a constant hum of bargaining and laughter, with the clang of a metalworker hammering a copper pot every few seconds. Not a single minute passed without a new sound competing for my attention."}, {"label": "Feelings", "text": "At first I felt completely overwhelmed. I had to shout just to make myself heard, and I was on edge because I kept worrying about losing Aziza in the crowd. Strangely, though, after half an hour I had got used to it, and the noise began to feel like energy rather than a nuisance. It reminded me that a city’s sounds are part of its character. As much as I love peace and quiet, I’d choose that kind of buzz over a silent supermarket any day, although I did need a quiet cup of tea afterwards."}], "phrases": [["in full swing", "at the busiest, most active stage"], ["the sheer volume", "the extreme loudness"], ["calling out", "shouting to get attention"], ["at the top of their voices", "as loudly as possible"], ["be heard over", "make your voice clear above other noise"], ["blasting", "playing extremely loudly"], ["weaving through", "moving along by turning around obstacles"], ["constant hum", "continuous low background noise"], ["competing for my attention", "trying to get noticed at the same time"], ["completely overwhelmed", "feeling unable to cope because of too much"], ["make myself heard", "be understood despite noise"], ["on edge", "nervous and tense"], ["got used to", "became familiar and comfortable with"], ["buzz", "an exciting, lively atmosphere"]], "grammar": [{"pattern": "Relative clause with who", "use": "person, who + verb", "example": "with my cousin Aziza, who wanted to buy dried fruit", "try": "with my friend ______, who ______."}, {"pattern": "Past continuous with kept", "use": "kept + -ing", "example": "motorbikes kept weaving through the narrow aisles", "try": "______ kept ______ing."}, {"pattern": "Participle clause", "use": "-ing phrase", "example": "honking at anyone in their way", "try": "______ing at ______."}, {"pattern": "Inverted structure for emphasis", "use": "Beneath it all + verb + subject", "example": "Beneath it all ran a constant hum of bargaining and laughter", "try": "Beneath it all ran ______."}, {"pattern": "Past perfect", "use": "had + past participle", "example": "after half an hour I had got used to it", "try": "After ______, I had ______."}, {"pattern": "As much as (concession)", "use": "As much as + clause, main clause", "example": "As much as I love peace and quiet, I’d choose that kind of buzz", "try": "As much as I ______, I’d ______."}]}}, "part3": {"intro": "We’ve been talking about a noisy place you have been to, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Noisy place", "title": "Noisy place", "questions": [{"q": "Is it good for children to make noise?", "model": {"answer": "Within reason, yes. Noise is often a sign that children are playing and exploring, and they need to let off steam to develop properly. A child forced to stay silent all day would bottle up their energy and probably become anxious. That said, they also have to learn consideration: shouting in the yard is fine, but not at night or near a hospital.", "phrases": [["within reason", "as long as it is not excessive"], ["let off steam", "release extra energy or feelings"], ["bottle up", "hide or hold in emotions"], ["consideration", "care for other people’s feelings"], ["that said", "however"]], "grammar": [{"pattern": "Past participle phrase", "use": "noun + past participle + would", "example": "A child forced to stay silent all day would bottle up their energy", "try": "A child forced to ______ would ______."}, {"pattern": "Concession", "use": "That said, ...", "example": "That said, they also have to learn consideration", "try": "That said, ______."}]}}, {"q": "What kinds of noise do people hear in their daily lives?", "model": {"answer": "Traffic is the main one in cities: engines, horns and the occasional siren. Add to that construction work, neighbours’ music and the background chatter of buses and offices. At home, there’s plenty of self-inflicted noise too, from televisions and phone notifications. Most people learn to tune it out, but a constant din can still be draining by the end of the day.", "phrases": [["the occasional siren", "a siren heard now and then"], ["background chatter", "people talking quietly in the distance"], ["self-inflicted", "caused by ourselves"], ["tune it out", "stop noticing it"], ["a constant din", "an unpleasant continuous loud noise"]], "grammar": [{"pattern": "Add to that", "use": "Add to that + noun", "example": "Add to that construction work, neighbours’ music", "try": "Add to that ______."}, {"pattern": "by the end of", "use": "by the end of + time", "example": "by the end of the day", "try": "By the end of ______, I’m ______."}]}}, {"q": "Which is noisier, a city or the countryside?", "model": {"answer": "A city, by a wide margin, though the noise is different. In cities it’s relentless: traffic, building sites, crowds. The countryside has its own sounds, such as roosters at dawn or dogs barking, but they’re natural and come in waves rather than all day. Interestingly, some villagers find the city unbearable, while many city dwellers can’t sleep in the countryside because it’s simply too quiet.", "phrases": [["by a wide margin", "by a large difference"], ["relentless", "never stopping"], ["building sites", "places where construction work is done"], ["come in waves", "happen at intervals, not continuously"], ["city dwellers", "people who live in cities"]], "grammar": [{"pattern": "Superlative / comparative", "use": "comparative + noun, though ...", "example": "A city, by a wide margin, though the noise is different", "try": "______, by a wide margin, though ______."}, {"pattern": "Contrast with while", "use": "clause 1, while clause 2", "example": "some villagers find the city unbearable, while many city dwellers can’t sleep", "try": "Some people ______, while others ______."}]}}, {"q": "Why do some people not mind noise while others find it very irritating?", "model": {"answer": "It comes down to upbringing and sensitivity. Someone who grew up in a busy household is used to it, whereas a person raised in a quiet village may find the same sound jarring. Context matters as well. Music at a wedding feels enjoyable, but the same volume at midnight next door is infuriating, because we feel we have no control over it.", "phrases": [["comes down to", "depends mainly on"], ["sensitivity", "how easily someone is affected"], ["is used to", "is accustomed to"], ["jarring", "unpleasant and shocking"], ["next door", "in the neighbouring house or flat"]], "grammar": [{"pattern": "Relative clause", "use": "someone who + past simple", "example": "Someone who grew up in a busy household is used to it", "try": "Someone who ______ is used to ______."}, {"pattern": "Reduced relative clause", "use": "a person + past participle", "example": "a person raised in a quiet village", "try": "a person raised in ______."}]}}, {"q": "What are the effects of noise pollution on people’s health?", "model": {"answer": "Prolonged exposure can wear people down. Loud surroundings are linked to stress, poor sleep and difficulty concentrating, and over time these problems can take a toll on general health. Children studying near busy roads often struggle to focus, which affects their results at school. Hearing can also be permanently damaged by constant loud sound, such as music played through headphones at full volume.", "phrases": [["wear people down", "make people tired and less able to cope"], ["are linked to", "be connected with, as cause or result"], ["take a toll on", "have a bad effect on"], ["struggle to focus", "find it hard to concentrate"], ["at full volume", "as loud as possible"]], "grammar": [{"pattern": "Passive", "use": "can + be + past participle", "example": "Hearing can also be permanently damaged by constant loud sound", "try": "______ can be damaged by ______."}, {"pattern": "Participle reduced relative", "use": "such as + noun + past participle", "example": "such as music played through headphones", "try": "such as music played ______."}]}}, {"q": "What can be done to reduce noise in cities?", "model": {"answer": "A combination of rules and design would work best. Authorities could enforce limits on night-time construction and loud vehicles, while planners could create green belts and sound barriers along main roads. More trees would help absorb sound, too. If more people used public transport or electric vehicles, traffic noise would fall considerably. Individuals can do their bit too, simply by keeping the volume down after dark.", "phrases": [["enforce limits", "make sure rules are obeyed"], ["green belts", "areas of trees and grass"], ["sound barriers", "walls that block noise"], ["fall considerably", "go down a lot"], ["do their bit", "contribute personally"]], "grammar": [{"pattern": "Second conditional", "use": "If + past simple, would + verb", "example": "If more people used public transport or electric vehicles, traffic noise would fall considerably", "try": "If more people ______, ______ would ______."}, {"pattern": "Modal could", "use": "could + verb", "example": "Authorities could enforce limits on night-time construction", "try": "Authorities could ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Places"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000041', 1041, 'Topic 41', 'Good service', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 41, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe an occasion when you received good service from a company or a shop", "bullets": ["what the company or shop was", "what the service was", "who helped you", "and explain why you think the service was good"], "explain": "", "notes": ["What", "Service", "Who", "Why"], "rounding": {"q": "Would you go back to the same shop?", "model": {"answer": "Without a doubt. For my next suit, I wouldn’t even think of going anywhere else, because that kind of trust is rare and well worth keeping.", "phrases": [], "grammar": []}}, "model": {"answer": "A good example that springs to mind is a small tailoring shop near my university, where I had a suit made for my graduation last June. It’s run by Mr Karimov, a man in his sixties who always has a measuring tape draped around his neck. The service itself was a made-to-measure suit, which he promised to finish within two weeks. From my first visit, he took his time. He asked what the occasion was, measured me twice, and even talked me out of a flashy fabric, saying I’d be uncomfortable in it by midday. His advice turned out to be spot on. The day before the ceremony, I tried the jacket on at home and noticed that one sleeve was slightly longer than the other. I rushed back in a panic, fully expecting to be told it was too late. Instead, Mr Karimov said, “Give me an hour,” sat down at his old sewing machine and fixed it while I waited. He wouldn’t accept a penny extra. What made the service so good was the combination of skill and genuine care. He went the extra mile, he was honest rather than pushy, and he owned up to the mistake without making excuses. Had he simply apologised and sent me away, I would probably never have gone back. As it is, I’ve recommended him to half my class. To me, good service is not about politeness alone; it’s about taking responsibility for the result.", "sections": [{"label": "What", "text": "A good example that springs to mind is a small tailoring shop near my university, where I had a suit made for my graduation last June. It’s run by Mr Karimov, a man in his sixties who always has a measuring tape draped around his neck."}, {"label": "Service", "text": "The service itself was a made-to-measure suit, which he promised to finish within two weeks. From my first visit, he took his time. He asked what the occasion was, measured me twice, and even talked me out of a flashy fabric, saying I’d be uncomfortable in it by midday. His advice turned out to be spot on."}, {"label": "Who", "text": "The day before the ceremony, I tried the jacket on at home and noticed that one sleeve was slightly longer than the other. I rushed back in a panic, fully expecting to be told it was too late. Instead, Mr Karimov said, “Give me an hour,” sat down at his old sewing machine and fixed it while I waited. He wouldn’t accept a penny extra."}, {"label": "Why", "text": "What made the service so good was the combination of skill and genuine care. He went the extra mile, he was honest rather than pushy, and he owned up to the mistake without making excuses. Had he simply apologised and sent me away, I would probably never have gone back. As it is, I’ve recommended him to half my class. To me, good service is not about politeness alone; it’s about taking responsibility for the result."}], "phrases": [["springs to mind", "comes into your thoughts quickly"], ["draped around", "hanging loosely around"], ["made-to-measure", "made specially to fit one person"], ["took his time", "did not rush"], ["talked me out of", "persuaded me not to do"], ["turned out to be spot on", "proved to be exactly right"], ["in a panic", "feeling sudden fear and worry"], ["a penny extra", "any extra money at all"], ["genuine care", "real, sincere concern"], ["went the extra mile", "made more effort than expected"], ["pushy", "trying too hard to persuade"], ["owned up to", "admitted"], ["making excuses", "giving reasons to avoid blame"]], "grammar": [{"pattern": "Relative clause with who", "use": "a man + in his sixties + who", "example": "a man in his sixties who always has a measuring tape draped around his neck", "try": "a man in his ______ who ______."}, {"pattern": "Present perfect", "use": "have/has + past participle", "example": "I’ve recommended him to half my class", "try": "I’ve ______ him to ______."}, {"pattern": "Past participle (causative)", "use": "have + object + past participle", "example": "I had a suit made for my graduation", "try": "I had a ______ made for ______."}, {"pattern": "Fully expecting (participle)", "use": "-ing clause of expectation", "example": "fully expecting to be told it was too late", "try": "______, fully expecting to be told ______."}, {"pattern": "Third conditional (inverted)", "use": "Had + subject + past participle, would have ...", "example": "Had he simply apologised and sent me away, I would probably never have gone back", "try": "Had he ______, I would never have ______."}, {"pattern": "Cleft with what", "use": "What + verb + was ...", "example": "What made the service so good was the combination of skill and genuine care", "try": "What made it good was ______."}]}}, "part3": {"intro": "We’ve been talking about an occasion when you received good service from a company or a shop, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Good service", "title": "Good service", "questions": [{"q": "What makes a shop or company provide good service?", "model": {"answer": "Well-trained, motivated staff, first of all. Employees who know the product and feel valued by their employer will naturally treat customers better. Equally important is a culture of listening to complaints and fixing them quickly. Companies that put customers first tend to enjoy repeat business, because people will happily pay a little more for a hassle-free experience. Good service often reflects how a business treats its own people.", "phrases": [["well-trained", "having received good instruction"], ["feel valued", "feel respected and appreciated"], ["listening to complaints", "paying attention to criticism"], ["put customers first", "treat customers as the top priority"], ["repeat business", "customers who come back again"]], "grammar": [{"pattern": "Relative clause", "use": "Employees who + verb", "example": "Employees who know the product and feel valued by their employer will naturally treat customers better", "try": "Employees who ______ will ______."}, {"pattern": "Tend to", "use": "tend to + verb", "example": "tend to enjoy repeat business", "try": "Companies that ______ tend to ______."}]}}, {"q": "What are the advantages and disadvantages of shopping at a big shopping centre?", "model": {"answer": "The main advantage is convenience: you can buy clothes, eat lunch and see a film under one roof, in air-conditioning during summer. On the downside, the crowds and the temptation to overspend can be exhausting. Prices may also be higher than in a local market. I tend to go with a list; otherwise I leave with things I never intended to buy.", "phrases": [["under one roof", "in a single building"], ["on the downside", "as a disadvantage"], ["the temptation to overspend", "the desire to spend too much"], ["go with a list", "take a shopping list with you"], ["things I never intended to buy", "unplanned purchases"]], "grammar": [{"pattern": "Comparative", "use": "adjective + than", "example": "Prices may also be higher than in a local market", "try": "Prices may be ______ than ______."}, {"pattern": "Otherwise", "use": "..., otherwise + clause", "example": "otherwise I leave with things I never intended to buy", "try": "______; otherwise ______."}]}}, {"q": "Why are shopping malls so popular?", "model": {"answer": "Because they offer far more than shopping. For many families, a mall is an all-in-one destination, with restaurants, playgrounds and cinemas, especially where winters are cold and summers scorching. They are also a safe, clean place for teenagers to meet friends away from the traffic. Add attractive discounts and international brands under one roof, and it’s easy to see why malls draw such crowds.", "phrases": [["far more than", "much more than"], ["all-in-one", "combining many things in one"], ["scorching", "extremely hot"], ["a safe, clean place", "a secure, tidy space"], ["draw such crowds", "attract so many people"]], "grammar": [{"pattern": "Imperative + and", "use": "Imperative, and + clause", "example": "Add attractive discounts and international brands under one roof, and it’s easy to see why", "try": "Add ______, and it’s easy to see why ______."}, {"pattern": "Indirect question", "use": "it’s easy to see why + clause", "example": "it’s easy to see why malls draw such crowds", "try": "It’s easy to see why ______."}]}}, {"q": "What are the differences between shopping online and shopping in a store?", "model": {"answer": "The difference is mainly touch and speed. Online, you can compare prices in minutes and have a parcel delivered to your door, but you can’t try anything on or check the quality. In a store, you get instant gratification and advice from a real person, though the choice is more limited. For electronics I prefer online; for clothes, I’d rather see things with my own eyes.", "phrases": [["touch and speed", "physical contact with goods and quick results"], ["try anything on", "put on clothes to see if they fit"], ["instant gratification", "getting what you want immediately"], ["advice from a real person", "help from a human, not a website"], ["with my own eyes", "personally, not through a picture"]], "grammar": [{"pattern": "Would rather", "use": "I’d rather + verb", "example": "I’d rather see things with my own eyes", "try": "I’d rather ______."}, {"pattern": "Contrast with though", "use": "clause, though + clause", "example": "though the choice is more limited", "try": "______, though ______."}]}}, {"q": "Are small local shops still important?", "model": {"answer": "Absolutely, and not only economically. They give a neighbourhood its character, and the owner often knows customers by name, which creates a trust that big chains struggle to match. Local shops also create jobs nearby and keep money circulating in the community. If they disappeared, many elderly people, who can’t easily travel or order online, would be left without anywhere convenient to buy essentials.", "phrases": [["give a neighbourhood its character", "make an area unique"], ["knows customers by name", "be personally familiar with shoppers"], ["struggle to match", "find it hard to equal"], ["keep money circulating", "keep money moving within the area"], ["buy essentials", "buy basic necessary goods"]], "grammar": [{"pattern": "Not only (ellipsis)", "use": "not only + adverb", "example": "not only economically", "try": "Not only ______, but also ______."}, {"pattern": "Second conditional", "use": "If + past simple, would be left", "example": "If they disappeared, many elderly people, who can’t easily travel or order online, would be left without anywhere convenient", "try": "If they disappeared, ______ would ______."}]}}, {"q": "Does consumerism help or harm a country’s economy?", "model": {"answer": "It depends on the degree. Up to a point, spending fuels the economy: shops hire staff, factories produce more and the government collects more tax. But a culture of buying things we don’t need can push households into debt and waste resources. A country whose growth relies on constant consumption is vulnerable when conditions change. Balance is the key, and governments should encourage saving too.", "phrases": [["it depends on the degree", "the answer changes according to how much"], ["up to a point", "to a limited extent"], ["fuels the economy", "provides energy for economic growth"], ["push households into debt", "force families to owe money"], ["is vulnerable", "is easily harmed"]], "grammar": [{"pattern": "Relative clause with whose", "use": "A country whose + noun + verb", "example": "A country whose growth relies on constant consumption is vulnerable", "try": "A country whose ______ relies on ______ is ______."}, {"pattern": "Colon list", "use": "clause: A, B and C", "example": "shops hire staff, factories produce more and the government collects more tax", "try": "______ hire staff, ______ produce more and ______."}]}}, {"q": "How is customer service different now from what it was in the past?", "model": {"answer": "It has become faster but less personal. A generation ago, you would walk into a shop, and the owner would know you and sort out any problem on the spot. Today, we’re more likely to chat to a bot or send a message and wait for a reply. On the plus side, round-the-clock support is now common, and complaints can often be resolved without leaving home, which saves everyone time.", "phrases": [["a generation ago", "about thirty years ago"], ["sort out", "solve a problem"], ["on the spot", "immediately, at that moment"], ["on the plus side", "as a positive point"], ["round-the-clock", "available twenty-four hours a day"]], "grammar": [{"pattern": "Would for past habits", "use": "would + verb", "example": "you would walk into a shop, and the owner would know you", "try": "You would ______, and the owner would ______."}, {"pattern": "Present perfect", "use": "has become", "example": "It has become faster but less personal", "try": "It has become ______ but ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Events & experiences"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000042', 1042, 'Topic 42', 'Something you saved for', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 42, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe something that you saved money to buy", "bullets": ["what it was", "how long it took you to save enough money to buy it", "why you wanted to buy this thing", "how you felt when you bought it"], "explain": "", "notes": ["What", "How Long", "Why", "Feelings"], "rounding": {"q": "Do you think saving up for something makes it more valuable?", "model": {"answer": "In my experience, yes. When you’ve given up other things to afford something, you appreciate it more, and you think twice before treating it carelessly.", "phrases": [], "grammar": []}}, "model": {"answer": "The first thing that comes to mind is my laptop, which I saved up for during my first year at university. Until then, I’d been doing assignments on a sluggish old desktop at my uncle’s house, an hour’s bus ride from my dormitory. It took me about eight months to scrape together enough money. I tutored two schoolchildren in English twice a week, and I cut back on things like takeaway coffee and taxis, which wasn’t easy. I kept the price in a note on my phone, and every time I was tempted to splurge on something silly, I looked at that number and thought twice. I wanted it because my old computer kept crashing whenever a deadline was close. I once lost an entire essay at midnight, a lesson I’d rather not repeat. A reliable laptop would let me work at the library, and I also needed to run statistical software for my economics course. When I finally walked out of the shop with the box under my arm, I felt a rush of pride, far more than I’d expected. It wasn’t even the top model, but every key reminded me of the effort behind it. Perhaps because I’d earned it myself, I looked after it carefully, and it’s still going strong four years later. If my parents had simply bought it for me, I doubt I’d have valued it nearly as much. To my mind, delayed gratification is part of what makes a purchase feel like a reward.", "sections": [{"label": "What", "text": "The first thing that comes to mind is my laptop, which I saved up for during my first year at university. Until then, I’d been doing assignments on a sluggish old desktop at my uncle’s house, an hour’s bus ride from my dormitory."}, {"label": "How Long", "text": "It took me about eight months to scrape together enough money. I tutored two schoolchildren in English twice a week, and I cut back on things like takeaway coffee and taxis, which wasn’t easy. I kept the price in a note on my phone, and every time I was tempted to splurge on something silly, I looked at that number and thought twice."}, {"label": "Why", "text": "I wanted it because my old computer kept crashing whenever a deadline was close. I once lost an entire essay at midnight, a lesson I’d rather not repeat. A reliable laptop would let me work at the library, and I also needed to run statistical software for my economics course."}, {"label": "Feelings", "text": "When I finally walked out of the shop with the box under my arm, I felt a rush of pride, far more than I’d expected. It wasn’t even the top model, but every key reminded me of the effort behind it. Perhaps because I’d earned it myself, I looked after it carefully, and it’s still going strong four years later. If my parents had simply bought it for me, I doubt I’d have valued it nearly as much. To my mind, delayed gratification is part of what makes a purchase feel like a reward."}], "phrases": [["saved up for", "kept money over time in order to buy"], ["sluggish", "slow and not working well"], ["scrape together", "manage to collect with difficulty"], ["cut back on", "spend less on"], ["splurge on", "spend a lot of money on something unnecessary"], ["thought twice", "reconsidered before acting"], ["kept crashing", "repeatedly stopped working suddenly"], ["a lesson I’d rather not repeat", "an unpleasant experience I want to avoid again"], ["a rush of pride", "a sudden strong feeling of being proud"], ["still going strong", "continuing to work well after a long time"], ["looked after", "took care of"], ["delayed gratification", "waiting for a reward rather than having it immediately"]], "grammar": [{"pattern": "Past perfect continuous", "use": "had been + -ing", "example": "I’d been doing assignments on a sluggish old desktop", "try": "I’d been ______ing for ______."}, {"pattern": "Tempted to + time clause", "use": "every time + clause, main clause", "example": "every time I was tempted to splurge on something silly, I looked at that number", "try": "Every time I was tempted to ______, I ______."}, {"pattern": "Relative clause with which", "use": "..., which + verb", "example": "which wasn’t easy", "try": "..., which wasn’t ______."}, {"pattern": "Reduced relative (apposition)", "use": "noun phrase, a + noun phrase", "example": "a lesson I’d rather not repeat", "try": "______, a lesson I’d ______."}, {"pattern": "Third conditional", "use": "If + past perfect, would have + past participle", "example": "If my parents had simply bought it for me, I doubt I’d have valued it nearly as much", "try": "If my parents had ______, I doubt I’d have ______."}, {"pattern": "Perhaps because", "use": "Perhaps because + clause, main clause", "example": "Perhaps because I’d earned it myself, I looked after it carefully", "try": "Perhaps because ______, I ______."}]}}, "part3": {"intro": "We’ve been talking about something that you saved money to buy, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Something you saved for", "title": "Something you saved for", "questions": [{"q": "Why is it important to teach children to save money?", "model": {"answer": "Because it builds self-control, a skill that lasts a lifetime. A child who learns to wait for a toy, rather than getting it immediately, understands that things have value and that choices involve trade-offs. If children never learn this, they may become adults who spend impulsively and live beyond their means. Starting small, with a simple piggy bank, is enough to lay the foundations.", "phrases": [["builds self-control", "develops the ability to control impulses"], ["trade-offs", "situations where you must give up one thing for another"], ["spend impulsively", "buy things without thinking"], ["live beyond their means", "spend more than they earn"], ["lay the foundations", "start the basics for future development"]], "grammar": [{"pattern": "Relative clause (apposition)", "use": "noun phrase, a skill that + verb", "example": "self-control, a skill that lasts a lifetime", "try": "______, a skill that ______."}, {"pattern": "Conditional with never", "use": "If + subject + never learn, they may ...", "example": "If children never learn this, they may become adults who spend impulsively", "try": "If children never learn ______, they may ______."}]}}, {"q": "Who should teach children how to manage money, schools or parents?", "model": {"answer": "Ideally both, though I’d lean towards parents. Children learn about money by watching how household finances work, such as how a family budgets or discusses a big purchase. Schools can add structure through lessons on budgeting and interest, which many parents lack the confidence to explain. So it’s a partnership: parents set an example at home, and teachers reinforce it with theory.", "phrases": [["lean towards", "slightly prefer"], ["household finances", "the money matters of a family"], ["lack the confidence", "not feel sure enough"], ["set an example", "behave in a way others can copy"], ["reinforce", "strengthen"]], "grammar": [{"pattern": "Gerund after by", "use": "by + -ing", "example": "Children learn about money by watching how household finances work", "try": "Children learn by ______ing."}, {"pattern": "Non-defining which", "use": "..., which + clause", "example": "which many parents lack the confidence to explain", "try": "..., which many people ______."}]}}, {"q": "Why do some people find it hard to save money?", "model": {"answer": "Several things get in the way. Low or irregular income makes it tough, obviously, but even well-paid people struggle, partly because advertising constantly tempts us and buying online is effortless. Many also fall into the trap of instant gratification, thinking, “I deserve this.” Without a clear goal, saving feels like a sacrifice, whereas a specific target gives it a sense of purpose.", "phrases": [["get in the way", "prevent or block"], ["irregular income", "money that arrives at uneven times"], ["fall into the trap of", "make the mistake of"], ["instant gratification", "getting pleasure immediately"], ["a sense of purpose", "a feeling of having a reason"]], "grammar": [{"pattern": "Without + noun", "use": "Without + noun, clause", "example": "Without a clear goal, saving feels like a sacrifice", "try": "Without a ______, ______ feels like ______."}, {"pattern": "Participle clause", "use": "verb + thinking", "example": "fall into the trap of instant gratification, thinking", "try": "______, thinking, “______.”"}]}}, {"q": "What is the best way to save money?", "model": {"answer": "Paying yourself first is the most reliable method: as soon as your salary arrives, set aside a fixed percentage before spending anything. Automating the transfer helps because it takes willpower out of the equation. It’s also worth tracking your spending for a month, because you’ll probably find small leaks, like daily snacks, that quietly eat into your budget. Making it a habit matters more than the amount.", "phrases": [["paying yourself first", "saving before you spend"], ["set aside", "keep money for a purpose"], ["takes willpower out of the equation", "removes the need for self-discipline"], ["tracking your spending", "recording what you spend"], ["eat into", "gradually use up"]], "grammar": [{"pattern": "As soon as", "use": "as soon as + present simple", "example": "as soon as your salary arrives, set aside a fixed percentage", "try": "As soon as ______, ______."}, {"pattern": "Superlative", "use": "the most + adjective + noun", "example": "the most reliable method", "try": "It’s the most ______ way to ______."}]}}, {"q": "Do people in your country like to save money?", "model": {"answer": "Generally, yes. Saving is seen as a sign of responsibility, and many families put money aside for weddings, education and emergencies. Older generations, in particular, tend to be cautious with money, having lived through uncertain times. Younger people are more inclined to spend on experiences and gadgets, though, so the habit is slowly shifting, especially in big cities, where social media encourages constant spending.", "phrases": [["a sign of responsibility", "evidence of being sensible"], ["put money aside", "save money"], ["cautious with money", "careful about spending"], ["more inclined to", "more likely to"], ["is slowly shifting", "is gradually changing"]], "grammar": [{"pattern": "Passive", "use": "is/are + seen as", "example": "Saving is seen as a sign of responsibility", "try": "______ is seen as ______."}, {"pattern": "Comparative", "use": "more + adjective + to", "example": "Younger people are more inclined to spend on experiences and gadgets", "try": "______ are more inclined to ______."}]}}, {"q": "What are the consequences of not saving money?", "model": {"answer": "The most obvious is vulnerability: without a cushion, a sudden medical bill or job loss can throw your life into chaos. People may be forced to borrow at high interest, which leads to a cycle of debt. In the long term, you can’t plan for big goals such as buying a home or retiring comfortably. It also brings constant stress, even when things are going well.", "phrases": [["a cushion", "a reserve of money for emergencies"], ["throw your life into chaos", "make life suddenly disorganised"], ["a cycle of debt", "a repeating pattern of borrowing"], ["in the long term", "over many years"], ["retiring comfortably", "stopping work with enough money"]], "grammar": [{"pattern": "Passive", "use": "be forced to + verb", "example": "People may be forced to borrow at high interest", "try": "People may be forced to ______."}, {"pattern": "Without as condition", "use": "without + noun, can + verb", "example": "without a cushion, a sudden medical bill or job loss can throw your life into chaos", "try": "Without ______, ______ can ______."}]}}, {"q": "Do you agree that the more people save, the better their lives will be?", "model": {"answer": "Not necessarily. Saving is sensible up to a point, but the more people hoard money out of fear, the less they enjoy life today. What matters is balance, since spending on experiences, health and relationships also enriches life. Someone who saves aggressively but never takes a holiday may end up wealthy yet exhausted. I’d support saving, but I wouldn’t treat it as the only measure of wellbeing.", "phrases": [["up to a point", "to a limited extent"], ["hoard", "collect and keep a lot of something"], ["out of fear", "because of fear"], ["enriches life", "makes life fuller and more satisfying"], ["end up wealthy yet exhausted", "finally become rich but very tired"]], "grammar": [{"pattern": "The more ... the less", "use": "The more + clause, the less + clause", "example": "the more people hoard money out of fear, the less they enjoy life today", "try": "The more ______, the less ______."}, {"pattern": "Cleft with what", "use": "What matters is + noun", "example": "What matters is balance", "try": "What matters is ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Things & ideas"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000043', 1043, 'Topic 43', 'Skill you learned in childhood', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 43, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a skill you learned in your childhood", "bullets": ["what the skill was", "who taught you or how you learned it", "how long it took you to learn it", "and explain why this skill is useful to you"], "explain": "", "notes": ["What", "Who", "How Long", "Why"], "rounding": {"q": "Do you think everyone should learn to swim?", "model": {"answer": "Yes, I do. It’s a basic safety skill, and since so many holidays involve water, children should really be taught it at school, not just by their families.", "phrases": [], "grammar": []}}, "model": {"answer": "The first thing that comes to mind is swimming, which I picked up the hard way, because I was terrified of water until I was about seven. It was my uncle Farhod who taught me. He worked as a lifeguard at a pool in Fergana, where we spent every summer, and, to be fair, he never threw me in at the deep end. Instead, he started by getting me used to the water: blowing bubbles, then floating on my back with his hand barely touching me. It took roughly two summers to get the hang of the front crawl. I remember swallowing half the pool during the first week, and there were days when I was ready to throw in the towel, but he kept egging me on. “Nobody ever drowned from being embarrassed,” he used to say. By the end of the second summer, I could swim a full length without stopping, and I felt incredibly proud. Looking back, it’s one of the most useful things I’ve ever learned, and it gave me real confidence. It keeps me fit, and I still go twice a week to clear my head after a long day of lectures. What’s more, had I never learned, I couldn’t have enjoyed the holiday I took in Turkey last year. Once you’ve learned, it becomes second nature, and I’d love to pass it on to my own children one day.", "sections": [{"label": "What", "text": "The first thing that comes to mind is swimming, which I picked up the hard way, because I was terrified of water until I was about seven."}, {"label": "Who", "text": "It was my uncle Farhod who taught me. He worked as a lifeguard at a pool in Fergana, where we spent every summer, and, to be fair, he never threw me in at the deep end. Instead, he started by getting me used to the water: blowing bubbles, then floating on my back with his hand barely touching me."}, {"label": "How Long", "text": "It took roughly two summers to get the hang of the front crawl. I remember swallowing half the pool during the first week, and there were days when I was ready to throw in the towel, but he kept egging me on. “Nobody ever drowned from being embarrassed,” he used to say. By the end of the second summer, I could swim a full length without stopping, and I felt incredibly proud."}, {"label": "Why", "text": "Looking back, it’s one of the most useful things I’ve ever learned, and it gave me real confidence. It keeps me fit, and I still go twice a week to clear my head after a long day of lectures. What’s more, had I never learned, I couldn’t have enjoyed the holiday I took in Turkey last year. Once you’ve learned, it becomes second nature, and I’d love to pass it on to my own children one day."}], "phrases": [["pick up (a skill)", "learn something without formal lessons"], ["to be fair", "used to make a balanced, honest point"], ["throw (someone) in at the deep end", "make someone face something difficult with no preparation"], ["get (someone) used to", "help someone become familiar with something"], ["get the hang of", "learn how to do something"], ["throw in the towel", "give up"], ["egg (someone) on", "keep encouraging someone to continue"], ["keep (someone) fit", "help someone stay healthy and in shape"], ["clear your head", "relax and stop thinking about worries"], ["second nature", "something you do automatically because you know it so well"], ["pass (something) on", "teach or give something to the next generation"]], "grammar": [{"pattern": "Cleft sentence", "use": "It was + person + who + past simple", "example": "It was my uncle Farhod who taught me", "try": "It was my ______ who taught me to ______."}, {"pattern": "Until + past simple", "use": "was + adjective + until + age", "example": "I was terrified of water until I was about seven", "try": "I was afraid of ______ until I was ______."}, {"pattern": "Started by + -ing", "use": "he started by + -ing", "example": "he started by getting me used to the water", "try": "She started by ______ing ______."}, {"pattern": "Past habit with used to", "use": "used to + verb (a repeated saying)", "example": "he used to say", "try": "My teacher used to say, “______.”"}, {"pattern": "Kept + -ing", "use": "kept + -ing = did it again and again", "example": "he kept egging me on", "try": "My coach kept ______ me."}, {"pattern": "Mixed conditional with inversion", "use": "Had + subject + past participle, … couldn’t have + past participle", "example": "had I never learned, I couldn’t have enjoyed the holiday I took in Turkey last year", "try": "Had I never ______, I couldn’t have ______."}]}}, "part3": {"intro": "We’ve been talking about a skill you learned in your childhood, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Skill you learned in childhood", "title": "Skill you learned in childhood", "questions": [{"q": "What is the difference between the way children learn and the way adults learn?", "model": {"answer": "Children learn by doing, whereas adults tend to learn by analysing. A child will happily copy a swimming stroke and make mistakes without worrying, because they have nothing to lose. Adults, by contrast, want to understand why something works before trying it, and they’re often self-conscious about failing. That’s why, given the same amount of practice, kids usually pick up a skill faster, while adults remember it more deliberately.", "phrases": [["make mistakes", "do things wrongly while learning"], ["nothing to lose", "no risk of being harmed by failing"], ["self-conscious", "worried about how others see you"], ["pick up", "learn easily"], ["deliberately", "with careful, conscious thought"]], "grammar": [{"pattern": "whereas for contrast", "use": "A, whereas B", "example": "Children learn by doing, whereas adults tend to learn by analysing", "try": "Children ______, whereas adults ______."}, {"pattern": "Participle clause", "use": "given + noun, + clause", "example": "given the same amount of practice, kids usually pick up a skill faster", "try": "Given ______, most people ______."}]}}, {"q": "Is it better to learn a skill in a group or individually?", "model": {"answer": "It depends on the skill. For something like football or a language, a group is better, because you’re motivated by the people around you and you learn from watching their mistakes. But for skills that demand concentration, such as the piano, I’d lean towards one-to-one lessons, where a teacher can correct you straight away. Ideally, you’d combine the two: practise alone, then test yourself in a group.", "phrases": [["motivated by", "encouraged to try harder because of"], ["lean towards", "prefer slightly"], ["correct", "fix someone’s mistakes"], ["combine", "use two things together"], ["test yourself", "check how well you can do something"]], "grammar": [{"pattern": "Relative clause with where", "use": "place + where + clause", "example": "one-to-one lessons, where a teacher can correct you straight away", "try": "______, where ______ can ______."}, {"pattern": "Skills + such as", "use": "skills that + verb, such as + noun", "example": "skills that demand concentration, such as the piano", "try": "Skills that ______, such as ______, ______."}]}}, {"q": "Which skills should children learn at an early age?", "model": {"answer": "Swimming and basic first aid come first, in my view, since they could save a life. Beyond that, I’d add money management: if children learned how to save from a young age, they’d be far better prepared for adult life. Social skills matter too, particularly working in a team and handling disagreements, which no textbook can really teach. These are all things children absorb easily when they’re young.", "phrases": [["save a life", "prevent someone from dying"], ["money management", "the ability to budget and save"], ["work in a team", "cooperate with others toward a shared goal"], ["handle disagreements", "deal calmly with conflict"], ["absorb", "take in and learn naturally"]], "grammar": [{"pattern": "Second conditional", "use": "if + past simple, would + verb", "example": "if children learned how to save from a young age, they’d be far better prepared for adult life", "try": "If children ______, they’d ______."}, {"pattern": "Relative clause with which", "use": "…, which + clause", "example": "which no textbook can really teach", "try": "______, which ______."}]}}, {"q": "Do children today learn skills differently from children in the past?", "model": {"answer": "Quite differently. A generation ago, children learned by watching their parents and neighbours, so skills like cooking or fixing a bicycle were handed down naturally. Nowadays, a child can look up a tutorial in seconds. That’s a huge advantage, although it means they sometimes skip the hands-on practice that sticks in the mind. Not only is learning quicker now, but it’s also less personal, and often more superficial.", "phrases": [["hand down", "pass from one generation to the next"], ["look up", "search for information"], ["skip", "miss out deliberately"], ["stick in the mind", "be remembered easily"], ["superficial", "not deep; without much detail"]], "grammar": [{"pattern": "Passive past", "use": "were + past participle", "example": "were handed down naturally", "try": "Skills like ______ were ______ naturally."}, {"pattern": "Not only… but also", "use": "Not only is/does…, but it’s also…", "example": "Not only is learning quicker now, but it’s also less personal", "try": "Not only is ______, but it’s also ______."}]}}, {"q": "Who is the best person to teach children practical skills?", "model": {"answer": "A parent or grandparent, in most cases, because they have patience and a personal reason to see the child succeed. My grandfather taught me to repair a bicycle chain, and I still remember his hands guiding mine. That said, for specialised skills like swimming or coding, a trained instructor is safer, since they know how to break things down into small steps. The ideal is probably a blend.", "phrases": [["guide", "gently show someone the way to do something"], ["in most cases", "usually"], ["break things down", "divide into smaller, easier parts"], ["that said", "however"], ["a blend", "a mixture"]], "grammar": [{"pattern": "Concession with that said", "use": "…. That said, + clause", "example": "That said, for specialised skills like swimming or coding, a trained instructor is safer", "try": "That said, for ______, ______."}, {"pattern": "Reason with since", "use": "clause, since + clause", "example": "since they know how to break things down into small steps", "try": "______ is safer, since ______."}]}}, {"q": "Is it important to learn skills that are not taught at school?", "model": {"answer": "Absolutely, because school only scratches the surface of what people need in real life. Nobody teaches you how to manage your time, cook a decent meal or deal with a difficult colleague, yet these abilities shape your daily life far more than, say, memorising dates. If young people relied on school alone, they would struggle once they entered the workforce. So self-directed learning is crucial.", "phrases": [["scratch the surface", "deal with only a small part of something"], ["manage your time", "organise your hours well"], ["deal with", "handle"], ["struggle", "have difficulty"], ["enter the workforce", "start working"]], "grammar": [{"pattern": "Second conditional", "use": "if + past simple, would + verb", "example": "If young people relied on school alone, they would struggle", "try": "If people relied on ______, they would ______."}, {"pattern": "Comparative with far more than", "use": "shape + far more than", "example": "shape your daily life far more than, say, memorising dates", "try": "______ matters far more than ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Things & ideas"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000044', 1044, 'Topic 44', 'Crowded place', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 44, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a time when you went to a crowded place", "bullets": ["what the place was", "when you went there", "who you went with", "and explain why you liked or disliked it"], "explain": "", "notes": ["What", "When", "Who", "Why"], "rounding": {"q": "Do you usually avoid crowded places?", "model": {"answer": "Not always. I try to avoid them when I’m in a hurry, but for festivals or football matches, I actually enjoy the energy, as long as I’m with people I know.", "phrases": [], "grammar": []}}, "model": {"answer": "One occasion I’ll never forget is the Navruz festival in Tashkent a few years ago, which was easily the most jam-packed place I’ve ever been in. It was the afternoon of 21 March, and the weather was unusually warm. We arrived around two, which, as it turned out, was a mistake, because half the city seemed to have had the same idea. The queue for the metro alone stretched all the way up the stairs. I went with my cousin Madina and two of her friends. We’d planned to watch the folk dancing and try some sumalak, but the park was so packed that we could barely move. Shuffling along in a wall of people, I lost sight of Madina at one point and had to ring her to find out where she was. Honestly, I enjoyed it far more than I’d expected. What struck me was how good-natured everyone was. Strangers were sharing food, children were perched on their fathers’ shoulders, and a group of old men began singing right next to us. Admittedly, I went home with aching feet and a sore throat from shouting over the music. That said, I wouldn’t have missed it for the world. Had we come earlier, we’d have had more space, but we’d never have felt that buzz. Looking back, a crowd can be either draining or uplifting; it all depends on the mood and who you’re with.", "sections": [{"label": "What", "text": "One occasion I’ll never forget is the Navruz festival in Tashkent a few years ago, which was easily the most jam-packed place I’ve ever been in."}, {"label": "When", "text": "It was the afternoon of 21 March, and the weather was unusually warm. We arrived around two, which, as it turned out, was a mistake, because half the city seemed to have had the same idea. The queue for the metro alone stretched all the way up the stairs."}, {"label": "Who", "text": "I went with my cousin Madina and two of her friends. We’d planned to watch the folk dancing and try some sumalak, but the park was so packed that we could barely move. Shuffling along in a wall of people, I lost sight of Madina at one point and had to ring her to find out where she was."}, {"label": "Why", "text": "Honestly, I enjoyed it far more than I’d expected. What struck me was how good-natured everyone was. Strangers were sharing food, children were perched on their fathers’ shoulders, and a group of old men began singing right next to us. Admittedly, I went home with aching feet and a sore throat from shouting over the music. That said, I wouldn’t have missed it for the world. Had we come earlier, we’d have had more space, but we’d never have felt that buzz. Looking back, a crowd can be either draining or uplifting; it all depends on the mood and who you’re with."}], "phrases": [["jam-packed", "completely full of people"], ["as it turned out", "as later became clear"], ["shuffle along", "move forward slowly with small steps"], ["lose sight of", "stop being able to see"], ["strike (someone)", "make a strong impression on someone"], ["good-natured", "friendly and cheerful"], ["perched", "sitting on the edge of something high"], ["admittedly", "it must be said"], ["shout over", "speak loudly above another noise"], ["wouldn’t have missed it for the world", "was extremely glad to have been there"], ["buzz", "a lively, exciting atmosphere"], ["looking back", "when I think about it now"]], "grammar": [{"pattern": "Non-defining clause with as it", "use": "turned out …, which, as it turned out, + clause", "example": "which, as it turned out, was a mistake", "try": "______, which, as it turned out, ______."}, {"pattern": "Past perfect for earlier plans", "use": "had/’d + past participle", "example": "We’d planned to watch the folk dancing", "try": "We’d planned to ______, but ______."}, {"pattern": "so… that", "use": "so + adjective + that + result", "example": "the park was so packed that we could barely move", "try": "The place was so ______ that ______."}, {"pattern": "Participle clause", "use": "V-ing phrase, + main clause", "example": "Shuffling along in a wall of people, I lost sight of Madina", "try": "Walking along ______, I ______."}, {"pattern": "Cleft with what", "use": "What + verb + me + was + clause", "example": "What struck me was how good-natured everyone was", "try": "What struck me was how ______."}, {"pattern": "Third conditional with inversion", "use": "Had + subject + past participle, … would have", "example": "Had we come earlier, we’d have had more space", "try": "Had we ______, we’d have ______."}]}}, "part3": {"intro": "We’ve been talking about a time when you went to a crowded place, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Crowded place", "title": "Crowded place", "questions": [{"q": "What places are often crowded in your country?", "model": {"answer": "Markets and public transport spring to mind first. In Tashkent, for instance, the metro is packed at rush hour, and places like Chorsu Bazaar are heaving at weekends. Festivals and weddings also draw big crowds, particularly in spring, when Navruz celebrations fill the parks. Then there are shopping centres, which are jammed on Friday evenings, since that’s when most families have time to spare.", "phrases": [["packed", "completely full"], ["rush hour", "the busiest time of day for traffic"], ["heaving", "extremely crowded"], ["draw big crowds", "attract many people"], ["fill the parks", "make the parks full of people"], ["time to spare", "free time"]], "grammar": [{"pattern": "For instance with relative where", "use": "place + like + name", "example": "places like Chorsu Bazaar are heaving at weekends", "try": "Places like ______ are ______ at ______."}, {"pattern": "Time clause with when", "use": "…, when + clause", "example": "particularly in spring, when Navruz celebrations fill the parks", "try": "______, particularly in ______, when ______."}]}}, {"q": "Do people behave differently in crowded places?", "model": {"answer": "Yes, usually in two opposite ways. On the one hand, people become more cooperative, making room for each other and helping strangers. On the other hand, a crowd can make people pushy, especially when they’re in a hurry. What really matters is whether people feel anonymous: the less accountable they feel, the more inconsiderately they may behave. Football crowds are a good example of both extremes.", "phrases": [["make room", "move to create space"], ["pushy", "aggressive in getting what you want"], ["anonymous", "unknown to others"], ["accountable", "responsible for your actions"], ["inconsiderately", "without thinking about others"]], "grammar": [{"pattern": "On the one hand… on the other", "use": "hand On the one hand, …. On the other hand, …", "example": "On the one hand, people become more cooperative", "try": "On the one hand, ______. On the other hand, ______."}, {"pattern": "The less… the more", "use": "the less + adjective, the more + clause", "example": "the less accountable they feel, the more inconsiderately they may behave", "try": "The less ______, the more ______."}]}}, {"q": "What are the negative effects of crowded places?", "model": {"answer": "The most obvious one is stress. When you’re squeezed into a tiny space, your heart rate rises and you can’t think straight. There are health risks too, as infections spread more easily, and in an emergency, such as a fire, a dense crowd can turn dangerous quickly. Over time, constant crowding takes a toll on people’s wellbeing, which is why overpopulated areas often suffer from more noise and pollution.", "phrases": [["squeezed", "pressed tightly into a small space"], ["can’t think straight", "unable to think clearly"], ["spread", "pass from one person to another"], ["turn dangerous", "become unsafe"], ["take a toll on", "have a harmful effect on"]], "grammar": [{"pattern": "When + present simple for general", "use": "truth When you’re + p.p./adj, + result", "example": "When you’re squeezed into a tiny space, your heart rate rises", "try": "When you’re ______, ______."}, {"pattern": "Non-defining which", "use": "…, which is why + clause", "example": "which is why overpopulated areas often suffer from more noise and pollution", "try": "______, which is why ______."}]}}, {"q": "Why do some people enjoy crowds while others avoid them?", "model": {"answer": "It comes down to personality. Extroverts feed off the energy of a crowd, so a concert or festival feels exciting to them. Introverts, however, find the same environment draining, because they need quiet to recharge. Past experience plays a part as well: someone who has ever felt panicky in a packed lift will naturally steer clear of crowds. So it’s partly temperament and partly memory.", "phrases": [["feed off", "gain energy from"], ["draining", "making you feel tired"], ["recharge", "regain your energy"], ["panicky", "suddenly very anxious"], ["steer clear of", "deliberately avoid"]], "grammar": [{"pattern": "It comes down to", "use": "It comes down to + noun", "example": "It comes down to personality", "try": "It comes down to ______."}, {"pattern": "Relative clause with who + present", "use": "perfect someone who has + past participle, will + verb", "example": "someone who has ever felt panicky in a packed lift will naturally steer clear of crowds", "try": "Someone who has ______ will naturally ______."}]}}, {"q": "Do you agree that cities of the future will be so crowded that they will have no green spaces?", "model": {"answer": "I’d like to think not, although the risk is real. As land becomes more expensive, developers are tempted to build on every spare plot. But cities have started recognising that parks improve air quality and mental health, so many are adding rooftop gardens and green corridors. If planners kept prioritising housing alone, we could lose them; with sensible rules, I believe we’ll strike a balance.", "phrases": [["be tempted to", "feel attracted to doing something"], ["improve air quality", "make the air cleaner"], ["green corridor", "a strip of nature through a city"], ["strike a balance", "find a fair middle position"], ["spare plot", "empty piece of land"]], "grammar": [{"pattern": "Reduced concessive although", "use": "…, although + clause", "example": "although the risk is real", "try": "I’d like to think ______, although ______."}, {"pattern": "Second conditional with could", "use": "If + past simple, … could + verb", "example": "If planners kept prioritising housing alone, we could lose them", "try": "If planners ______, we could ______."}]}}, {"q": "What can be done to reduce overcrowding in cities?", "model": {"answer": "Decentralisation would be the first step. If more jobs, universities and hospitals were located in smaller cities, fewer people would move to the capital in the first place. Better public transport would help, too, as it would take cars off the road. In the short term, staggering working hours is a cheap fix, because it spreads out the morning rush. In the long run, regional development is the real answer.", "phrases": [["locate", "place in a particular position"], ["move to", "relocate to"], ["take cars off the road", "reduce the number of vehicles"], ["stagger", "arrange to happen at different times"], ["spread out", "distribute over a longer period"]], "grammar": [{"pattern": "Passive in second conditional", "use": "If + noun + were + past participle, would + verb", "example": "If more jobs, universities and hospitals were located in smaller cities, fewer people would move to the capital", "try": "If more ______ were ______, fewer people would ______."}, {"pattern": "In the short term / long run", "use": "In the short term, …. In the long run, …", "example": "In the short term, staggering working hours is a cheap fix", "try": "In the short term, ______. In the long run, ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Places"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000045', 1045, 'Topic 45', 'Waste of time', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 45, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe an activity you usually do that wastes your time", "bullets": ["what it is", "when you do it", "why you do it", "why you think it wastes your time"], "explain": "", "notes": ["What", "When", "Why", "Waste"], "rounding": {"q": "Do you think young people waste more time than older people?", "model": {"answer": "Probably, yes, but only because they have more distractions. Older people waste time too; they just do it in front of the television instead of on a phone.", "phrases": [], "grammar": []}}, "model": {"answer": "Let me tell you about a habit I’m not proud of: scrolling through short videos on my phone. It starts innocently enough, but I always end up watching far more than I intended. I do it mostly late at night, once I’ve wrapped up my homework, and again on the bus to university, where there’s nothing else to do. On bad days, I lose track of time completely, and what was supposed to be ten minutes turns into an hour. The reason I keep doing it is simple: it’s effortless. After a long day of studying economics, my brain is fried, and videos ask nothing of me. Each clip lasts only fifteen seconds, so there’s always a tempting “one more”, and the app seems designed to keep me hooked. Part of me also uses it to switch off and avoid thinking about deadlines. But I’m well aware that it eats into my time. Last month, I checked my screen time and was shocked to find I’d been spending nearly two hours a day on it, which is time I could have used to read, or simply to sleep. Never had I realised how much I was losing. What bothers me most is that I rarely remember anything I’ve watched. So I’ve started putting my phone out of reach after ten, and it’s paying off. Slowly, I’m getting a grip on the habit, and I sleep noticeably better.", "sections": [{"label": "What", "text": "Let me tell you about a habit I’m not proud of: scrolling through short videos on my phone. It starts innocently enough, but I always end up watching far more than I intended."}, {"label": "When", "text": "I do it mostly late at night, once I’ve wrapped up my homework, and again on the bus to university, where there’s nothing else to do. On bad days, I lose track of time completely, and what was supposed to be ten minutes turns into an hour."}, {"label": "Why", "text": "The reason I keep doing it is simple: it’s effortless. After a long day of studying economics, my brain is fried, and videos ask nothing of me. Each clip lasts only fifteen seconds, so there’s always a tempting “one more”, and the app seems designed to keep me hooked. Part of me also uses it to switch off and avoid thinking about deadlines."}, {"label": "Waste", "text": "But I’m well aware that it eats into my time. Last month, I checked my screen time and was shocked to find I’d been spending nearly two hours a day on it, which is time I could have used to read, or simply to sleep. Never had I realised how much I was losing. What bothers me most is that I rarely remember anything I’ve watched. So I’ve started putting my phone out of reach after ten, and it’s paying off. Slowly, I’m getting a grip on the habit, and I sleep noticeably better."}], "phrases": [["innocently enough", "in a harmless way at first"], ["end up (doing)", "finally do something, often unplanned"], ["wrap up", "finish"], ["lose track of time", "forget how much time has passed"], ["fried", "completely exhausted mentally"], ["keep (someone) hooked", "make someone unable to stop using something"], ["switch off", "stop thinking or worrying and relax"], ["eat into", "gradually use up or reduce"], ["out of reach", "too far to grab easily"], ["pay off", "bring good results"], ["get a grip on", "gain control of"]], "grammar": [{"pattern": "Contact relative clause", "use": "noun + (that) + subject + verb", "example": "a habit I’m not proud of", "try": "a habit I’m ______ of."}, {"pattern": "Past continuous idea with", "use": "supposed to was/were supposed to be + noun", "example": "what was supposed to be ten minutes turns into an hour", "try": "What was supposed to be ______ turns into ______."}, {"pattern": "", "use": "Cleft: The reason… is The reason + clause + is + clause", "example": "The reason I keep doing it is simple", "try": "The reason I ______ is ______."}, {"pattern": "Past perfect continuous", "use": "had/’d been + -ing", "example": "I’d been spending nearly two hours a day on it", "try": "I’d been ______ for ______."}, {"pattern": "Inversion with never", "use": "Never had + subject + past participle", "example": "Never had I realised how much I was losing", "try": "Never had I ______."}, {"pattern": "Relative clause for emphasis", "use": "What + verb + me + is + that", "example": "What bothers me most is that I rarely remember anything I’ve watched", "try": "What bothers me most is that ______."}]}}, "part3": {"intro": "We’ve been talking about an activity you usually do that wastes your time, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Waste of time", "title": "Waste of time", "questions": [{"q": "Do people today have a better work–life balance than in the past?", "model": {"answer": "Not necessarily, even though technology has made work more flexible. Our grandparents’ working day usually ended when they left the office, whereas today many people check emails at dinner. Remote work saves commuting time, but it also blurs the line between home and job. So while hours may be shorter on paper, people are never fully switched off, which undermines real balance.", "phrases": [["flexible", "able to adapt to different times and places"], ["blur the line", "make the difference unclear"], ["on paper", "in theory"], ["switched off", "relaxed and not thinking about work"], ["undermine", "weaken gradually"]], "grammar": [{"pattern": "Concession with even though", "use": "even though + present perfect clause", "example": "even though technology has made work more flexible", "try": "Even though ______ has made ______, ______."}, {"pattern": "Non-defining which", "use": "…, which + verb", "example": "which undermines real balance", "try": "______, which ______."}]}}, {"q": "How important is it to have a daily routine?", "model": {"answer": "Very important, in my experience, particularly for students. Without a routine, you spend half the day deciding what to do, which is exhausting in itself. A fixed schedule takes the guesswork out of mornings and frees up mental energy for harder tasks. Of course, a routine that’s too rigid can become dull, so I’d suggest a loose structure with some room for spontaneity.", "phrases": [["spend half the day deciding", "waste a lot of time making choices"], ["take the guesswork out of", "make something clear and predictable"], ["free up", "make available"], ["too rigid", "not flexible enough"], ["room for spontaneity", "space for unplanned things"]], "grammar": [{"pattern": "Without + noun", "use": "Without + noun, + clause", "example": "Without a routine, you spend half the day deciding what to do", "try": "Without ______, you ______."}, {"pattern": "Relative clause with that", "use": "noun + that’s + adjective + can + verb", "example": "a routine that’s too rigid can become dull", "try": "A ______ that’s too ______ can ______."}]}}, {"q": "What kinds of things make people feel under pressure?", "model": {"answer": "Deadlines and money are the obvious ones, but I’d argue expectation is just as powerful. When family or friends have high hopes for you, falling short feels like letting them down. Comparison plays a part too: seeing classmates get promoted or praised can make people feel they’re lagging behind. In other words, pressure often comes from within as much as from outside.", "phrases": [["have high hopes for", "expect someone to do well"], ["fall short", "fail to reach the expected standard"], ["let (someone) down", "disappoint someone"], ["lag behind", "progress more slowly than others"], ["come from within", "start inside a person"]], "grammar": [{"pattern": "Gerund as subject", "use": "-ing + verb", "example": "falling short feels like letting them down", "try": "Failing feels like ______."}, {"pattern": "make + object + infinitive", "use": "make + object + (feel)", "example": "can make people feel they’re lagging behind", "try": "______ can make people feel ______."}]}}, {"q": "Do you agree that social media increases the pressure of modern life?", "model": {"answer": "To a large extent, yes. Scrolling through other people’s highlights makes everyone else’s life look effortless, so users feel they must keep up. There’s also an expectation to reply instantly, which leaves people permanently on call. That said, it isn’t all bad: used wisely, social media keeps people in touch. The problem lies less in the platforms than in how much time we spend on them.", "phrases": [["scroll through", "look quickly through content on a screen"], ["effortless", "achieved without effort"], ["keep up", "stay at the same level as others"], ["on call", "always available if needed"], ["keep in touch", "stay connected"]], "grammar": [{"pattern": "Participle clause", "use": "past participle + adverb, + clause", "example": "used wisely, social media keeps people in touch", "try": "Used ______, ______ can ______."}, {"pattern": "less… than", "use": "lies less in A than in B", "example": "The problem lies less in the platforms than in how much time we spend on them", "try": "The problem lies less in ______ than in ______."}]}}, {"q": "Can a small amount of stress be beneficial?", "model": {"answer": "Definitely, up to a point. A little stress sharpens your focus: the night before an exam, the adrenaline helps you concentrate and get things done. Athletes, for instance, often perform better when they’re slightly nervous. However, once it becomes constant, it turns into exhaustion. The key is that stress should be short and followed by proper rest, otherwise people burn out.", "phrases": [["up to a point", "to a limited extent"], ["sharpen your focus", "improve concentration"], ["get things done", "complete tasks"], ["turn into", "become"], ["burn out", "become exhausted from overwork"]], "grammar": [{"pattern": "Time expression + present simple", "use": "the night before + noun, + clause", "example": "the night before an exam, the adrenaline helps you concentrate", "try": "The night before ______, ______."}, {"pattern": "otherwise", "use": "…, otherwise + clause", "example": "otherwise people burn out", "try": "You need ______, otherwise ______."}]}}, {"q": "What can people do to avoid wasting time?", "model": {"answer": "Planning is the simplest answer. Writing down three priorities each morning keeps you from drifting into aimless scrolling. It also helps to set time limits on apps and to leave your phone out of sight while studying. Beyond that, taking proper breaks actually saves time, because tired people work slowly. Small habits like these add up, and they cost nothing.", "phrases": [["keep (someone) from drifting", "stop someone from losing direction"], ["set time limits", "decide a maximum time"], ["out of sight", "where you cannot see it"], ["take a break", "stop to rest"], ["add up", "gradually make a big total effect"]], "grammar": [{"pattern": "Gerund subject", "use": "-ing phrase + verb", "example": "Writing down three priorities each morning keeps you from drifting into aimless scrolling", "try": "Writing down ______ keeps you from ______."}, {"pattern": "It helps to", "use": "It also helps to + verb and to + verb", "example": "It also helps to set time limits on apps and to leave your phone out of sight", "try": "It helps to ______ and to ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Events & experiences"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000046', 1046, 'Topic 46', 'Your least favourite movie', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 46, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a film you did not like", "bullets": ["what the film was", "what it was about", "why you decided to watch it", "and explain why it disappointed you"], "explain": "", "notes": ["What", "About", "Why Watch", "Why Disapp Ointed"], "rounding": {"q": "Do you usually check reviews before you watch a film?", "model": {"answer": "Usually, yes, but I’ve learned to read a few different ones instead of trusting a single score. Opinions about films vary so much that an average rating can be misleading.", "phrases": [], "grammar": []}}, "model": {"answer": "If I had to pick a film I really didn’t enjoy, it would be a sci-fi blockbuster that came out a couple of years ago. I’d rather not name it, but you’d probably recognise it, because it was all over social media at the time. It was about a team of astronauts who discover a signal from a distant planet and have to decide whether to answer it. On paper, that sounds gripping, and the trailer certainly had me on the edge of my seat. I decided to watch it because my friend Jamshid had raved about it for weeks. He kept saying it was a must-see, and the online reviews were glowing, so I got my hopes up. We booked tickets for a Saturday night and even paid extra for the big screen. The cinema was packed, which I took as a good sign. Unfortunately, it fell flat. The special effects were stunning, I’ll give it that, but the plot was paper-thin, and the characters were so shallow that I couldn’t care less what happened to them. At nearly three hours, it also dragged on forever. By the halfway mark, I kept glancing at my watch, and Jamshid had gone suspiciously quiet. Afterwards, he admitted he’d expected something deeper too. Looking back, it taught me never to take hype at face value. Had I read a few balanced reviews first, I’d have saved my money for something better.", "sections": [{"label": "What", "text": "If I had to pick a film I really didn’t enjoy, it would be a sci-fi blockbuster that came out a couple of years ago. I’d rather not name it, but you’d probably recognise it, because it was all over social media at the time."}, {"label": "About", "text": "It was about a team of astronauts who discover a signal from a distant planet and have to decide whether to answer it. On paper, that sounds gripping, and the trailer certainly had me on the edge of my seat."}, {"label": "Why Watch", "text": "I decided to watch it because my friend Jamshid had raved about it for weeks. He kept saying it was a must-see, and the online reviews were glowing, so I got my hopes up. We booked tickets for a Saturday night and even paid extra for the big screen. The cinema was packed, which I took as a good sign."}, {"label": "Why Disapp Ointed", "text": "Unfortunately, it fell flat. The special effects were stunning, I’ll give it that, but the plot was paper-thin, and the characters were so shallow that I couldn’t care less what happened to them. At nearly three hours, it also dragged on forever. By the halfway mark, I kept glancing at my watch, and Jamshid had gone suspiciously quiet. Afterwards, he admitted he’d expected something deeper too. Looking back, it taught me never to take hype at face value. Had I read a few balanced reviews first, I’d have saved my money for something better."}], "phrases": [["all over (social media)", "everywhere"], ["gripping", "so exciting that you cannot stop watching"], ["on the edge of one’s seat", "extremely excited or tense"], ["rave about", "praise enthusiastically"], ["get one’s hopes up", "expect something good"], ["fall flat", "fail to have the intended effect"], ["I’ll give it that", "I admit that point in its favour"], ["paper-thin", "very weak or shallow"], ["drag on", "continue for too long"], ["looking back", "when I think about the past"], ["take (something) at face value", "accept something without questioning it"]], "grammar": [{"pattern": "Second conditional", "use": "If I had to + verb, it would be", "example": "If I had to pick a film I really didn’t enjoy, it would be a sci-fi blockbuster", "try": "If I had to pick ______, it would be ______."}, {"pattern": "Relative clause with who", "use": "noun + who + present simple", "example": "a team of astronauts who discover a signal from a distant planet", "try": "a team of ______ who ______."}, {"pattern": "Past perfect", "use": "had + past participle (earlier action)", "example": "my friend Jamshid had raved about it for weeks", "try": "My friend had ______ for weeks."}, {"pattern": "so… that", "use": "so + adjective + that + result", "example": "the characters were so shallow that I couldn’t care less what happened to them", "try": "The ______ were so ______ that I couldn’t ______."}, {"pattern": "Past perfect with had gone", "use": "had gone + adjective", "example": "Jamshid had gone suspiciously quiet", "try": "______ had gone ______."}, {"pattern": "Third conditional with inversion", "use": "Had + subject + past participle, I’d have + past participle", "example": "Had I read a few balanced reviews first, I’d have saved my money for something better", "try": "Had I ______, I’d have ______."}]}}, "part3": {"intro": "We’ve been talking about a film you did not like, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Your least favourite movie", "title": "Your least favourite movie", "questions": [{"q": "What kinds of films are popular in your country?", "model": {"answer": "Comedies and action films are the safest bets, although Hollywood blockbusters dominate the cinemas in the big cities. Uzbek comedies and family dramas have a loyal audience too, since they reflect everyday life and the humour feels familiar. Among younger people, superhero and horror films draw the crowds, especially at weekends, while historical epics tend to do well around national holidays.", "phrases": [["dominate", "be the most powerful or common"], ["loyal audience", "fans who keep coming back"], ["reflect everyday life", "show ordinary life realistically"], ["draw the crowds", "attract many viewers"], ["do well", "be successful"]], "grammar": [{"pattern": "Reason clause with since", "use": "…, since + clause", "example": "since they reflect everyday life and the humour feels familiar", "try": "______ are popular, since ______."}, {"pattern": "while for contrast", "use": "…, while + subject + verb", "example": "while historical epics tend to do well around national holidays", "try": "______, while ______ tend to ______."}]}}, {"q": "What are the differences between watching a film at home and in a cinema?", "model": {"answer": "At the cinema, you get the big screen and surround sound, and there’s a real sense of occasion because you’ve made an effort to go. At home, on the other hand, you can pause, snack and watch in your pyjamas, which is far cheaper. Cinema is better for spectacle, whereas home suits slower, character-driven stories that you want to take in properly.", "phrases": [["sense of occasion", "feeling that something is special"], ["make an effort", "try hard to do something"], ["spectacle", "an impressive visual show"], ["character-driven", "focused on people more than action"], ["take in", "fully absorb or understand"]], "grammar": [{"pattern": "Present perfect for result", "use": "because you’ve + past participle", "example": "because you’ve made an effort to go", "try": "______ because you’ve ______."}, {"pattern": "whereas", "use": "A, whereas B", "example": "whereas home suits slower, character-driven stories that you want to take in properly", "try": "______ is better for ______, whereas ______."}]}}, {"q": "Why do people of different ages enjoy different types of films?", "model": {"answer": "Largely because life experience shapes what appeals to you. Teenagers crave action and humour, as they’re looking for excitement and shared jokes with friends. Adults, however, relate to stories about family, work or moral dilemmas, since they’ve lived through similar situations. Older viewers often prefer nostalgic classics that remind them of their youth. In short, we gravitate towards films that mirror our own stage of life.", "phrases": [["shape", "influence and form"], ["crave", "want very strongly"], ["relate to", "feel a connection with"], ["nostalgic", "longing for the past"], ["gravitate towards", "be naturally drawn to"]], "grammar": [{"pattern": "Noun clause", "use": "what + verb + to you", "example": "life experience shapes what appeals to you", "try": "______ shapes what appeals to ______."}, {"pattern": "Relative clause with that", "use": "noun + that + verb", "example": "classics that remind them of their youth", "try": "______ that remind them of ______."}]}}, {"q": "Do you think films can influence people’s behaviour?", "model": {"answer": "They certainly can, particularly among young viewers. Fashion is the clearest example: a character’s hairstyle or outfit can spark a trend overnight. More seriously, repeated exposure to violence may desensitise some people, whereas inspiring stories can motivate viewers to pursue a goal. That said, films rarely change someone’s fundamental values; they reinforce what a person is already inclined to believe.", "phrases": [["spark a trend", "start a fashion or habit"], ["desensitise", "make less sensitive to something"], ["motivate", "give someone a reason to act"], ["pursue", "work towards"], ["reinforce", "make stronger"]], "grammar": [{"pattern": "Superlative", "use": "the + superlative + example", "example": "Fashion is the clearest example", "try": "______ is the clearest example."}, {"pattern": "Noun clause with what", "use": "reinforce + what + subject + is + inclined to", "example": "they reinforce what a person is already inclined to believe", "try": "They reinforce what a person is already ______."}]}}, {"q": "Why do some films become very popular while others fail?", "model": {"answer": "Word of mouth matters more than marketing. A relatable story with strong characters will spread quickly once audiences start recommending it, whereas a film that relies on special effects alone often falls flat. Timing plays a part too: a film that captures the mood of the moment can take off, while a similar one released at the wrong time is overlooked. Luck, frankly, is a factor.", "phrases": [["strong characters", "well-written, memorable people in a story"], ["rely on", "depend on"], ["fall flat", "fail to impress"], ["capture the mood", "express the feeling of a time"], ["take off", "suddenly become successful"], ["overlook", "fail to notice"]], "grammar": [{"pattern": "Relative clause with that", "use": "a film that + verb", "example": "a film that relies on special effects alone often falls flat", "try": "A film that ______ often ______."}, {"pattern": "Reduced relative clause", "use": "noun + past participle phrase", "example": "a similar one released at the wrong time is overlooked", "try": "A film released ______ is ______."}]}}, {"q": "Do you think cinemas will disappear in the future?", "model": {"answer": "I doubt they’ll vanish completely, though they will probably have to adapt. Streaming has eaten into audiences, and home screens keep improving. Yet people still want shared experiences: laughing or gasping together is something you can’t replicate on a sofa. If cinemas offer more than just a film, such as comfortable seating and special events, they’ll survive, albeit in smaller numbers.", "phrases": [["adapt", "change to suit new conditions"], ["eat into", "reduce gradually"], ["shared experience", "something people do together"], ["replicate", "copy exactly"], ["survive", "continue to exist"], ["albeit", "although"]], "grammar": [{"pattern": "Present perfect", "use": "has + past participle", "example": "Streaming has eaten into audiences", "try": "______ has eaten into ______."}, {"pattern": "First conditional", "use": "If + present simple, will + verb", "example": "If cinemas offer more than just a film, such as comfortable seating and special events, they’ll survive", "try": "If cinemas offer ______, they’ll ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Things & ideas"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000047', 1047, 'Topic 47', 'Trip you often take but dislike', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 47, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a short journey that you often take but dislike", "bullets": ["where you go", "how often you do this", "when you do this", "why you dislike it"], "explain": "", "notes": ["Where", "How Often", "When", "Why"], "rounding": {"q": "Do you think you’ll still be making this journey in five years’ time?", "model": {"answer": "I hope not. By then I’d like to have graduated and be working somewhere I can get to on foot, or at least by metro, so I never have to squeeze onto a crowded bus again.", "phrases": [], "grammar": []}}, "model": {"answer": "Let me tell you about a journey I make almost every day and, frankly, dread: the bus ride from our flat in Chilonzor to my university in the city centre. It’s only about six kilometres, but it can feel like a trek. I do it five days a week, sometimes six when we have extra classes on Saturday, so over a semester it adds up to a ridiculous number of hours. Weekends are my only break from it. The worst part is that I have to travel at rush hour, around eight in the morning, when everyone is heading to work or school. By the time the bus reaches my stop, it’s already packed to the rafters. I’m usually squashed between a man with a huge bag and a student listening to music at full volume. The windows rarely open, and in summer it feels like a sauna. Honestly, what I dislike most isn’t the crowding itself but the unpredictability. Some days the traffic moves nicely and I’m there in twenty minutes; on others, we crawl along for almost an hour, and I arrive frazzled and late for my first lecture. I’ve tried to make the best of it by listening to English podcasts, which has helped a little. Even so, I’d move closer to the university tomorrow if I could. Were the metro extended to our area, I’d switch in a heartbeat, because it’s far more reliable.", "sections": [{"label": "Where", "text": "Let me tell you about a journey I make almost every day and, frankly, dread: the bus ride from our flat in Chilonzor to my university in the city centre. It’s only about six kilometres, but it can feel like a trek."}, {"label": "How Often", "text": "I do it five days a week, sometimes six when we have extra classes on Saturday, so over a semester it adds up to a ridiculous number of hours. Weekends are my only break from it."}, {"label": "When", "text": "The worst part is that I have to travel at rush hour, around eight in the morning, when everyone is heading to work or school. By the time the bus reaches my stop, it’s already packed to the rafters. I’m usually squashed between a man with a huge bag and a student listening to music at full volume. The windows rarely open, and in summer it feels like a sauna."}, {"label": "Why", "text": "Honestly, what I dislike most isn’t the crowding itself but the unpredictability. Some days the traffic moves nicely and I’m there in twenty minutes; on others, we crawl along for almost an hour, and I arrive frazzled and late for my first lecture. I’ve tried to make the best of it by listening to English podcasts, which has helped a little. Even so, I’d move closer to the university tomorrow if I could. Were the metro extended to our area, I’d switch in a heartbeat, because it’s far more reliable."}], "phrases": [["dread", "feel very anxious about something in advance"], ["trek", "a long, tiring journey"], ["add up", "gradually reach a large total"], ["rush hour", "the busiest time of day for travel"], ["packed to the rafters", "completely full of people"], ["squashed", "pressed into a small space"], ["crawl along", "move extremely slowly"], ["frazzled", "tired and stressed"], ["make the best of it", "accept a bad situation and try to enjoy it"], ["even so", "despite that"], ["in a heartbeat", "immediately, without hesitation"]], "grammar": [{"pattern": "Contact relative clause", "use": "noun + (that) + subject + verb", "example": "a journey I make almost every day", "try": "a journey I ______ every day."}, {"pattern": "Time clause with when", "use": "…, when + clause", "example": "around eight in the morning, when everyone is heading to work or school", "try": "______, when ______."}, {"pattern": "By the time", "use": "By the time + present simple, + present", "example": "By the time the bus reaches my stop, it’s already packed to the rafters", "try": "By the time ______, it’s already ______."}, {"pattern": "Cleft sentence", "use": "what + subject + verb + is(n’t) + A but B", "example": "what I dislike most isn’t the crowding itself but the unpredictability", "try": "What I dislike most isn’t ______ but ______."}, {"pattern": "Non-defining which", "use": "…, which + present perfect", "example": "which has helped a little", "try": "______, which has ______."}, {"pattern": "Inverted conditional", "use": "Were + subject + past participle, I’d + verb", "example": "Were the metro extended to our area, I’d switch in a heartbeat", "try": "Were ______ extended, I’d ______."}]}}, "part3": {"intro": "We’ve been talking about a short journey that you often take but dislike, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Trip you often take but dislike", "title": "Trip you often take but dislike", "questions": [{"q": "What problems arise when lots of people travel to work at the same time?", "model": {"answer": "Congestion is the biggest one. When everyone sets off between eight and nine, roads grind to a halt, journeys take twice as long, and drivers burn fuel sitting idle. Public transport suffers as well, since overcrowded buses and carriages are uncomfortable. There’s also a knock-on effect on people’s mood: workers arrive already stressed, which hurts productivity before the day has even begun.", "phrases": [["set off", "begin a journey"], ["grind to a halt", "stop slowly"], ["knock-on effect", "a secondary result of something"], ["already stressed", "tense before work has started"], ["hurt productivity", "reduce how much work gets done"]], "grammar": [{"pattern": "Time clause with when", "use": "When + subject + verb, + clause", "example": "When everyone sets off between eight and nine, roads grind to a halt", "try": "When everyone ______, ______."}, {"pattern": "Participle clause", "use": "verb + object + sitting/-ing", "example": "drivers burn fuel sitting idle", "try": "Drivers ______ sitting ______."}]}}, {"q": "Why do people like travelling?", "model": {"answer": "Because it breaks the routine. When you’re stuck in the same environment, days blur together, whereas a trip gives you something new to look forward to. There’s also the curiosity about other cultures, food and landscapes. Perhaps most importantly, people come back refreshed: even a short weekend away can recharge your batteries, which explains why holidays are so highly valued.", "phrases": [["break the routine", "change a normal pattern"], ["blur together", "become hard to tell apart"], ["look forward to", "feel happy about a future event"], ["come back refreshed", "return feeling energetic"], ["recharge your batteries", "regain energy by resting"]], "grammar": [{"pattern": "Passive participle in a time clause", "use": "When you’re + stuck…", "example": "When you’re stuck in the same environment, days blur together", "try": "When you’re stuck ______, ______."}, {"pattern": "Non-defining which", "use": "…, which explains why + clause", "example": "which explains why holidays are so highly valued", "try": "______, which explains why ______."}]}}, {"q": "Do people in your country like to travel abroad?", "model": {"answer": "Increasingly, yes, particularly the younger generation. Turkey, Dubai and Georgia have become popular for short breaks, partly because flights feel more affordable than before, especially for students and young professionals. Older people tend to prefer domestic trips or visiting relatives. Interest in travel abroad has grown steadily as incomes have risen and people share their photos online, which inspires friends to follow suit.", "phrases": [["short break", "a brief holiday"], ["affordable", "not too expensive"], ["domestic trip", "a journey within one’s own country"], ["grow steadily", "increase gradually"], ["follow suit", "do the same as others"]], "grammar": [{"pattern": "Reason with partly because", "use": "…, partly because + clause", "example": "partly because flights feel more affordable than before", "try": "______, partly because ______."}, {"pattern": "As + present perfect", "use": "as + noun + have + past participle", "example": "as incomes have risen", "try": "Interest has grown as ______ have ______."}]}}, {"q": "What are the benefits of travelling abroad?", "model": {"answer": "The main benefit is broadening your horizons. Living even briefly in another culture challenges your assumptions and teaches you to adapt quickly to unfamiliar situations, and it improves your language skills, since you can’t hide behind your mother tongue. It can also boost your career, because employers value people who’ve shown independence. My first trip abroad, for example, made me far more open-minded.", "phrases": [["broaden your horizons", "gain wider experience and knowledge"], ["challenge your assumptions", "make you question what you believed"], ["hide behind", "use as protection to avoid something"], ["boost your career", "improve job prospects"], ["open-minded", "willing to accept new ideas"]], "grammar": [{"pattern": "Gerund subject", "use": "Living + adverb + in …", "example": "Living even briefly in another culture challenges your assumptions", "try": "Living ______ in ______ teaches you ______."}, {"pattern": "Relative clause with who + present", "use": "perfect people who’ve + past participle", "example": "employers value people who’ve shown independence", "try": "Employers value people who’ve ______."}]}}, {"q": "Who likes travelling more, older people or younger people?", "model": {"answer": "Younger people, I’d say, simply because they have the energy and curiosity. For them, travel is about adventure, often on a tight budget. Older people may enjoy it just as much, but family commitments and health can hold them back, and they tend to prefer comfort. If you asked my grandparents, they’d rather stay at home, whereas my cousins are always planning their next trip.", "phrases": [["on a tight budget", "with very little money"], ["family commitments", "responsibilities towards relatives"], ["hold (someone) back", "prevent someone from doing something"], ["would rather stay", "prefer to stay"], ["plan one’s next trip", "organise a future journey"]], "grammar": [{"pattern": "Second conditional with would", "use": "rather If + past simple, they’d rather + verb", "example": "If you asked my grandparents, they’d rather stay at home", "try": "If you asked my ______, they’d rather ______."}, {"pattern": "always + continuous", "use": "are always + -ing", "example": "my cousins are always planning their next trip", "try": "My ______ are always ______."}]}}, {"q": "Do people prefer long trips or short trips?", "model": {"answer": "These days, more people opt for short trips, largely because time is tight. A weekend break fits around work, costs less, and can be arranged at short notice. Long trips are more rewarding, though, since you get to know a place properly. If money and time weren’t an issue, most people would choose a long trip, but in practice, short breaks win out.", "phrases": [["opt for", "choose"], ["arrange at short notice", "organise with very little warning"], ["get to know", "become familiar with"], ["in practice", "in reality"], ["win out", "finally succeed over others"]], "grammar": [{"pattern": "Passive modal", "use": "can be + past participle", "example": "can be arranged at short notice", "try": "A trip can be ______ at short notice."}, {"pattern": "Second conditional", "use": "If + past simple (weren’t), would + verb", "example": "If money and time weren’t an issue, most people would choose a long trip", "try": "If ______ weren’t an issue, most people would ______."}]}}, {"q": "How could daily journeys be made more pleasant?", "model": {"answer": "Better scheduling and comfort would be a good start. If buses ran more frequently and were air-conditioned, people would dread the journey far less. Small touches help too: reliable wifi, clear information about arrival times and cleaner stations. On a personal level, podcasts or audiobooks can turn dead time into learning time. So both public investment and individual habits can transform the experience.", "phrases": [["frequently", "often; at short intervals"], ["dread", "fear in advance"], ["small touches", "minor details that improve things"], ["turn dead time into learning time", "use wasted time to learn"], ["transform", "change completely"]], "grammar": [{"pattern": "Second conditional", "use": "If + past simple, people would + verb", "example": "If buses ran more frequently and were air-conditioned, people would dread the journey far less", "try": "If buses ______, people would ______."}, {"pattern": "both… and", "use": "both A and B can + verb", "example": "both public investment and individual habits can transform the experience", "try": "Both ______ and ______ can ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Events & experiences"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000048', 1048, 'Topic 48', 'Person who taught you a skill', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 48, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a person who taught you a skill", "bullets": ["who this person is", "what this person taught you", "how they taught you", "why you think it was important"], "explain": "", "notes": ["Who", "What", "How", "Why"], "rounding": {"q": "Do you ever get the chance to pass on what she taught you?", "model": {"answer": "Yes, quite often. I run a small speaking club for first-year students, and I tell them exactly what she told me: slow down and trust your audience.", "phrases": [], "grammar": []}}, "model": {"answer": "If I had to pick one person, it would be my English teacher at school, Ms Dilfuza, who taught me how to speak confidently in public. She was in her fifties then, very soft-spoken, yet she had a commanding presence in the classroom. Before I met her, I was painfully shy. I’d freeze up whenever I had to answer a question, and my hands would start to shake. In Grade 9, she asked me to represent our school in a debate competition, and I nearly said no. She didn’t push me; she coached me. Every day after lessons, we practised in an empty classroom. She’d ask me to speak slowly, look at the back of the room, and pause instead of rushing. One thing she said still sticks in my mind: “Your audience wants you to succeed.” She also recorded me on her old phone, so I could iron out my bad habits, such as saying “um” every few seconds. We kept this up for a couple of months. On the day of the competition, I was shaking like a leaf backstage, yet once I started, her advice kicked in and I got through it. We didn’t win, but I’d never felt so proud. Looking back, that experience taught me that confidence is a skill, not a personality trait. Had it not been for her, I’d probably still be avoiding presentations today. It’s thanks to her that I now lead seminars at university with ease.", "sections": [{"label": "Who", "text": "If I had to pick one person, it would be my English teacher at school, Ms Dilfuza, who taught me how to speak confidently in public. She was in her fifties then, very soft-spoken, yet she had a commanding presence in the classroom."}, {"label": "What", "text": "Before I met her, I was painfully shy. I’d freeze up whenever I had to answer a question, and my hands would start to shake. In Grade 9, she asked me to represent our school in a debate competition, and I nearly said no."}, {"label": "How", "text": "She didn’t push me; she coached me. Every day after lessons, we practised in an empty classroom. She’d ask me to speak slowly, look at the back of the room, and pause instead of rushing. One thing she said still sticks in my mind: “Your audience wants you to succeed.” She also recorded me on her old phone, so I could iron out my bad habits, such as saying “um” every few seconds. We kept this up for a couple of months."}, {"label": "Why", "text": "On the day of the competition, I was shaking like a leaf backstage, yet once I started, her advice kicked in and I got through it. We didn’t win, but I’d never felt so proud. Looking back, that experience taught me that confidence is a skill, not a personality trait. Had it not been for her, I’d probably still be avoiding presentations today. It’s thanks to her that I now lead seminars at university with ease."}], "phrases": [["soft-spoken", "having a quiet, gentle voice"], ["commanding presence", "a manner that naturally gets respect and attention"], ["painfully shy", "extremely shy and uncomfortable"], ["freeze up", "be unable to speak or move because of nerves"], ["stick in one’s mind", "be remembered clearly"], ["iron out", "remove small problems"], ["keep up", "continue doing"], ["shake like a leaf", "tremble with nerves"], ["kick in", "begin to have an effect"], ["looking back", "when I think about the past"], ["had it not been for", "if something had not happened"], ["lead seminars", "run discussion classes"]], "grammar": [{"pattern": "Second conditional with who-clause", "use": "If I had to + verb, it would be + noun, who + past simple", "example": "If I had to pick one person, it would be my English teacher at school, Ms Dilfuza, who taught me how to speak confidently in public", "try": "If I had to pick one person, it would be ______, who ______."}, {"pattern": "would for past habit", "use": "She’d + verb", "example": "She’d ask me to speak slowly", "try": "My teacher would ask me to ______."}, {"pattern": "Whenever clause", "use": "whenever + past simple", "example": "whenever I had to answer a question", "try": "I’d freeze up whenever ______."}, {"pattern": "Past perfect with never", "use": "I’d never + past participle + so + adjective", "example": "I’d never felt so proud", "try": "I’d never felt so ______."}, {"pattern": "Mixed conditional with inversion", "use": "Had it not been for + noun, I’d + verb", "example": "Had it not been for her, I’d probably still be avoiding presentations today", "try": "Had it not been for ______, I’d ______."}, {"pattern": "Cleft with it’s thanks to", "use": "It’s thanks to + noun + that + clause", "example": "It’s thanks to her that I now lead seminars at university with ease", "try": "It’s thanks to ______ that ______."}]}}, "part3": {"intro": "We’ve been talking about a person who taught you a skill, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Person who taught you a skill", "title": "Person who taught you a skill", "questions": [{"q": "Is it important for people to keep learning new skills throughout their lives?", "model": {"answer": "Absolutely, because the world changes faster than any one education can keep up with. Jobs that exist today may be automated tomorrow, so people who keep upskilling stay employable. Beyond career reasons, learning keeps the mind sharp and gives retirement a sense of purpose. Whoever stops learning risks being left behind, both professionally and personally. Learning shouldn’t stop when school does.", "phrases": [["keep upskilling", "continue improving one’s skills"], ["employable", "attractive to employers"], ["sharp", "mentally quick and alert"], ["sense of purpose", "a feeling that life has meaning"], ["risk being left behind", "be in danger of falling behind others"]], "grammar": [{"pattern": "Comparative with than", "use": "faster than + noun + can + verb", "example": "faster than any one education can keep up with", "try": "The world changes faster than ______ can ______."}, {"pattern": "Whoever", "use": "Whoever + verb + verb", "example": "Whoever stops learning risks being left behind", "try": "Whoever ______ risks ______."}]}}, {"q": "Is it harder for older people to learn new skills?", "model": {"answer": "Partly. Older learners often take longer to memorise new information, and some can be set in their ways. On the other hand, they have advantages: life experience, discipline and clear motivation. My aunt took up English at fifty and made steady progress, not because it was easy but because she practised daily. So it’s more a matter of attitude than age.", "phrases": [["memorise", "learn by heart"], ["set in one’s ways", "unwilling to change habits"], ["take up", "begin a new activity"], ["make progress", "improve gradually"], ["a matter of attitude", "depending on one’s mindset"]], "grammar": [{"pattern": "not… but", "use": "not because A but because B", "example": "not because it was easy but because she practised daily", "try": "She succeeded not because ______ but because ______."}, {"pattern": "more… than", "use": "more a matter of A than B", "example": "more a matter of attitude than age", "try": "It’s more a matter of ______ than ______."}]}}, {"q": "What practical skills can young people teach older people?", "model": {"answer": "Mostly digital skills. Young people can show their parents how to set up a video call, spot a scam message or use online banking safely. Many older people are reluctant to try in case they break something, so a patient explanation goes a long way. If teenagers took the time to do this regularly, it would ease older people’s anxiety and bring the generations closer.", "phrases": [["set up", "arrange or install"], ["spot", "notice"], ["reluctant", "unwilling"], ["go a long way", "be very helpful"], ["ease", "make less severe"]], "grammar": [{"pattern": "in case", "use": "in case + present simple", "example": "in case they break something", "try": "They hesitate in case ______."}, {"pattern": "Second conditional", "use": "If + past simple, it would + verb", "example": "If teenagers took the time to do this regularly, it would ease older people’s anxiety", "try": "If teenagers ______, it would ______."}]}}, {"q": "What can younger people learn from older people?", "model": {"answer": "Patience and perspective, mainly. Older people have been through setbacks, so they know that hard times pass, which is reassuring for a generation that expects instant results. They can also teach practical skills such as cooking from scratch, budgeting or fixing things around the house. My grandmother, for instance, can make a meal out of almost nothing, which I find genuinely impressive.", "phrases": [["go through", "experience something difficult"], ["reassuring", "making you feel less worried"], ["cook from scratch", "prepare food from basic ingredients"], ["fix things around the house", "do small repairs at home"], ["make a meal out of almost nothing", "cook well with very few ingredients"]], "grammar": [{"pattern": "Present perfect", "use": "have + past participle", "example": "Older people have been through setbacks", "try": "Older people have ______."}, {"pattern": "Relative clause with that", "use": "a generation that + verb", "example": "a generation that expects instant results", "try": "a generation that ______."}]}}, {"q": "Where can people learn practical skills?", "model": {"answer": "These days, almost anywhere. Vocational colleges and workshops are the traditional route, and they give you hands-on practice with feedback. But video tutorials have opened up a whole new option: you can learn to change a tyre or bake bread for free. Apprenticeships work well too, since you learn alongside experienced people. The best route depends on how complex the skill is.", "phrases": [["hands-on", "involving direct practice"], ["open up", "create new possibilities"], ["apprenticeship", "a period of learning a trade at work"], ["learn alongside", "learn together with"], ["depend on", "be decided by"]], "grammar": [{"pattern": "Present perfect", "use": "have + opened up", "example": "video tutorials have opened up a whole new option", "try": "______ have opened up ______."}, {"pattern": "Embedded question", "use": "depends on + how + adjective + subject + is", "example": "The best route depends on how complex the skill is", "try": "The best route depends on how ______ the ______ is."}]}}, {"q": "Who would you prefer to learn a skill from, friends, teachers or parents?", "model": {"answer": "It depends on the skill, but friends are the most approachable. There’s no pressure, so you can ask silly questions without feeling judged, and you pick things up by doing them together. Teachers, on the other hand, know how to structure a lesson, which suits academic subjects. Parents are patient but often too close to be objective. So I’d choose a friend for something casual, like cooking.", "phrases": [["approachable", "easy to talk to"], ["no pressure", "no stress to perform"], ["ask silly questions", "ask things you fear sound stupid"], ["pick up", "learn informally"], ["too close to be objective", "too involved to judge fairly"]], "grammar": [{"pattern": "without + -ing", "use": "without + feeling + adjective", "example": "without feeling judged", "try": "You can ask questions without feeling ______."}, {"pattern": "too + adjective + to", "use": "too + adjective + to + verb", "example": "too close to be objective", "try": "Parents are often too ______ to ______."}]}}, {"q": "Can computer games help people develop useful skills?", "model": {"answer": "To an extent, yes. Strategy games sharpen problem-solving and planning, and fast-paced ones can improve hand–eye coordination and reaction time. Multiplayer games also teach teamwork and communication. The catch is balance: hours of gaming can eat into study and sleep. Used in moderation, they’re a useful supplement, not a substitute for real-world practice. My younger brother, for instance, picked up much of his English from them.", "phrases": [["sharpen problem-solving", "improve the ability to solve problems"], ["hand–eye coordination", "the link between what you see and your movements"], ["teamwork", "working well with others"], ["eat into", "reduce gradually"], ["in moderation", "in reasonable amounts"]], "grammar": [{"pattern": "Participle clause", "use": "Used + adverbial, + clause", "example": "Used in moderation, they’re a useful supplement", "try": "Used ______, they’re ______."}, {"pattern": "not… but contrast", "use": "a + noun, not a + noun", "example": "a useful supplement, not a substitute for real-world practice", "try": "It’s a useful ______, not a ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "People"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000049', 1049, 'Topic 49', 'Old person', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 49, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe an older person you admire", "bullets": ["who this person is", "how you know this person", "what you like to do together", "how you feel about this person"], "explain": "", "notes": ["Who", "How I Know Him", "Together", "Feelings"], "rounding": {"q": "Do you think you’ll be like him when you’re older?", "model": {"answer": "I hope so, at least in terms of staying curious. If I can still learn new things and listen to young people at seventy-eight, I’ll consider that a real success.", "phrases": [], "grammar": []}}, "model": {"answer": "If I had to pick one person, it would be my grandfather, Anvar, who’s seventy-eight now and a retired geography teacher. He’s a man of few words, yet he commands respect without ever raising his voice. Obviously I’ve known him all my life, but we really grew close when I was about twelve. My parents were working long hours back then, so I spent most summers at his house outside Bukhara, tagging along wherever he went. Whenever I think of him, I picture a straw hat and a battered notebook full of sketches of birds. These days we still go for a walk every Friday morning, and we put the world to rights over a pot of green tea. Last spring, for instance, he taught me how to graft apricot trees, which turned out to be far more fiddly than he’d made it look. What struck me was his patience: he simply let me ruin three branches before saying a word. Not once did he make me feel small. What I admire most is that he’s never been set in his ways. He’ll happily ask me to explain my phone to him, and he listens to the answer. If it weren’t for him, I’d probably have given up on my studies in my first year, when I was at a low ebb. I look up to him enormously. Looking back, he taught me that a person doesn’t have to say much to leave a lasting impression.", "sections": [{"label": "Who", "text": "If I had to pick one person, it would be my grandfather, Anvar, who’s seventy-eight now and a retired geography teacher. He’s a man of few words, yet he commands respect without ever raising his voice."}, {"label": "How I Know Him", "text": "Obviously I’ve known him all my life, but we really grew close when I was about twelve. My parents were working long hours back then, so I spent most summers at his house outside Bukhara, tagging along wherever he went. Whenever I think of him, I picture a straw hat and a battered notebook full of sketches of birds."}, {"label": "Together", "text": "These days we still go for a walk every Friday morning, and we put the world to rights over a pot of green tea. Last spring, for instance, he taught me how to graft apricot trees, which turned out to be far more fiddly than he’d made it look. What struck me was his patience: he simply let me ruin three branches before saying a word. Not once did he make me feel small."}, {"label": "Feelings", "text": "What I admire most is that he’s never been set in his ways. He’ll happily ask me to explain my phone to him, and he listens to the answer. If it weren’t for him, I’d probably have given up on my studies in my first year, when I was at a low ebb. I look up to him enormously. Looking back, he taught me that a person doesn’t have to say much to leave a lasting impression."}], "phrases": [["a man of few words", "someone who speaks very little"], ["command respect", "make people respect you naturally"], ["grow close", "become emotionally close over time"], ["tag along", "go somewhere with someone, often as a follower"], ["put the world to rights", "discuss and ‘solve’ all the world’s problems in a friendly chat"], ["fiddly", "awkward and needing small, careful movements"], ["make (someone) feel small", "make someone feel stupid or unimportant"], ["set in his ways", "unwilling to change habits or opinions"], ["at a low ebb", "in a low state, sad or discouraged"], ["look up to", "admire and respect"], ["leave a lasting impression", "have an effect that people remember for a long time"]], "grammar": [{"pattern": "Second conditional with ‘if it", "use": "weren’t for’ If it weren’t for + noun, I’d + (have +) verb", "example": "If it weren’t for him, I’d probably have given up on my studies", "try": "If it weren’t for ______, I’d probably ______."}, {"pattern": "Inversion with ‘Not once’", "use": "Not once + did + subject + base verb", "example": "Not once did he make me feel small", "try": "Not once did ______ ______."}, {"pattern": "Non-defining relative clause with which", "use": "…, which + verb: comments on the whole previous idea", "example": "which turned out to be far more fiddly than he’d made it look", "try": "…, which turned out to be ______."}, {"pattern": "Present perfect with ‘never’", "use": "has/have never been + adjective phrase", "example": "he’s never been set in his ways", "try": "She’s never been ______."}, {"pattern": "Defining ‘when’ clause", "use": "time + when + clause", "example": "when I was at a low ebb", "try": "...in my first year, when I ______."}]}}, "part3": {"intro": "We’ve been talking about an older person you admire, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Old person", "title": "Old person", "questions": [{"q": "What can young people learn from older people?", "model": {"answer": "Quite a lot, but mostly how to keep things in perspective. Having been through hard times themselves, older people tend not to panic over minor setbacks. They can also pass on practical skills that textbooks don’t teach, such as cooking or mending things. The more time young people spend listening, the better they understand where their families come from and who they take after, which is a valuable lesson.", "phrases": [["keep things in perspective", "see a problem as it really is, not bigger than it is"], ["minor setback", "a small problem or delay"], ["pass on", "give knowledge or skills to someone younger"], ["take after", "be similar to an older family member"], ["valuable", "useful and worth learning"]], "grammar": [{"pattern": "The more… the better…", "use": "The more + clause, the better + clause", "example": "The more time young people spend listening, the better they understand", "try": "The more I ______, the better I ______."}, {"pattern": "Participle clause", "use": "Having + past participle, clause", "example": "Having been through hard times themselves", "try": "Having ______, she ______."}]}}, {"q": "Do you think older people enjoy life more now than they did in the past?", "model": {"answer": "In many ways, yes. My grandparents’ generation worked hard well into their sixties, whereas today’s retirees often have a decent pension, better healthcare and plenty of spare time. Some of them take up new hobbies or travel abroad, which would have been unthinkable fifty years ago. That said, loneliness is still a real problem when their children move away to big cities and only keep in touch by phone.", "phrases": [["spare time", "free time when you don’t have to work"], ["take up", "start a new hobby or activity"], ["unthinkable", "impossible to imagine"], ["move away", "leave to live in another place"], ["keep in touch", "stay in contact"]], "grammar": [{"pattern": "Contrast with whereas", "use": "clause 1, whereas clause 2", "example": "whereas today’s retirees often have a decent pension", "try": "My parents worked long hours, whereas ______."}, {"pattern": "Would have been + adjective", "use": "would have been + adjective: a past comparison", "example": "which would have been unthinkable fifty years ago", "try": "…, which would have been ______ years ago."}]}}, {"q": "Can older and younger people share the same interests?", "model": {"answer": "Absolutely, though it depends on the activity. Football, cooking and old films tend to bring generations together, because you don’t need to be the same age to enjoy them. My grandfather and I bond over chess, for example, and he still beats me. The real barrier isn’t age; it’s whether either side is willing to meet the other halfway and give it a go.", "phrases": [["bring generations together", "make people feel united"], ["bond over", "become closer by sharing an activity"], ["barrier", "something that stops progress or contact"], ["meet (someone) halfway", "compromise with someone"], ["give it a go", "try something"]], "grammar": [{"pattern": "Whether-clause", "use": "it’s + whether + subject + verb", "example": "it’s whether either side is willing to meet the other halfway", "try": "What matters is whether ______."}, {"pattern": "Because + you (general)", "use": "because + you + verb: a general reason", "example": "because you don’t need to be the same age to enjoy them", "try": "...because you don’t need to ______."}]}}, {"q": "What activities do older people like to do these days?", "model": {"answer": "Judging by my neighbourhood, it’s quite a mixed bag. Many of the men play chess or dominoes in the courtyard, while the women get together for tea and catch up on the latest news. More and more retired people also keep fit by walking in the park early in the morning. A few have even taken to video calls, which keeps them in the loop with grandchildren abroad.", "phrases": [["a mixed bag", "a variety of different things"], ["catch up on", "talk about recent news"], ["keep fit", "stay physically healthy"], ["take to", "begin to do something as a habit"], ["in the loop", "kept informed about what is happening"]], "grammar": [{"pattern": "Participle opening", "use": "Judging by + noun, clause", "example": "Judging by my neighbourhood, it’s quite a mixed bag", "try": "Judging by ______, ______."}, {"pattern": "More and more", "use": "More and more + noun + verb", "example": "More and more retired people also keep fit", "try": "More and more people ______."}]}}, {"q": "Who should take care of elderly people, their families or the government?", "model": {"answer": "Ideally both, but the family should come first. If elderly people live with relatives, they feel valued, and that’s something no care home can fully replace. However, families can’t always shoulder the burden alone, especially when an illness is serious, so the state has to step in with pensions and proper healthcare. It’s really a shared responsibility, and each side should pull its weight.", "phrases": [["shoulder the burden", "accept a heavy responsibility"], ["step in", "get involved to help"], ["shared responsibility", "a duty that more than one party has"], ["pull its weight", "do a fair share of the work"], ["fully replace", "completely take the place of"]], "grammar": [{"pattern": "Zero conditional", "use": "If + present simple, present simple", "example": "If elderly people live with relatives, they feel valued", "try": "If children ______, they ______."}, {"pattern": "Relative clause with that", "use": "something + no + noun + can + verb", "example": "that’s something no care home can fully replace", "try": "That’s something no ______ can ______."}]}}, {"q": "How do older people contribute to society?", "model": {"answer": "Far more than they’re given credit for. Many look after grandchildren, which allows parents to go out to work. Others volunteer at schools or local charities, drawing on decades of experience. Then there’s the knowledge they hold, from traditional crafts to local history, which would be lost for good if nobody recorded it. Society would be poorer without them, and in a very real sense they hold communities together.", "phrases": [["given credit for", "be recognised for something"], ["draw on", "use knowledge or experience"], ["lost for good", "lost forever"], ["poorer", "with less value (not only money)"], ["in a very real sense", "truly, not just in theory"]], "grammar": [{"pattern": "Passive with would", "use": "would + be + past participle + if…", "example": "which would be lost for good if nobody recorded it", "try": "…, which would be ______ if ______."}, {"pattern": "", "use": "Passive: given credit be given credit for + noun/-ing", "example": "Far more than they’re given credit for", "try": "He’s not given enough credit for ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "People"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000050', 1050, 'Topic 50', 'Person who is good at making things by hand', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 50, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a person who is good at making things by hand", "bullets": ["who this person is", "how you know this person", "what talent this person possesses", "why you admire this person"], "explain": "", "notes": ["Who", "How I Know Him", "Talent", "Why I Admire Him"], "rounding": {"q": "Would you like to learn a craft like that yourself?", "model": {"answer": "Definitely. I’d love to try pottery properly, even if my first few pieces end up as flowerpots. Working with your hands is a great way to switch off from screens.", "phrases": [], "grammar": []}}, "model": {"answer": "The first person who comes to mind is Mr Rahimov, a potter from Rishton, a small town in the Fergana Valley that’s famous for its ceramics. He’s in his late fifties and, as far as I can tell, has had clay under his fingernails for most of his life. I know him through my university friend Sardor, who happens to be his son. Two summers ago Sardor invited me to spend a week at the family workshop, and I ended up hanging around there far longer than I’d planned, simply because I couldn’t stop watching. What he can do with a lump of clay still amazes me. Within minutes he throws a bowl on the wheel, with walls so thin that light almost shines through, and then he decorates it freehand with the traditional blue and turquoise patterns. He clearly has a knack for it, but when I tried, I produced something resembling a lopsided flowerpot. He just laughed and told me his first decent bowl had taken him ten years. What I admire is not only his skill but also his integrity. He could easily have switched to mass-produced tiles, which would pay far better, yet he puts his heart and soul into every piece and fires it in a wood kiln, the way his father did. He takes pride in getting every detail right, and to him it’s a labour of love. I respect anyone who keeps a dying art alive at a time when cheap imports are everywhere. Honestly, he’s made me value things that are made by hand.", "sections": [{"label": "Who", "text": "The first person who comes to mind is Mr Rahimov, a potter from Rishton, a small town in the Fergana Valley that’s famous for its ceramics. He’s in his late fifties and, as far as I can tell, has had clay under his fingernails for most of his life."}, {"label": "How I Know Him", "text": "I know him through my university friend Sardor, who happens to be his son. Two summers ago Sardor invited me to spend a week at the family workshop, and I ended up hanging around there far longer than I’d planned, simply because I couldn’t stop watching."}, {"label": "Talent", "text": "What he can do with a lump of clay still amazes me. Within minutes he throws a bowl on the wheel, with walls so thin that light almost shines through, and then he decorates it freehand with the traditional blue and turquoise patterns. He clearly has a knack for it, but when I tried, I produced something resembling a lopsided flowerpot. He just laughed and told me his first decent bowl had taken him ten years."}, {"label": "Why I Admire Him", "text": "What I admire is not only his skill but also his integrity. He could easily have switched to mass-produced tiles, which would pay far better, yet he puts his heart and soul into every piece and fires it in a wood kiln, the way his father did. He takes pride in getting every detail right, and to him it’s a labour of love. I respect anyone who keeps a dying art alive at a time when cheap imports are everywhere. Honestly, he’s made me value things that are made by hand."}], "phrases": [["hang around", "spend time somewhere with no particular purpose"], ["throw (a pot)", "shape clay on a spinning potter’s wheel"], ["freehand", "drawn or painted without a guide or tracing"], ["have a knack for", "have a natural ability to do something well"], ["lopsided", "uneven, with one side higher or bigger than the other"], ["put your heart and soul into", "give all your energy and passion to something"], ["take pride in", "feel proud of your work and do it carefully"], ["a labour of love", "work done for love of it, not for money"], ["keep a dying art alive", "continue a tradition that is disappearing"], ["by hand", "made with hands, not machines"]], "grammar": [{"pattern": "Not only… but also…", "use": "not only + noun/adjective + but also + noun", "example": "not only his skill but also his integrity", "try": "I admire not only her ______ but also her ______."}, {"pattern": "", "use": "Modal perfect: could have could (easily) have + past participle: a possibility not taken", "example": "He could easily have switched to mass-produced tiles", "try": "She could easily have ______."}, {"pattern": "the way + subject + did", "use": "the way + subject + did: comparing how things are done", "example": "the way his father did", "try": "...the way my mother ______."}, {"pattern": "Past perfect", "use": "had + past participle: earlier past", "example": "his first decent bowl had taken him ten years", "try": "My first attempt had taken me ______."}, {"pattern": "Participle clause (resembling)", "use": "something + -ing phrase: reduced relative clause", "example": "something resembling a lopsided flowerpot", "try": "I produced something resembling ______."}, {"pattern": "Relative clause with which", "use": "…, which would + verb", "example": "which would pay far better", "try": "...a job, which would ______."}]}}, "part3": {"intro": "We’ve been talking about a person who is good at making things by hand, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Person who is good at making things by hand", "title": "Person who is good at making things by hand", "questions": [{"q": "Why do some people enjoy making things by hand?", "model": {"answer": "Probably because it gives them a tangible result. After a day of emails and screens, you can hold what you’ve made, and that’s deeply satisfying. It’s also therapeutic, since your hands are busy and your mind slows down. What’s more, a handmade gift means a lot more than something off the shelf, because the maker has put time and care into it.", "phrases": [["tangible", "real and able to be touched or seen"], ["therapeutic", "calming and good for your mind"], ["mean a lot", "be very important emotionally"], ["off the shelf", "ready-made, not personal"], ["put time and care into", "spend effort carefully on something"]], "grammar": [{"pattern": "Because-clause with present", "use": "perfect because + subject + has/have + past participle", "example": "because the maker has put time and care into it", "try": "...because the writer has ______."}, {"pattern": "Cleft-style ‘What’s more’", "use": "What’s more, + clause: adds a stronger point", "example": "What’s more, a handmade gift means a lot more", "try": "What’s more, ______."}]}}, {"q": "Are art classes important in schools?", "model": {"answer": "On the one hand, they can seem like a luxury when schools are under pressure to improve exam results. On the other hand, art develops creativity and fine motor skills, and it gives quieter pupils a way to express themselves. In my experience, children who struggle with maths sometimes come into their own in the art room, so dropping it would be a real mistake.", "phrases": [["creativity", "the ability to produce new ideas"], ["fine motor skills", "precise hand movements, such as drawing or writing"], ["express yourself", "show your ideas and feelings"], ["come into your own", "show your best qualities for the first time"], ["a luxury", "something nice but not essential"]], "grammar": [{"pattern": "On the one hand… on the other", "use": "hand… On the one hand, … On the other hand, …", "example": "On the one hand, they can seem like a luxury", "try": "On the one hand, ______. On the other hand, ______."}, {"pattern": "Relative clause with who", "use": "children who + verb", "example": "children who struggle with maths", "try": "Students who ______ often ______."}]}}, {"q": "Should all children learn to draw?", "model": {"answer": "At a basic level, yes, though not necessarily to a high standard. Drawing trains you to observe things closely, which helps in subjects like geography or biology. Were it made compulsory at an advanced level, some children would simply lose heart. It’s better to let them enjoy the process than to expect everyone to produce masterpieces, and a bit of encouragement goes a long way.", "phrases": [["compulsory", "required by rule"], ["lose heart", "stop believing you can succeed"], ["enjoy the process", "like doing something rather than only caring about the result"], ["produce a masterpiece", "create an excellent piece of art"], ["encouragement goes a long way", "a little support helps a lot"]], "grammar": [{"pattern": "Inverted second conditional", "use": "Were + subject + (to) + verb, subject + would…", "example": "Were it made compulsory at an advanced level, some children would simply lose heart", "try": "Were it ______, people would ______."}, {"pattern": "better to… than to…", "use": "It’s better to + verb than to + verb", "example": "It’s better to let them enjoy the process than to expect everyone", "try": "It’s better to ______ than to ______."}]}}, {"q": "Is it easy to identify children’s talents?", "model": {"answer": "Not really, because talent often shows itself late or in unexpected ways. A boy may seem uninterested in school and then light up when he’s handed a camera. Schools rely heavily on exam scores, which only measure a narrow range of ability. That’s why parents and teachers should offer children a wide range of activities and watch what they gravitate towards.", "phrases": [["show itself", "become visible"], ["light up", "suddenly become happy and interested"], ["rely heavily on", "depend a great deal on"], ["a wide range of", "many different kinds of"], ["gravitate towards", "naturally move towards or choose"]], "grammar": [{"pattern": "Reduced concession with may", "use": "subject + may + verb, and then + clause", "example": "A boy may seem uninterested in school and then light up", "try": "A child may ______ and then ______."}, {"pattern": "Relative clause with which", "use": "…, which + verb", "example": "which only measure a narrow range of ability", "try": "..., which only ______."}]}}, {"q": "Do you think handmade products will become less common in the future?", "model": {"answer": "I’d expect them to become rarer, but also more valuable. Factories will keep producing cheaper goods, so everyday items like plates and clothes will increasingly be made by machine. Yet people are willing to pay a premium for something one of a kind, which is why I believe skilled craftspeople will survive as a niche market rather than disappear altogether.", "phrases": [["willing to pay a premium", "ready to pay extra for quality"], ["one of a kind", "unique"], ["survive", "continue to exist"], ["niche market", "a small, specialised group of buyers"], ["altogether", "completely"]], "grammar": [{"pattern": "Future passive", "use": "will + be + past participle", "example": "will increasingly be made by machine", "try": "Most goods will be ______ by ______."}, {"pattern": "Which is why", "use": "…, which is why + clause", "example": "which is why I believe skilled craftspeople will survive", "try": "..., which is why ______."}]}}, {"q": "Can art created by AI be as good as art made by humans?", "model": {"answer": "Technically, it can already look impressive, but I’m not convinced it’s as good. Art isn’t just about the finished image; it’s about the person behind it, their experience and intention. Once you know a picture was generated in seconds, it loses some of its emotional weight. That said, AI could be a useful tool in the hands of a real artist, rather than a substitute for one.", "phrases": [["impressive", "causing admiration"], ["lose some of its emotional weight", "become less moving"], ["That said", "however (adds a contrast)"], ["in the hands of", "used by"], ["substitute", "a replacement"]], "grammar": [{"pattern": "Not just… it’s about…", "use": "X isn’t just about A; it’s about B", "example": "Art isn’t just about the finished image; it’s about the person behind it", "try": "Learning isn’t just about ______; it’s about ______."}, {"pattern": "Once + present/past passive", "use": "Once you know + clause, …", "example": "Once you know a picture was generated in seconds", "try": "Once you know ______, ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "People"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000051', 1051, 'Topic 51', 'Enjoyable evening with friends', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 51, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe an enjoyable evening you spent with your friends", "bullets": ["who you were with", "where you were", "what you did, ate or talked about", "and explain why the evening was enjoyable"], "explain": "", "notes": ["Who", "Where", "What We Did", "Why It Was Enjoyable"], "rounding": {"q": "Do you often get together with the same group of friends?", "model": {"answer": "Not as often as I’d like, to be honest. We try to meet a couple of times a year, and each time we pick up exactly where we left off.", "phrases": [], "grammar": []}}, "model": {"answer": "One evening I’ll never forget was last July, when five of my old university friends and I got together at Timur’s family dacha near Chimgan. We hadn’t all been in the same place since graduation, so it felt like a small reunion. The dacha sits on a hillside with a long wooden terrace facing the mountains, and the air up there is far cooler and cleaner than in Tashkent. We arrived around five, just as the sun was sinking behind the ridge. Timur took charge of the shashlik, insisting that nobody else touch the grill, while the rest of us chopped salad and argued about the music. After dinner we sat around a lantern and reminisced about the dreadful group project that had nearly cost us our degrees. Halfway through the story, the power cut out, and rather than complain, we carried on by torchlight, with Aziz strumming his guitar badly. We completely lost track of time, and it was past two when someone finally noticed. What made the evening so enjoyable was how effortless it felt. Nobody was in a rush, nobody checked their phones, and we could be ourselves without trying to impress anyone. It was a breath of fresh air after a stressful month at work. Had the power not gone off, we’d probably have ended up scrolling through videos instead of talking. Looking back, I realise that good company matters more than any fancy venue, and that friendships only stand the test of time if you make an effort to keep them alive.", "sections": [{"label": "Who", "text": "One evening I’ll never forget was last July, when five of my old university friends and I got together at Timur’s family dacha near Chimgan. We hadn’t all been in the same place since graduation, so it felt like a small reunion."}, {"label": "Where", "text": "The dacha sits on a hillside with a long wooden terrace facing the mountains, and the air up there is far cooler and cleaner than in Tashkent. We arrived around five, just as the sun was sinking behind the ridge."}, {"label": "What We Did", "text": "Timur took charge of the shashlik, insisting that nobody else touch the grill, while the rest of us chopped salad and argued about the music. After dinner we sat around a lantern and reminisced about the dreadful group project that had nearly cost us our degrees. Halfway through the story, the power cut out, and rather than complain, we carried on by torchlight, with Aziz strumming his guitar badly. We completely lost track of time, and it was past two when someone finally noticed."}, {"label": "Why It Was Enjoyable", "text": "What made the evening so enjoyable was how effortless it felt. Nobody was in a rush, nobody checked their phones, and we could be ourselves without trying to impress anyone. It was a breath of fresh air after a stressful month at work. Had the power not gone off, we’d probably have ended up scrolling through videos instead of talking. Looking back, I realise that good company matters more than any fancy venue, and that friendships only stand the test of time if you make an effort to keep them alive."}], "phrases": [["get together", "meet socially"], ["take charge of", "take control of and be responsible for"], ["reminisce about", "talk happily about past times"], ["cut out", "stop working suddenly"], ["carry on", "continue"], ["lose track of time", "not notice how much time has passed"], ["in a rush", "in a hurry"], ["be yourself", "behave naturally"], ["a breath of fresh air", "a refreshing change"], ["stand the test of time", "stay strong over many years"], ["make an effort", "try hard to do something"]], "grammar": [{"pattern": "Past perfect", "use": "had + past participle: an earlier past", "example": "the dreadful group project that had nearly cost us our degrees", "try": "...the exam that had nearly ______."}, {"pattern": "Cleft sentence with What", "use": "What + subject + verb + was + noun phrase / how clause", "example": "What made the evening so enjoyable was how effortless it felt", "try": "What made the trip special was ______."}, {"pattern": "Inverted third conditional", "use": "Had + subject + not + past participle, subject + would have + past participle", "example": "Had the power not gone off, we’d probably have ended up scrolling through videos", "try": "Had it not ______, we’d have ______."}, {"pattern": "Insist + subjunctive", "use": "insisting that + subject + base verb", "example": "insisting that nobody else touch the grill", "try": "...insisting that everyone ______."}, {"pattern": "Rather than + clause", "use": "rather than + base verb", "example": "rather than complain, we carried on", "try": "Rather than ______, we ______."}, {"pattern": "Only if", "use": "only + if-clause: the one condition", "example": "friendships only stand the test of time if you make an effort", "try": "Friendships only last if you ______."}]}}, "part3": {"intro": "We’ve been talking about an enjoyable evening you spent with your friends, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Enjoyable evening with friends", "title": "Enjoyable evening with friends", "questions": [{"q": "Do young people prefer spending time with their friends or with their family?", "model": {"answer": "Generally speaking, friends, at least in their teens and twenties. At that age young people want independence, and friends share the same worries and sense of humour. That doesn’t mean family takes a back seat for good, though. Once they settle down and have children of their own, many turn back to their relatives, so the preference shifts quite naturally with age.", "phrases": [["generally speaking", "in most cases"], ["take a back seat", "become less important"], ["settle down", "start a stable life with a home or family"], ["turn back to", "return to for support"], ["shift with age", "change as people get older"]], "grammar": [{"pattern": "Time clause with once", "use": "Once + subject + verb, main clause", "example": "Once they settle down and have children of their own, many turn back to their relatives", "try": "Once I ______, I’ll ______."}, {"pattern": "Doesn’t mean… though", "use": "That doesn’t mean + clause, though", "example": "That doesn’t mean family takes a back seat for good, though", "try": "That doesn’t mean ______, though."}]}}, {"q": "What is the difference between spending time with friends and spending time with family?", "model": {"answer": "With family, you take it for granted that people will accept you, whereas with friends you choose each other. Family time often follows routines and expectations, like Friday dinners at the grandparents’ house. Time with friends is looser and more spontaneous, and you can talk about things you’d never mention to your parents. In the end the two complement each other rather than compete.", "phrases": [["take it for granted", "assume something without thinking"], ["routines", "fixed, regular ways of doing things"], ["spontaneous", "unplanned and natural"], ["complement each other", "go well together and add something different"], ["compete", "try to win against each other"]], "grammar": [{"pattern": "Whereas contrast", "use": "clause, whereas clause", "example": "whereas with friends you choose each other", "try": "______, whereas ______."}, {"pattern": "Would + never", "use": "things + you’d never + verb", "example": "things you’d never mention to your parents", "try": "There are things I’d never ______."}]}}, {"q": "Why do people need friends?", "model": {"answer": "Because friends provide something family often can’t: a fresh perspective. They’re the ones who lift your spirits after a bad day and tell you honestly when you’re making a mistake. Without them, people can end up isolated, which is bad for mental health. Friendship also teaches us to compromise, a skill we need at work and in marriage as much as in a social life.", "phrases": [["a fresh perspective", "a new way of looking at something"], ["lift your spirits", "make you feel happier"], ["make a mistake", "do something wrong"], ["end up isolated", "finally become alone and cut off"], ["compromise", "accept less than you wanted to reach an agreement"]], "grammar": [{"pattern": "Relative clause with who", "use": "the ones who + verb", "example": "They’re the ones who lift your spirits after a bad day", "try": "They’re the ones who ______."}, {"pattern": "Without + noun, subject + can", "use": "Without + pronoun, + clause", "example": "Without them, people can end up isolated", "try": "Without ______, people can ______."}]}}, {"q": "How do people in your country usually spend their evenings?", "model": {"answer": "It varies, but there’s a strong tradition of gathering at home. In summer, families sit out in the courtyard drinking tea and eating fruit until late, while in cities young people head to cafés or stroll along the main avenues. On weekdays, though, most people are worn out after work and simply have dinner and unwind in front of the TV.", "phrases": [["gather", "come together as a group"], ["sit out", "sit outside"], ["stroll", "walk slowly for pleasure"], ["worn out", "very tired"], ["unwind", "relax after work or stress"]], "grammar": [{"pattern": "There’s a tradition of -ing", "use": "There’s a strong tradition of + -ing", "example": "there’s a strong tradition of gathering at home", "try": "There’s a tradition of ______ in my country."}, {"pattern": "", "use": "Participle: sit out + -ing sit + -ing: describes an activity", "example": "families sit out in the courtyard drinking tea and eating fruit", "try": "We sit ______ chatting."}]}}, {"q": "Does eating together help friends or families become closer?", "model": {"answer": "Yes, I’m convinced it does. A shared meal slows everyone down, so people actually talk rather than rushing off. In my family, the evening meal is where news is exchanged and disagreements get ironed out. It’s hard to stay cross with someone while you’re passing them a dish. It only works, however, if phones are put away; otherwise everyone is physically present but mentally elsewhere.", "phrases": [["slow (someone) down", "make someone less hurried"], ["exchanged", "shared, told to each other"], ["iron out", "solve small problems or disagreements"], ["pass (a dish)", "hand food across the table"], ["physically present but mentally elsewhere", "there in body but thinking about something else"]], "grammar": [{"pattern": "Cleft with where", "use": "X is where + clause", "example": "the evening meal is where news is exchanged", "try": "The kitchen is where ______."}, {"pattern": "Passive with get", "use": "get + past participle", "example": "disagreements get ironed out", "try": "Problems get ______."}]}}, {"q": "How has technology changed the way friends spend time together?", "model": {"answer": "Quite dramatically. Twenty years ago friends had to arrange to meet in person; nowadays they can chat, play games or watch films together without leaving home. That’s convenient, but there’s a downside: a group can sit in the same room and still be glued to their screens. Used wisely, technology keeps friends connected across distances, but it can’t replace a face-to-face evening.", "phrases": [["arrange", "plan and organise"], ["a downside", "a disadvantage"], ["still be glued to", "keep looking at, unable to stop"], ["keep (friends) connected", "help them stay in contact"], ["can’t replace", "can’t take the place of"]], "grammar": [{"pattern": "Participle clause with used", "use": "Used + adverb, + clause (passive participle)", "example": "Used wisely, technology keeps friends connected", "try": "Used ______, it can ______."}, {"pattern": "Twenty years ago + had to", "use": "had to + base verb: past necessity", "example": "friends had to arrange to meet in person", "try": "Years ago people had to ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Events & experiences"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000052', 1052, 'Topic 52', 'Sports person you admire', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 52, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a sports person you admire", "bullets": ["who this person is", "what this person has achieved", "how you know about this person", "explain why you like this person"], "explain": "", "notes": ["Who", "Achievemen Ts", "How I Know About Him", "Why I Like Him"], "rounding": {"q": "Have you ever tried playing tennis yourself?", "model": {"answer": "Yes, a little. I played with my uncle at weekends for a couple of years, and I quickly realised how tough even a basic rally is.", "phrases": [], "grammar": []}}, "model": {"answer": "The sports person I admire most is Rafael Nadal, the Spanish tennis player, who has now retired. For many fans, myself included, he’s the perfect example of what determination can achieve. His record speaks for itself: twenty-two Grand Slam singles titles, fourteen of them at the French Open, which earned him the nickname ‘the King of Clay’. He also won Olympic gold in Beijing in 2008, and again in doubles in Rio in 2016. Even more impressive is that he managed all this despite injuries that took a toll on his body and would have ended the careers of most players. I came across him as a teenager, when my uncle, a huge tennis fan, woke me up early to watch the 2008 Wimbledon final. We were glued to the screen for nearly five hours as he and Federer pushed each other to the limit. Never had I seen anything like it. Ever since, I’ve kept up with his career through interviews and documentaries. What I like most is his attitude. He would fight for every point as if it were the last, yet he stayed grounded and treated opponents with respect, even after painful defeats. He also bounced back from injury again and again, because he was prepared to put in the hours when nobody was watching. If I hadn’t seen him play, I might never have understood that talent is only the starting point. He sets an example that’s hard to forget.", "sections": [{"label": "Who", "text": "The sports person I admire most is Rafael Nadal, the Spanish tennis player, who has now retired. For many fans, myself included, he’s the perfect example of what determination can achieve."}, {"label": "Achievemen Ts", "text": "His record speaks for itself: twenty-two Grand Slam singles titles, fourteen of them at the French Open, which earned him the nickname ‘the King of Clay’. He also won Olympic gold in Beijing in 2008, and again in doubles in Rio in 2016. Even more impressive is that he managed all this despite injuries that took a toll on his body and would have ended the careers of most players."}, {"label": "How I Know About Him", "text": "I came across him as a teenager, when my uncle, a huge tennis fan, woke me up early to watch the 2008 Wimbledon final. We were glued to the screen for nearly five hours as he and Federer pushed each other to the limit. Never had I seen anything like it. Ever since, I’ve kept up with his career through interviews and documentaries."}, {"label": "Why I Like Him", "text": "What I like most is his attitude. He would fight for every point as if it were the last, yet he stayed grounded and treated opponents with respect, even after painful defeats. He also bounced back from injury again and again, because he was prepared to put in the hours when nobody was watching. If I hadn’t seen him play, I might never have understood that talent is only the starting point. He sets an example that’s hard to forget."}], "phrases": [["speak for itself", "be so clear that no explanation is needed"], ["take a toll on", "cause gradual damage to"], ["come across", "find or meet by chance"], ["be glued to", "watch something without looking away"], ["push each other to the limit", "force each other to try as hard as possible"], ["keep up with", "stay informed about"], ["fight for every point", "try hard until the very end"], ["stay grounded", "remain modest and realistic despite success"], ["bounce back", "recover quickly after a setback"], ["put in the hours", "spend a lot of time practising or working"], ["set an example", "behave in a way others can copy"]], "grammar": [{"pattern": "Cleft sentence", "use": "What + subject + verb + is + noun phrase", "example": "What I like most is his attitude", "try": "What I admire most is ______."}, {"pattern": "Would for past habit", "use": "would + base verb: typical past behaviour", "example": "He would fight for every point as if it were the last", "try": "She would always ______."}, {"pattern": "Inversion with Never", "use": "Never + had + subject + past participle", "example": "Never had I seen anything like it", "try": "Never had I ______."}, {"pattern": "Third conditional (mixed)", "use": "If + past perfect, subject + might + never + have + past participle", "example": "If I hadn’t seen him play, I might never have understood", "try": "If I hadn’t ______, I might never have ______."}, {"pattern": "Non-defining relative clause", "use": "…, which + verb", "example": "which earned him the nickname", "try": "..., which earned him ______."}, {"pattern": "Even more + adjective + is that", "use": "Even more + adjective + is that + clause", "example": "Even more impressive is that he managed all this", "try": "Even more surprising is that ______."}]}}, "part3": {"intro": "We’ve been talking about a sports person you admire, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Sports person you admire", "title": "Sports person you admire", "questions": [{"q": "Should students have to do sports at school?", "model": {"answer": "Yes, within reason. Regular exercise keeps pupils fit and sharper in lessons, as well as better at coping with exam stress, and team games teach cooperation in a way textbooks can’t. The problem is that forcing a child who hates running to compete can put them off sport for life. A flexible approach, with several activities to choose from, usually works best and keeps everyone on board.", "phrases": [["keep (someone) fit", "help someone stay healthy"], ["put (someone) off", "make someone dislike something"], ["flexible", "able to change to suit people"], ["work best", "give the best results"], ["on board", "willing to take part"]], "grammar": [{"pattern": "", "use": "Reduced relative: forcing a child who forcing + object + to + verb as subject", "example": "forcing a child who hates running to compete", "try": "Forcing students to ______ can ______."}, {"pattern": "Time-free ‘in a way’", "use": "in a way + that / (that) + subject + can’t", "example": "in a way textbooks can’t", "try": "…in a way ______ can’t."}]}}, {"q": "What qualities does an athlete need in order to be successful?", "model": {"answer": "Above all, resilience. Every athlete loses matches, gets injured and goes through a bad patch, so the ones who succeed are those who can pick themselves up and try again. Alongside that, they need discipline, because training is repetitive and often quite boring all year round. Add a supportive coach and a sensible diet, and you have the foundations of a long career.", "phrases": [["resilience", "the ability to recover from difficulty"], ["go through a bad patch", "have a difficult period"], ["pick yourself up", "recover and start again after failure"], ["discipline", "controlled, regular effort"], ["foundations", "the basic parts something is built on"]], "grammar": [{"pattern": "", "use": "Cleft: the ones who those who / the ones who + verb", "example": "the ones who succeed are those who can pick themselves up", "try": "The ones who succeed are those who ______."}, {"pattern": "Imperative + and", "use": "Add + noun, and you have + noun", "example": "Add a supportive coach and a sensible diet, and you have the foundations of a long career", "try": "Add ______, and you have ______."}]}}, {"q": "Is talent more important than hard work in sport?", "model": {"answer": "It depends on the level. At school level, hard work can make up for a lack of natural talent. At the very top, however, everyone trains relentlessly, so natural gifts, such as height or speed, can tip the balance. Plenty of gifted teenagers never turn professional because they stop pushing themselves. Still, talent that isn’t developed goes to waste, which is why I’d put hard work slightly ahead.", "phrases": [["make up for", "compensate for"], ["train relentlessly", "practise without ever easing off"], ["tip the balance", "make the deciding difference"], ["go to waste", "be lost without being used"], ["slightly ahead", "a little more important"]], "grammar": [{"pattern": "Relative clause with talent that", "use": "noun + that + isn’t + past participle", "example": "talent that isn’t developed goes to waste", "try": "Talent that isn’t ______ ______."}, {"pattern": "Such as for examples", "use": "noun, such as A or B,", "example": "natural gifts, such as height or speed,", "try": "...skills, such as ______ or ______,"}]}}, {"q": "Are sports stars good role models for young people?", "model": {"answer": "Sometimes, but not always. Athletes who lead by example, training hard and staying genuinely humble, are wonderful role models, because they prove that effort pays off. The trouble is that fame can bring scandals or flashy lifestyles, which can send the wrong message to impressionable teenagers. So I’d encourage young people to look up to a player’s work ethic rather than copy everything they do off the pitch.", "phrases": [["lead by example", "show others how to behave by doing it yourself"], ["flashy", "showy, designed to attract attention"], ["impressionable", "easily influenced"], ["look up to", "admire"], ["work ethic", "belief in working hard"]], "grammar": [{"pattern": "Relative clause with who +", "use": "participle noun + who + verb, -ing, -ing,", "example": "Athletes who lead by example, training hard and staying genuinely humble,", "try": "People who ______, ______ing and ______ing, ..."}, {"pattern": "Rather than + clause", "use": "rather than + base verb", "example": "rather than copy everything", "try": "...rather than ______."}]}}, {"q": "What kinds of sport are popular in your country?", "model": {"answer": "Football is by far the most popular, and you’ll see boys kicking a ball around on almost any patch of grass. Wrestling, boxing and judo are also well established, partly because of their long tradition here. Tennis and chess are gaining ground among younger people, especially in cities, where new clubs have been opening and parents are keen to get their children involved.", "phrases": [["kick a ball around", "play casually with a football"], ["well established", "firmly in place for a long time"], ["gain ground", "become more popular"], ["keen to", "eager to"], ["involved", "taking part"]], "grammar": [{"pattern": "By far + superlative", "use": "by far the + superlative", "example": "by far the most popular", "try": "...is by far the ______."}, {"pattern": "Present perfect continuous", "use": "have/has + been + -ing", "example": "new clubs have been opening", "try": "New ______ have been ______ing lately."}]}}, {"q": "Why do so few people become top athletes?", "model": {"answer": "Because the odds are stacked against them. Only a tiny number of people have the right physical gifts, and even they need years of training, good coaching and a fair share of luck. Many drop out early because of injury or the cost of equipment and travel. It takes not only talent but also sacrifice, and most people aren’t prepared to give up their social lives.", "phrases": [["the odds are stacked against (someone)", "the situation makes success very unlikely"], ["drop out", "stop before finishing"], ["a fair share of", "a reasonable amount of"], ["sacrifice", "giving up something valuable for a goal"], ["be prepared to", "be willing to"]], "grammar": [{"pattern": "Not only… but also…", "use": "It takes not only A but also B", "example": "It takes not only talent but also sacrifice", "try": "It takes not only ______ but also ______."}, {"pattern": "Because of + noun", "use": "because of + noun phrase", "example": "because of injury or the cost of equipment and travel", "try": "Many quit because of ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "People"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000053', 1053, 'Topic 53', 'Person famous in your local area', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 53, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a person famous in your local area", "bullets": ["who this person is", "what this person does", "why this person is popular", "how you feel about this person"], "explain": "", "notes": ["Who", "What He Does", "Why He Is Popular", "How I Feel"], "rounding": {"q": "Would you like to meet someone as famous as him?", "model": {"answer": "Not really famous in the national sense, but I’d like to be known and respected in my own neighbourhood, just as he is.", "phrases": [], "grammar": []}}, "model": {"answer": "Let me tell you about Rustam aka, a baker whose little shop on the corner of my street is known all over our district, and honestly beyond it. He’s in his early sixties, with flour permanently on his apron and a laugh you can hear from the pavement. He bakes non in a traditional tandoor oven, starting at four every morning. By six there’s already a queue, and by eight everything has usually sold out. Besides plain bread, he makes a version with onions and a little sesame that I’ve never found anywhere else. He also teaches his apprentices personally, rather than leaving them to learn on the job by themselves. Part of his popularity comes from the bread, which really is second to none in the area. But what struck me even more is his generosity. After a funeral or a family emergency on our street, he quietly hands out loaves for free, and he never makes a song and dance about it. It’s mostly word of mouth that has made him a household name, as he has never spent a som on advertising. I feel a mixture of pride and gratitude towards him. When I was a student on a tight budget, he often threw in an extra loaf and told me to pay him later, which I’ve never forgotten. If I ever open a business, I’d like to treat customers the way he does, as neighbours first and customers second. He proves that you don’t need to be rich or on television to be a local legend, and that people go out of their way for those who give back to their community.", "sections": [{"label": "Who", "text": "Let me tell you about Rustam aka, a baker whose little shop on the corner of my street is known all over our district, and honestly beyond it. He’s in his early sixties, with flour permanently on his apron and a laugh you can hear from the pavement."}, {"label": "What He Does", "text": "He bakes non in a traditional tandoor oven, starting at four every morning. By six there’s already a queue, and by eight everything has usually sold out. Besides plain bread, he makes a version with onions and a little sesame that I’ve never found anywhere else. He also teaches his apprentices personally, rather than leaving them to learn on the job by themselves."}, {"label": "Why He Is Popular", "text": "Part of his popularity comes from the bread, which really is second to none in the area. But what struck me even more is his generosity. After a funeral or a family emergency on our street, he quietly hands out loaves for free, and he never makes a song and dance about it. It’s mostly word of mouth that has made him a household name, as he has never spent a som on advertising."}, {"label": "How I Feel", "text": "I feel a mixture of pride and gratitude towards him. When I was a student on a tight budget, he often threw in an extra loaf and told me to pay him later, which I’ve never forgotten. If I ever open a business, I’d like to treat customers the way he does, as neighbours first and customers second. He proves that you don’t need to be rich or on television to be a local legend, and that people go out of their way for those who give back to their community."}], "phrases": [["sell out", "be completely finished because everything has been bought"], ["learn on the job", "learn by doing the work, not in a classroom"], ["second to none", "better than all others"], ["make a song and dance about (something)", "make a big fuss about it"], ["word of mouth", "people telling each other, not advertising"], ["a household name", "someone everyone knows"], ["on a tight budget", "with very little money to spend"], ["throw in", "add something extra for free"], ["a local legend", "a person famous and respected in one place"], ["go out of your way", "make a special effort"], ["give back", "do something good for the community that has supported you"]], "grammar": [{"pattern": "Relative clause with whose", "use": "noun + whose + noun + verb", "example": "a baker whose little shop on the corner of my street is known all over our district", "try": "I know a man whose ______ is ______."}, {"pattern": "Cleft sentence", "use": "what + subject + verb + even more + is + noun", "example": "what struck me even more is his generosity", "try": "What impressed me most is ______."}, {"pattern": "Present perfect passive/active", "use": "contrast that has made him + noun", "example": "that has made him a household name", "try": "...which has made her ______."}, {"pattern": "Rather than + -ing", "use": "rather than + -ing", "example": "rather than leaving them to learn on the job by themselves", "try": "He helps people rather than ______ing."}, {"pattern": "The way + subject + does", "use": "treat X the way + subject + does", "example": "treat customers the way he does", "try": "I’d like to treat people the way ______ does."}, {"pattern": "Real conditional with ever", "use": "If I ever + present, I’d + base verb", "example": "If I ever open a business, I’d like to treat customers the way he does", "try": "If I ever ______, I’d like to ______."}]}}, "part3": {"intro": "We’ve been talking about a person famous in your local area, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Person famous in your local area", "title": "Person famous in your local area", "questions": [{"q": "Why do some people become popular in their communities?", "model": {"answer": "Usually because they give something back. A doctor who treats patients kindly, or a shopkeeper who goes out of his way to help, soon earns a reputation as someone reliable. Popularity in a community is built slowly through small, consistent acts rather than one grand gesture. People trust those who are there for them in difficult times, and that kind of trust is what sticks.", "phrases": [["give something back", "do something good for people who have helped you"], ["go out of your way", "make a special effort"], ["earn a reputation", "become known for a quality"], ["there for (someone)", "available to help"], ["stick", "stay in people’s minds"]], "grammar": [{"pattern": "Relative clause with who", "use": "noun + who + verb", "example": "A doctor who treats patients kindly", "try": "A neighbour who ______."}, {"pattern": "", "use": "Cleft: that kind of … is what that kind of + noun + is what + verb", "example": "that kind of trust is what sticks", "try": "That kind of ______ is what ______."}]}}, {"q": "Is it easier to become famous nowadays than in the past?", "model": {"answer": "In one sense, yes. A single video can go viral overnight and turn an unknown teenager into a celebrity, whereas fifty years ago you needed a record deal or a television appearance. However, staying famous is a different matter, since attention moves on so quickly. So it’s easier to get noticed, but much harder to build a lasting reputation, and most people fade from view within months.", "phrases": [["go viral", "spread extremely fast online"], ["stay famous", "remain well known"], ["get noticed", "attract people’s attention"], ["build a lasting reputation", "become known in a way that continues for years"], ["fade from view", "slowly disappear from public attention"]], "grammar": [{"pattern": "Whereas", "use": "clause, whereas clause", "example": "whereas fifty years ago you needed a record deal", "try": "Today you can ______, whereas fifty years ago you ______."}, {"pattern": "Much harder to", "use": "it’s + comparative + to + verb", "example": "it’s easier to get noticed, but much harder to build a lasting reputation", "try": "It’s easier to ______, but much harder to ______."}]}}, {"q": "Why do people want to be popular?", "model": {"answer": "I suppose it’s a basic human need to belong. Being popular means people like and value you, which boosts your self-esteem. For some, there are practical benefits too, such as better job opportunities or influence. But if popularity becomes the main goal, people may change who they are to please others, which is exhausting, so it’s healthiest when it comes as a by-product of being genuine.", "phrases": [["belong", "feel accepted as part of a group"], ["value", "think someone is important"], ["self-esteem", "confidence and respect for yourself"], ["influence", "the power to affect what others think or do"], ["by-product", "a result that comes along with something else"]], "grammar": [{"pattern": "If + present, may", "use": "If + present simple, subject + may + verb", "example": "if popularity becomes the main goal, people may change who they are", "try": "If ______ becomes the main goal, people may ______."}, {"pattern": "Which as comment", "use": "…, which is + adjective", "example": "which is exhausting", "try": "..., which is ______."}]}}, {"q": "Why do some people become famous but not successful?", "model": {"answer": "Fame and success aren’t the same thing. Someone can become a flash in the pan for a silly reason, without any real skill or achievement, so the attention disappears as quickly as it came. Others become household names through scandal rather than talent. Success, on the other hand, usually requires sustained effort and some lasting value to others, which is something fame alone can’t provide.", "phrases": [["a flash in the pan", "something that is popular only briefly"], ["household name", "a person everyone has heard of"], ["on the other hand", "used to give a contrasting point"], ["sustained effort", "hard work continued over a long time"], ["lasting value", "benefit that continues over time"]], "grammar": [{"pattern": "As quickly as", "use": "as + adverb + as", "example": "as quickly as it came", "try": "It disappeared as quickly as ______."}, {"pattern": "", "use": "Relative clause: something … which …, which is something + subject + can’t + verb", "example": "which is something fame alone can’t provide", "try": "..., which is something ______ can’t ______."}]}}, {"q": "Do you think good teachers are always popular with students?", "model": {"answer": "Not necessarily. Some of the best teachers I had were quite strict, and I only appreciated them years later. A teacher who demands hard work will rarely win a popularity contest, whereas one who gives easy marks might be adored. That said, the finest teachers are demanding yet approachable, so students respect them and, in the long run, look back on them fondly.", "phrases": [["appreciate", "understand the value of"], ["win a popularity contest", "be liked the most by everyone"], ["demanding", "expecting a lot from others"], ["look back on (someone)", "remember a past experience"], ["fondly", "with affection"]], "grammar": [{"pattern": "Only … years later", "use": "I only + past simple + time expression", "example": "I only appreciated them years later", "try": "I only realised ______ years later."}, {"pattern": "Who-relative with rarely", "use": "a teacher who + verb + will rarely + verb", "example": "A teacher who demands hard work will rarely win a popularity contest", "try": "A boss who ______ will rarely ______."}]}}, {"q": "What qualities make someone popular at work?", "model": {"answer": "Reliability is probably number one in any workplace: colleagues like people who deliver on their promises and don’t pass the buck. Beyond that, a genuinely positive attitude and good listening skills go a long way. Someone who shares the credit for success and offers help without being asked will almost always be popular, whereas people who talk down to others soon lose goodwill.", "phrases": [["deliver on", "do what you promised"], ["pass the buck", "blame others to avoid responsibility"], ["go a long way", "help a great deal"], ["share the credit", "let others be praised too"], ["talk down to", "speak as if someone is less intelligent"], ["lose goodwill", "lose people’s kind feelings"]], "grammar": [{"pattern": "Relative clause with people who", "use": "people who + verb", "example": "people who deliver on their promises", "try": "...people who ______."}, {"pattern": "Whereas contrast", "use": "clause, whereas people who…", "example": "whereas people who talk down to others soon lose goodwill", "try": "..., whereas people who ______ soon ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "People"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000054', 1054, 'Topic 54', 'Losing something important', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 54, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe an occasion when you lost something", "bullets": ["what it was", "when and where you lost it", "what you did about it", "and explain why it was important to you"], "explain": "", "notes": ["What It Was", "When And Where", "What I Did", "Why It Mattered"], "rounding": {"q": "Do you lose things often?", "model": {"answer": "Not often, but I’m a bit absent-minded when I’m tired. That’s why I now have a fixed place for my keys and wallet, and it has saved me many times.", "phrases": [], "grammar": []}}, "model": {"answer": "The thing I lost was my wallet, a brown leather one my father gave me the day I started university. It wasn’t expensive, but he had slipped a small folded note behind my student card. It happened about three years ago on the train from Samarkand to Tashkent. I’d been dozing off with my jacket over the seat, and when we arrived, I patted my pockets and realised it had gone. My stomach sank. All my cash, my student card and my bank card were in it, and I was in a panic for a good ten minutes. First I retraced my steps through the carriage, then I asked the conductor, who told me to report it at the lost-property office at the station. I also rang my bank to block my card, which I should have done immediately. Two days later a stranger called to say that a cleaner had found the wallet under a seat and handed it in. The money had vanished, but everything else had turned up. What mattered was the note. It only said, ‘Study hard and call your mother’, but I’d have been heartbroken to lose it. The wallet had sentimental value far beyond its price. Since then I’ve made a habit of double-checking my seat before I leave any train, and I keep a photo of that note on my phone, just in case. Looking back, it taught me that the things we lose are rarely the ones we can replace.", "sections": [{"label": "What It Was", "text": "The thing I lost was my wallet, a brown leather one my father gave me the day I started university. It wasn’t expensive, but he had slipped a small folded note behind my student card."}, {"label": "When And Where", "text": "It happened about three years ago on the train from Samarkand to Tashkent. I’d been dozing off with my jacket over the seat, and when we arrived, I patted my pockets and realised it had gone. My stomach sank. All my cash, my student card and my bank card were in it, and I was in a panic for a good ten minutes."}, {"label": "What I Did", "text": "First I retraced my steps through the carriage, then I asked the conductor, who told me to report it at the lost-property office at the station. I also rang my bank to block my card, which I should have done immediately. Two days later a stranger called to say that a cleaner had found the wallet under a seat and handed it in. The money had vanished, but everything else had turned up."}, {"label": "Why It Mattered", "text": "What mattered was the note. It only said, ‘Study hard and call your mother’, but I’d have been heartbroken to lose it. The wallet had sentimental value far beyond its price. Since then I’ve made a habit of double-checking my seat before I leave any train, and I keep a photo of that note on my phone, just in case. Looking back, it taught me that the things we lose are rarely the ones we can replace."}], "phrases": [["doze off", "fall asleep lightly without meaning to"], ["pat your pockets", "touch your pockets to check something is there"], ["your stomach sinks", "you suddenly feel worried or disappointed"], ["in a panic", "very frightened and unable to think calmly"], ["retrace your steps", "go back along the way you came"], ["hand in", "give something found to the authorities"], ["vanish", "disappear completely"], ["turn up", "be found or appear"], ["sentimental value", "importance because of personal memories"], ["make a habit of", "do something regularly"], ["double-check", "check again to be sure"]], "grammar": [{"pattern": "Past perfect continuous", "use": "had + been + -ing", "example": "I’d been dozing off", "try": "I’d been ______ing when ______."}, {"pattern": "Should have + past participle", "use": "should have + past participle: regret about the past", "example": "which I should have done immediately", "try": "I should have ______."}, {"pattern": "Cleft sentence", "use": "What + verb + was + noun", "example": "What mattered was the note", "try": "What mattered most was ______."}, {"pattern": "Conditional perfect (would have)", "use": "I’d have + past participle + to + verb", "example": "I’d have been heartbroken to lose it", "try": "I’d have been ______ to ______."}, {"pattern": "Past perfect passive/active", "use": "had + past participle", "example": "a cleaner had found the wallet under a seat", "try": "Someone had ______."}, {"pattern": "Rarely … the ones", "use": "things + rarely + are + the ones", "example": "the things we lose are rarely the ones we can replace", "try": "The things we ______ are rarely ______."}]}}, "part3": {"intro": "We’ve been talking about an occasion when you lost something, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Losing something important", "title": "Losing something important", "questions": [{"q": "What kinds of things do people often lose?", "model": {"answer": "Small, everyday items, mostly: keys, phones, wallets and umbrellas. They’re things we use constantly and put down without thinking, so they easily go missing. Earphones are another favourite, because they’re tiny and easy to leave behind on buses. Interestingly, people rarely lose anything large, since its absence is noticed straight away, whereas a small item can disappear for hours before anyone realises.", "phrases": [["put down", "place somewhere"], ["go missing", "disappear so that nobody knows where it is"], ["leave behind", "forget to take with you"], ["absence", "the state of not being there"], ["noticed", "become aware of"]], "grammar": [{"pattern": "Reduced relative clause", "use": "things + (that) we + verb", "example": "They’re things we use constantly", "try": "They’re things we ______ every day."}, {"pattern": "Whereas contrast", "use": "clause, whereas clause", "example": "whereas a small item can disappear for hours before anyone realises", "try": "______, whereas ______."}]}}, {"q": "What kinds of people lose things easily?", "model": {"answer": "Those who are always in a hurry, I’d say. If you rush out of the door with your mind on a meeting, you’ll probably forget your keys. Absent-minded people, such as creative types who get lost in thought, are also prone to it, and so are teenagers juggling too many things at once. It’s rarely about intelligence; it’s about paying attention in the moment.", "phrases": [["absent-minded", "often forgetting things because you think about something else"], ["get lost in thought", "become so absorbed in thinking that you notice nothing else"], ["prone to", "likely to suffer from"], ["juggle", "try to manage several things at once"], ["pay attention", "focus carefully"]], "grammar": [{"pattern": "First conditional", "use": "If + present simple, will + verb", "example": "If you rush out of the door with your mind on a meeting, you’ll probably forget your keys", "try": "If you ______, you’ll probably ______."}, {"pattern": "So + auxiliary + subject", "use": "so + are/do + subject: ‘also’", "example": "and so are teenagers", "try": "...and so are ______."}]}}, {"q": "How can people avoid losing things?", "model": {"answer": "The simplest solution is to have a fixed place for everything. If your keys always hang by the door, you won’t have to turn the house upside down every morning. When travelling, it helps to run through a quick mental checklist before leaving: phone, wallet, keys. And for valuable items, a tracker tag is a cheap way to play it safe, as long as you remember to charge it.", "phrases": [["turn the house upside down", "search everywhere, making a mess"], ["run through", "go over quickly"], ["tracker tag", "a small device that shows where an item is"], ["play it safe", "avoid taking risks"], ["charge", "fill with electrical power"]], "grammar": [{"pattern": "Dummy it", "use": "it helps to + verb", "example": "it helps to run through a quick mental checklist", "try": "It helps to ______ before you ______."}, {"pattern": "As long as", "use": "as long as + subject + verb", "example": "as long as you remember to charge it", "try": "...as long as you ______."}]}}, {"q": "Has technology made it easier to find lost things?", "model": {"answer": "Definitely, up to a point. Phone-locating apps and tracker tags let you pinpoint a missing item within a few metres, which is a huge relief. In my parents’ day, you simply had to go back over your day and hope. The catch is that it only works if the battery is charged; a dead phone is as good as lost, and nothing can make up for that.", "phrases": [["pinpoint", "find the exact location of"], ["relief", "the good feeling when a worry ends"], ["the catch", "the hidden problem"], ["as good as", "almost, practically"], ["make up for", "compensate for"]], "grammar": [{"pattern": "Let + object + verb", "use": "let + object + base verb", "example": "let you pinpoint a missing item", "try": "This app lets you ______."}, {"pattern": "Which as comment", "use": "…, which is + a/an + noun", "example": "which is a huge relief", "try": "..., which is a huge ______."}]}}, {"q": "What should people do if they find something that belongs to someone else?", "model": {"answer": "Ideally, hand it in to the nearest authority, such as the police, a shop or the station staff, since the owner will probably ask there first. If there’s something inside, like an ID card, you could try to track down the owner directly. Keeping it is simply not an option. If you put yourself in their shoes, you’d want the same, and in the end it’s a matter of honesty.", "phrases": [["hand in", "give to the authorities"], ["track down", "find after searching"], ["simply not an option", "definitely cannot be considered"], ["put yourself in their shoes", "imagine how they feel"], ["a matter of honesty", "a question of being honest"]], "grammar": [{"pattern": "Second conditional", "use": "If + past simple, would + verb", "example": "If you put yourself in their shoes, you’d want the same", "try": "If you ______, you’d ______."}, {"pattern": "Such as examples", "use": "such as A, B or C", "example": "such as the police, a shop or the station staff", "try": "...such as ______, ______ or ______."}]}}, {"q": "Should children be taught to take care of their belongings?", "model": {"answer": "Absolutely, and the earlier the better. Children who are never made to look after their things tend to take them for granted, which can turn into carelessness later. Simple habits, such as packing their own school bag or tidying up after play, teach responsibility. It also helps them value what their parents have worked hard to buy, so it’s really a lesson in respect as well.", "phrases": [["the earlier the better", "as soon as possible is best"], ["take (it) for granted", "fail to appreciate because it is always there"], ["tidy up", "put things in order"], ["responsibility", "the duty to look after something"], ["value", "appreciate the worth of"]], "grammar": [{"pattern": "The + comparative, the +", "use": "comparative the earlier the better", "example": "the earlier the better", "try": "The ______ the better."}, {"pattern": "Passive made to", "use": "be made to + verb", "example": "are never made to look after their things", "try": "Children are never made to ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Events & experiences"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000055', 1055, 'Topic 55', 'Something you do that saves your time', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 55, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe something you do that helps you save your time", "bullets": ["what it is", "when you do it", "how you feel when you do this", "how it helps you"], "explain": "", "notes": ["What", "When", "Feelings", "How It Helps"], "rounding": {"q": "Do you think you manage your time better than most people you know?", "model": {"answer": "Probably, yes, at least compared with my classmates. I’m not perfect, though; I still waste an evening on my phone now and then, but I’m quick to notice and get back on track.", "phrases": [], "grammar": []}}, "model": {"answer": "The first thing that comes to mind is a habit I picked up in my second year at university: batch cooking every Sunday evening. I study Economics, and my timetable is jam-packed, so I used to waste nearly an hour every night deciding what to eat, shopping and washing up. Then my aunt Gulnora, who runs a small café in Samarkand, suggested cooking three or four meals at once. So now, without fail, I spend about two hours in the kitchen on Sunday evenings with a playlist on. I chop vegetables, cook rice or lentils in bulk, divide everything into containers and put them in the fridge. During the week, I just heat something up. What struck me was how calm it makes me feel. At first, to be fair, I found it tedious; I’d stand there thinking I could be revising instead. Now it’s a form of therapy, and I always feel as if a weight has been lifted before Monday arrives. In practical terms, it frees up roughly seven hours a week, which I spend catching up on reading and going to the gym. It has also cut down on my spending, because I no longer grab a bite at the canteen. Had I not started, I’d probably have burned out during my last exams. Looking back, I’ve realised that saving time isn’t about rushing. It’s about making the most of the hours you have by deciding things once instead of every single day.", "sections": [{"label": "What", "text": "The first thing that comes to mind is a habit I picked up in my second year at university: batch cooking every Sunday evening. I study Economics, and my timetable is jam-packed, so I used to waste nearly an hour every night deciding what to eat, shopping and washing up. Then my aunt Gulnora, who runs a small café in Samarkand, suggested cooking three or four meals at once."}, {"label": "When", "text": "So now, without fail, I spend about two hours in the kitchen on Sunday evenings with a playlist on. I chop vegetables, cook rice or lentils in bulk, divide everything into containers and put them in the fridge. During the week, I just heat something up."}, {"label": "Feelings", "text": "What struck me was how calm it makes me feel. At first, to be fair, I found it tedious; I’d stand there thinking I could be revising instead. Now it’s a form of therapy, and I always feel as if a weight has been lifted before Monday arrives."}, {"label": "How It Helps", "text": "In practical terms, it frees up roughly seven hours a week, which I spend catching up on reading and going to the gym. It has also cut down on my spending, because I no longer grab a bite at the canteen. Had I not started, I’d probably have burned out during my last exams."}, {"label": "Reflection", "text": "Looking back, I’ve realised that saving time isn’t about rushing. It’s about making the most of the hours you have by deciding things once instead of every single day."}], "phrases": [["batch cooking", "preparing several meals in one session to eat later"], ["jam-packed", "completely full, with no free space"], ["without fail", "every single time, reliably"], ["a form of therapy", "something that relaxes you and clears your head"], ["frees up", "makes time or money available for other uses"], ["catching up on", "doing things you have fallen behind with"], ["cut down on", "reduce the amount of something"], ["grab a bite", "eat something quickly"], ["burned out", "exhausted from too much stress or work"], ["making the most of", "using something as well as possible"]], "grammar": [{"pattern": "Relative clause with who", "use": "noun + who + extra information about a person", "example": "my aunt Gulnora, who runs a small café in Samarkand", "try": "My cousin, who ______, taught me to ______."}, {"pattern": "Past habit with used to", "use": "used to + infinitive for a past routine", "example": "I used to waste nearly an hour every night", "try": "I used to ______ every ______, but now I ______."}, {"pattern": "Cleft sentence with What", "use": "What + subject + verb + be + noun clause", "example": "What struck me was how calm it makes me feel.", "try": "What surprised me was ______."}, {"pattern": "Concession with to be fair", "use": "to be fair + admission before a contrast", "example": "At first, to be fair, I found it tedious", "try": "To be fair, ______, but ______."}, {"pattern": "Inverted third conditional", "use": "Had + subject + past participle, would have + past participle", "example": "Had I not started, I’d probably have burned out during my last exams.", "try": "Had I not ______, I would have ______."}, {"pattern": "Relative clause with which", "use": "comma + which referring to the whole idea", "example": "which I spend catching up on reading and going to the gym", "try": "It saves two hours, which I use for ______."}]}}, "part3": {"intro": "We’ve been talking about something you do that helps you save your time, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Something you do that saves your time", "title": "Something you do that saves your time", "questions": [{"q": "Why is it important to manage your time well?", "model": {"answer": "Because time is the one resource you can never get back, so wasting it has a cost. People who plan their days feel in control, whereas those who don’t are constantly playing catch-up. Take students: if they set aside an hour for revision, they rarely panic before exams. Not only does planning improve results, it also leaves room for rest and hobbies, which keeps people on an even keel.", "phrases": [["get back", "recover something you have lost"], ["playing catch-up", "trying to reach the level you should already be at"], ["set aside", "reserve for a purpose"], ["leaves room for", "makes space for"], ["on an even keel", "calm and stable"]], "grammar": [{"pattern": "Contrast with whereas", "use": "whereas links two opposite groups", "example": "whereas those who don’t are constantly playing catch-up", "try": "Some people ______, whereas others ______."}, {"pattern": "Not only... but also", "use": "Not only + inverted verb..., it also...", "example": "Not only does planning improve results, it also leaves room for rest", "try": "Not only does ______, it also ______."}]}}, {"q": "How do people usually manage their time?", "model": {"answer": "It varies, but most rely on some sort of list, whether on paper or a phone. My mother, for instance, writes tomorrow’s tasks in a notebook every night, which stops her dithering in the morning. Others block out time in a calendar app. That said, plenty of people simply wing it and, as long as deadlines aren’t strict, it works for them, although they often end up rushing around.", "phrases": [["rely on", "depend on"], ["dithering", "hesitating and failing to decide"], ["block out", "reserve a period of time"], ["wing it", "do something without preparing"], ["rushing around", "hurrying from one thing to another"]], "grammar": [{"pattern": "Non-defining relative clause", "use": "comma + which for the result of the previous clause", "example": "which stops her dithering in the morning", "try": "She plans ahead, which means ______."}, {"pattern": "Concession with that said", "use": "That said, + contrasting point", "example": "That said, plenty of people simply wing it", "try": "That said, ______."}]}}, {"q": "How does technology help people save time?", "model": {"answer": "In countless ways, although it can also take time back. Banking, shopping and booking tickets used to mean queuing for hours, whereas now it’s a matter of a few taps. Online maps help drivers steer clear of traffic, and translation apps cut out tedious work. Mind you, the catch is that notifications eat into our concentration, so the time saved is only real if we use our devices deliberately.", "phrases": [["a matter of", "only needing a small amount of something"], ["steer clear of", "avoid"], ["cut out", "remove, eliminate"], ["the catch is", "the hidden disadvantage is"], ["eat into", "gradually use up part of something"]], "grammar": [{"pattern": "Used to for past habit", "use": "used to + infinitive", "example": "used to mean queuing for hours", "try": "Shopping used to mean ______."}, {"pattern": "Conditional with only... if", "use": "only + if clause as a condition", "example": "the time saved is only real if we use our devices deliberately", "try": "It only works if ______."}]}}, {"q": "Do you think success depends mainly on good time management?", "model": {"answer": "It certainly helps, yet I wouldn’t say it’s the main factor. Someone can organise every hour perfectly and still fail if they lack talent, connections or simply luck. What good time management does is help you make the most of whatever ability you have. If two equally gifted people were competing, the one who planned better would probably come out on top, but that’s a fine margin.", "phrases": [["the main factor", "the most important cause"], ["connections", "useful contacts or relationships"], ["make the most of", "use as effectively as possible"], ["come out on top", "win or end up best"], ["fine margin", "very small difference"]], "grammar": [{"pattern": "Cleft sentence with What", "use": "What + subject + does + is + base verb", "example": "What good time management does is help you make the most of whatever ability you have.", "try": "What this does is ______."}, {"pattern": "Second conditional", "use": "If + past simple, would + infinitive", "example": "If two equally gifted people were competing, the one who planned better would probably come out on top", "try": "If two people ______, the one who ______ would ______."}]}}, {"q": "Are people born with time-management skills, or can they learn them?", "model": {"answer": "Largely learned, I’d argue, although temperament plays a part. Some children are naturally tidier and more punctual, which gives them a head start. But nobody is born knowing how to use a planner. I used to miss deadlines at school until my teacher showed me how to break down assignments. Once I had got into the habit, it became automatic, and I never looked back.", "phrases": [["a head start", "an early advantage"], ["miss deadlines", "fail to finish work on time"], ["break down", "divide into smaller parts"], ["got into the habit", "began doing something regularly"], ["never looked back", "kept going forward without regret"]], "grammar": [{"pattern": "Past perfect with once", "use": "Once + had + past participle, then result", "example": "Once I had got into the habit, it became automatic", "try": "Once I had ______, I ______."}, {"pattern": "Until clause in the past", "use": "past simple + until + past simple", "example": "I used to miss deadlines at school until my teacher showed me", "try": "I used to ______ until ______."}]}}, {"q": "Are people busier now than they were in the past?", "model": {"answer": "In some ways, yes. Our grandparents’ days were hard, but their routine was a far cry from ours, ending when the shop closed. Now we’re expected to answer messages at any hour, so work spills over into the evening. Meanwhile, appliances have removed much household drudgery. So it’s less that we have more to do and more that we feel permanently on call.", "phrases": [["a far cry from", "very different from"], ["at any hour", "at any time of day or night"], ["spills over", "extends into another area or time"], ["drudgery", "boring, tiring routine work"], ["on call", "available to respond at any time"]], "grammar": [{"pattern": "Present perfect for result", "use": "have/has + past participle for change up to now", "example": "appliances have removed much household drudgery", "try": "Technology has ______."}, {"pattern": "Cleft-style contrast", "use": "it’s less that... and more that...", "example": "it’s less that we have more to do and more that we feel permanently on call", "try": "It’s less that ______ and more that ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Events & experiences"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000056', 1056, 'Topic 56', 'Something you weren’t interested in', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 56, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a time when someone talked about something you were not interested in but you kept listening", "bullets": ["who this person is", "what this person talked about", "why you kept listening", "how you felt about the experience"], "explain": "", "notes": ["Who", "What", "Why", "Feelings"], "rounding": {"q": "Do you usually find it easy to listen to people talk about things you don’t care about?", "model": {"answer": "Not always, to be honest. If it’s a friend, I make an effort and often end up enjoying it, but with a long, repetitive monologue I’ll admit my mind starts to wander.", "phrases": [], "grammar": []}}, "model": {"answer": "One occasion I’ll never forget was a long train journey from Tashkent to Bukhara last spring, when I found myself sitting opposite an elderly man called Rustam-aka, a retired railway engineer who had spent forty years on the tracks. He had a warm face with a twinkle in his eye, and he was clearly in the mood for a chat. Within ten minutes, he had launched into a detailed explanation of how old steam locomotives worked: the valves, the pressure, the coal shortages of the 1960s. Honestly, I couldn’t have cared less about engines, and I’d been hoping to doze off with my headphones on. Yet I kept listening. For one thing, it would have been rude to cut him off, since he was nearly eighty. For another, I noticed how his whole face lit up whenever he reached a favourite detail. When I finally apologised for yawning, he laughed and said, “You’re the first young person who has let me finish.” What struck me was how infectious his enthusiasm was. By the time we reached Navoi, I was asking questions and hanging on his every word. Never had I imagined that a lecture on boilers could be so entertaining, and I felt a little guilty about my earlier attitude. Looking back, I realise that listening is a kind of generosity. It costs nothing, yet it can make someone’s day, and I ended up picking up far more than I expected.", "sections": [{"label": "Who", "text": "One occasion I’ll never forget was a long train journey from Tashkent to Bukhara last spring, when I found myself sitting opposite an elderly man called Rustam-aka, a retired railway engineer who had spent forty years on the tracks. He had a warm face with a twinkle in his eye, and he was clearly in the mood for a chat."}, {"label": "What", "text": "Within ten minutes, he had launched into a detailed explanation of how old steam locomotives worked: the valves, the pressure, the coal shortages of the 1960s. Honestly, I couldn’t have cared less about engines, and I’d been hoping to doze off with my headphones on."}, {"label": "Why", "text": "Yet I kept listening. For one thing, it would have been rude to cut him off, since he was nearly eighty. For another, I noticed how his whole face lit up whenever he reached a favourite detail. When I finally apologised for yawning, he laughed and said, “You’re the first young person who has let me finish.”"}, {"label": "Feelings", "text": "What struck me was how infectious his enthusiasm was. By the time we reached Navoi, I was asking questions and hanging on his every word. Never had I imagined that a lecture on boilers could be so entertaining, and I felt a little guilty about my earlier attitude."}, {"label": "Reflection", "text": "Looking back, I realise that listening is a kind of generosity. It costs nothing, yet it can make someone’s day, and I ended up picking up far more than I expected."}], "phrases": [["a twinkle in his eye", "a bright, amused look that shows good humour"], ["in the mood for", "feeling like doing something"], ["launched into", "started talking about something with energy"], ["couldn’t have cared less", "was completely uninterested"], ["doze off", "fall asleep lightly"], ["cut him off", "interrupt someone so they stop speaking"], ["lit up", "became bright and animated with happiness"], ["infectious", "spreading easily to other people"], ["hanging on his every word", "listening with total attention"], ["make someone’s day", "make someone feel very happy"], ["picking up", "learning something casually"]], "grammar": [{"pattern": "Past perfect", "use": "had + past participle for an earlier action", "example": "he had launched into a detailed explanation", "try": "By the time ______, he had ______."}, {"pattern": "Participle clause", "use": "when + subject + found myself + -ing", "example": "when I found myself sitting opposite an elderly man", "try": "I found myself ______ing ______."}, {"pattern": "Modal perfect", "use": "would have been + adjective for an unreal past", "example": "it would have been rude to cut him off", "try": "It would have been ______ to ______."}, {"pattern": "Cleft sentence", "use": "What + subject + verb + was + clause", "example": "What struck me was how infectious his enthusiasm was.", "try": "What struck me was ______."}, {"pattern": "Negative inversion", "use": "Never had + subject + past participle", "example": "Never had I imagined that a lecture on boilers could be so entertaining, and I felt a little guilty about my earlier attitude.", "try": "Never had I ______."}, {"pattern": "For one thing... for another", "use": "two linked reasons", "example": "For one thing, it would have been rude to cut him off", "try": "For one thing, ______. For another, ______."}]}}, "part3": {"intro": "We’ve been talking about a time when someone talked about something you were not interested in but you kept listening, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Something you weren’t interested in", "title": "Something you weren’t interested in", "questions": [{"q": "What do young people usually talk about?", "model": {"answer": "It depends on the group, but music, football, exams and whatever is trending online come up constantly. Among my friends, a surprising amount of time goes on swapping gossip about celebrities and venting about workload. Deeper subjects such as careers and money tend to crop up later at night, once everyone has opened up, which I find far more interesting, and which comes as a surprise to many parents.", "phrases": [["swapping", "exchanging"], ["venting", "expressing frustration openly"], ["crop up", "appear unexpectedly in conversation"], ["opened up", "started to speak openly"], ["comes as a surprise", "is unexpected"]], "grammar": [{"pattern": "Relative clause with which", "use": "comma + which for comment on a whole idea", "example": "which I find far more interesting", "try": "______, which I find ______."}, {"pattern": "Once clause", "use": "once + present perfect", "example": "once everyone has opened up", "try": "Once people have ______, they ______."}]}}, {"q": "How can you tell if someone isn’t interested in what you are saying?", "model": {"answer": "Body language gives it away. If someone keeps glancing at their phone, looks past you or gives one-word replies, they have probably switched off. Another sign is when they change the subject. To be fair, silence doesn’t always mean boredom; some people are tired or shy. So I tend to read the room and ask a question to see whether they perk up, which is a good litmus test.", "phrases": [["switched off", "stopped paying attention"], ["change the subject", "start talking about something else"], ["read the room", "sense the mood of a group"], ["perk up", "become more lively and interested"], ["a good litmus test", "a clear way of finding out the truth"]], "grammar": [{"pattern": "First conditional", "use": "If + present, ...probably + have", "example": "If someone keeps glancing at their phone, looks past you or gives one-word replies, they have probably switched off.", "try": "If someone ______, they have probably ______."}, {"pattern": "Concession", "use": "To be fair, + statement; clause with doesn’t always", "example": "silence doesn’t always mean boredom", "try": "______ doesn’t always mean ______."}]}}, {"q": "Is it important to listen carefully to other people?", "model": {"answer": "Absolutely, because misunderstandings are costly. If a manager only half listens, instructions get lost and mistakes snowball. Beyond that, careful listening shows respect, and people open up to anyone who gives them their full attention. I’ve noticed that arguments in my family flare up when two people are talking at once, not when one is trying to understand. In short, listening is a skill that pays off every day.", "phrases": [["snowball", "grow quickly and out of control"], ["shows respect", "makes someone feel valued"], ["open up", "talk honestly about feelings"], ["flare up", "start suddenly and fiercely"], ["pays off", "brings a good result"]], "grammar": [{"pattern": "Present perfect", "use": "I’ve noticed that + clause", "example": "I’ve noticed that arguments in my family flare up", "try": "I’ve noticed that ______."}, {"pattern": "Relative clause with who", "use": "anyone who + verb", "example": "anyone who gives them their full attention", "try": "People trust anyone who ______."}]}}, {"q": "Why do some people talk a lot while others are quiet?", "model": {"answer": "Personality is the obvious factor: extroverts recharge around people, while introverts need solitude. Upbringing matters too, since children who are encouraged to speak up at the dinner table tend to be more talkative as adults. Context also plays a part. Someone who chatters away with friends may clam up in a meeting. Quiet people often come across as shy, yet they may simply be thinking.", "phrases": [["recharge", "regain energy"], ["speak up", "say what you think"], ["chatters away", "talks continuously and cheerfully"], ["clam up", "suddenly stop talking"], ["come across as", "give the impression of being"]], "grammar": [{"pattern": "Relative clause with who", "use": "children who are encouraged to...", "example": "children who are encouraged to speak up at the dinner table", "try": "People who ______ tend to ______."}, {"pattern": "Modal may for possibility", "use": "may + infinitive", "example": "Someone who chatters away with friends may clam up in a meeting.", "try": "Someone who ______ may ______."}]}}, {"q": "What makes someone a good listener?", "model": {"answer": "Patience and real curiosity. A good listener doesn’t cut in or jump to conclusions; instead, they ask follow-up questions that show they’ve taken in what you said. Steady eye contact helps too. My grandfather was brilliant at it. Whatever you told him, he would nod, pause, and then pick up on a small detail you had almost forgotten, which made you feel properly heard.", "phrases": [["cut in", "interrupt"], ["jump to conclusions", "decide something too quickly without enough facts"], ["taken in", "understood and absorbed"], ["eye contact", "looking directly at someone’s eyes"], ["pick up on", "notice and respond to"]], "grammar": [{"pattern": "Would for past habit", "use": "would + infinitive for repeated past action", "example": "he would nod, pause, and then pick up on a small detail", "try": "Whatever you told him, he would ______."}, {"pattern": "Make + object + adjective", "use": "which made you feel + adjective", "example": "which made you feel properly heard", "try": "It made me feel ______."}]}}, {"q": "Do you think technology has made communication less effective?", "model": {"answer": "In some respects, yes, although it has certainly made it faster. We can reach anyone instantly, yet tone tends to get lost in translation, so jokes are misread and small disagreements blow up. Many people also half-listen on video calls while checking other tabs. That said, for families living far apart, technology has been a lifeline. It’s efficient for information, but nothing replaces talking face to face.", "phrases": [["get lost in translation", "lose its real meaning when communicated"], ["blow up", "suddenly become a serious argument"], ["half-listen", "pay only partial attention"], ["a lifeline", "something that provides vital support"], ["face to face", "in person"]], "grammar": [{"pattern": "Present perfect", "use": "has + made", "example": "it has certainly made it faster", "try": "Technology has made ______."}, {"pattern": "Concession with that said", "use": "That said, + contrast", "example": "That said, for families living far apart, technology has been a lifeline.", "try": "That said, ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Events & experiences"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000057', 1057, 'Topic 57', 'Book that made you happy', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 57, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a book you read that made you happy", "bullets": ["what the book was", "what it was about", "when you read it", "and explain why it made you happy"], "explain": "", "notes": ["What", "About", "When", "Why"], "rounding": {"q": "Do you think you will read that book again some day?", "model": {"answer": "Quite possibly, yes. Whenever I’m feeling low or overloaded, I flick through my favourite chapters, because they never fail to cheer me up.", "phrases": [], "grammar": []}}, "model": {"answer": "If I had to pick one book that made me happy, it would be Three Men in a Boat by Jerome K. Jerome. My classmate Dilnoza pressed a dog-eared copy into my hands, and I almost didn’t open it, because I assumed a Victorian comedy would feel stiff and old-fashioned. It follows three friends and a dog called Montmorency on a rowing holiday up the Thames. Almost nothing important happens; instead, the narrator goes off on tangents about packing, cheese and a hopelessly tangled towing rope. Yet every chapter is laugh-out-loud funny, and it’s a feel-good classic. I read it last July, just after my final exams, while staying at my grandmother’s house in Fergana. I’d been running on empty for weeks, so I spent several afternoons lying in the shade under her mulberry tree, devouring a chapter at a time and finishing it from cover to cover in a week. It made me happy because it gave me permission to stop being serious. At one point I was laughing so hard that my grandmother came out to ask what was going on. What I loved was that the humour feels timeless, as if the author had been watching my own friends. By the last page, my stress had melted away, and I stayed in high spirits for days. Looking back, I think a really good comedy is a kind of medicine. It puts things into perspective.", "sections": [{"label": "What", "text": "If I had to pick one book that made me happy, it would be Three Men in a Boat by Jerome K. Jerome. My classmate Dilnoza pressed a dog-eared copy into my hands, and I almost didn’t open it, because I assumed a Victorian comedy would feel stiff and old-fashioned."}, {"label": "About", "text": "It follows three friends and a dog called Montmorency on a rowing holiday up the Thames. Almost nothing important happens; instead, the narrator goes off on tangents about packing, cheese and a hopelessly tangled towing rope. Yet every chapter is laugh-out-loud funny, and it’s a feel-good classic."}, {"label": "When", "text": "I read it last July, just after my final exams, while staying at my grandmother’s house in Fergana. I’d been running on empty for weeks, so I spent several afternoons lying in the shade under her mulberry tree, devouring a chapter at a time and finishing it from cover to cover in a week."}, {"label": "Why", "text": "It made me happy because it gave me permission to stop being serious. At one point I was laughing so hard that my grandmother came out to ask what was going on. What I loved was that the humour feels timeless, as if the author had been watching my own friends. By the last page, my stress had melted away, and I stayed in high spirits for days."}, {"label": "Reflection", "text": "Looking back, I think a really good comedy is a kind of medicine. It puts things into perspective."}], "phrases": [["dog-eared", "with corners folded and worn from much use"], ["goes off on tangents", "moves away from the main subject"], ["laugh-out-loud funny", "so amusing that you laugh aloud"], ["feel-good", "making you feel happy and positive"], ["running on empty", "having no energy left"], ["devouring", "reading very eagerly"], ["from cover to cover", "from the first page to the last"], ["timeless", "not affected by time or fashion"], ["melted away", "disappeared gradually"], ["in high spirits", "cheerful and energetic"], ["puts things into perspective", "helps you see what really matters"]], "grammar": [{"pattern": "Second conditional", "use": "If + past simple, would + infinitive", "example": "If I had to pick one book that made me happy, it would be Three Men in a Boat", "try": "If I had to choose, it would be ______."}, {"pattern": "Past perfect continuous", "use": "had been + -ing for background up to a past time", "example": "I’d been running on empty for weeks", "try": "I’d been ______ for weeks when ______."}, {"pattern": "So... that result", "use": "so + adjective/adverb + that + result", "example": "I was laughing so hard that my grandmother came out", "try": "I was so ______ that ______."}, {"pattern": "As if + past perfect", "use": "as if + subject + had + past participle", "example": "as if the author had been watching my own friends", "try": "It felt as if ______ had ______."}, {"pattern": "Cleft sentence", "use": "What + subject + verb + was that...", "example": "What I loved was that the humour feels timeless", "try": "What I loved was that ______."}, {"pattern": "Participle clause", "use": "-ing phrase for simultaneous actions", "example": "lying in the shade under her mulberry tree, devouring a chapter at a time", "try": "I spent the evening ______ing, ______ing."}]}}, "part3": {"intro": "We’ve been talking about a book you read that made you happy, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Book that made you happy", "title": "Book that made you happy", "questions": [{"q": "What is the difference between a book and its film version?", "model": {"answer": "A book leaves plenty to the imagination, whereas a film hands you a finished picture. Readers linger over passages they love, which a film, limited by its running time, rarely allows. Films, however, are brilliant at bringing stories to life through music and acting. That’s why readers are often disappointed: the adaptation rarely lives up to the version in their heads.", "phrases": [["leaves plenty to the imagination", "lets the audience picture details for themselves"], ["linger over", "spend time enjoying slowly"], ["running time", "the length of a film"], ["bringing stories to life", "making stories vivid and real"], ["lives up to", "is as good as expected"]], "grammar": [{"pattern": "Contrast with whereas", "use": "whereas joins opposite ideas", "example": "whereas a film hands you a finished picture", "try": "A book ______, whereas a film ______."}, {"pattern": "Participle clause", "use": "noun + limited by + noun", "example": "a film, limited by its running time, rarely allows", "try": "______, limited by ______, can’t ______."}]}}, {"q": "Do you prefer reading books or watching films?", "model": {"answer": "Honestly, it depends on my mood. After a long day, a film is easier, because I can switch off and let the story carry me along. But when I want to really get lost in something, nothing beats a novel; I lose track of time on the bus. If I had to choose one, I’d go for books, since they stay with you longer.", "phrases": [["switch off", "relax and stop thinking"], ["get lost in", "become completely absorbed in"], ["nothing beats", "is better than everything else"], ["lose track of time", "forget how much time has passed"], ["stay with you", "remain in your memory"]], "grammar": [{"pattern": "Second conditional", "use": "If + past simple, I’d + infinitive", "example": "If I had to choose one, I’d go for books", "try": "If I had to choose, I’d ______."}, {"pattern": "Reason with since", "use": "since + reason", "example": "since they stay with you longer", "try": "I prefer ______ since ______."}]}}, {"q": "Do people read more or less than they did in the past?", "model": {"answer": "Less, I suspect, at least when it comes to books. Decades ago, with fewer distractions, evenings often meant sharing a novel. Now our attention is fragmented by phones. However, we actually read more text overall: messages, articles and posts. What’s changed is that we skim instead of immersing ourselves in long stories, which is a pity, because deep reading builds concentration.", "phrases": [["when it comes to", "regarding"], ["fragmented", "broken into small pieces"], ["skim", "read quickly without close attention"], ["immersing ourselves", "becoming deeply involved"], ["builds concentration", "develops the ability to focus"]], "grammar": [{"pattern": "Cleft sentence", "use": "What’s changed is that...", "example": "What’s changed is that we skim instead of immersing ourselves in long stories", "try": "What’s changed is that ______."}, {"pattern": "Absolute phrase", "use": "with + noun + comparative", "example": "with fewer distractions, evenings often meant sharing a novel", "try": "With fewer ______, people ______."}]}}, {"q": "How can reading help children?", "model": {"answer": "First and foremost, it helps them expand their vocabulary without noticing. A child who reads for twenty minutes a day will pick up words and sentence patterns that no worksheet could teach. Stories also foster empathy, since children put themselves in a character’s shoes. Over time, that leads to better grades across subjects and, just as importantly, a lifelong love of learning.", "phrases": [["expand their vocabulary", "learn more words"], ["pick up", "learn without formal teaching"], ["foster empathy", "encourage understanding of others’ feelings"], ["put themselves in a character’s shoes", "imagine another person’s situation"], ["lifelong love of learning", "a permanent enjoyment of study"]], "grammar": [{"pattern": "Relative clause", "use": "that + no worksheet could teach", "example": "words and sentence patterns that no worksheet could teach", "try": "skills that no ______ could ______."}, {"pattern": "Future with will", "use": "will + infinitive for a typical result", "example": "A child who reads for twenty minutes a day will pick up words", "try": "A child who ______ will ______."}]}}, {"q": "Should parents encourage their children to read from an early age?", "model": {"answer": "Definitely, though gently. Reading together at bedtime creates a warm routine that children look forward to, and it lays the foundation for later study. The risk is that parents turn it into a chore; if they force books on a reluctant child, he or she may develop an aversion to reading. My mother never pushed me. She simply left books lying around.", "phrases": [["look forward to", "anticipate with pleasure"], ["lays the foundation", "creates a base for future progress"], ["turn it into a chore", "make it a dull duty"], ["develop an aversion", "start to strongly dislike"], ["left books lying around", "kept books easily within reach"]], "grammar": [{"pattern": "Relative clause", "use": "a warm routine that children look forward to", "example": "a warm routine that children look forward to", "try": "a habit that people ______."}, {"pattern": "First conditional", "use": "if + present, may + infinitive", "example": "if they force books on a reluctant child, he or she may develop an aversion", "try": "If parents ______, children may ______."}]}}, {"q": "What kinds of books do young people like to read?", "model": {"answer": "Fantasy and romance seem especially popular, along with graphic novels. Many of my classmates grew up on Harry Potter and are hooked on series where one volume leads into the next. Others prefer practical books about money or productivity, because they feel under pressure to succeed. Whatever the genre, young people tend to like fast-paced plots and relatable characters whose problems resemble their own.", "phrases": [["are hooked on", "are addicted to or obsessed with"], ["leads into", "continues naturally into"], ["under pressure", "feeling stress to achieve"], ["fast-paced", "moving quickly"], ["relatable", "easy to identify with"]], "grammar": [{"pattern": "Relative clause with whose", "use": "noun + whose + noun", "example": "relatable characters whose problems resemble their own", "try": "characters whose ______ are ______."}, {"pattern": "Whatever clause", "use": "Whatever + noun, main clause", "example": "Whatever the genre, young people tend to like fast-paced plots", "try": "Whatever the ______, people ______."}]}}, {"q": "Can reading books make people happier?", "model": {"answer": "Up to a point, yes. Reading can take your mind off worries and bring a sense of calm, much as a walk does. A good novel can also make you feel less alone, which is a powerful antidote to loneliness. However, a book won’t solve real problems; it can only offer perspective and comfort. So I’d call it a helpful companion to happiness rather than the source of it.", "phrases": [["Up to a point", "partly but not completely"], ["take your mind off", "distract you from"], ["a powerful antidote to", "a strong remedy for"], ["offer perspective", "help you see things differently"], ["helpful companion", "something that supports you"]], "grammar": [{"pattern": "Comparison with much as", "use": "much as + clause", "example": "much as a walk does", "try": "______ can calm you, much as ______ does."}, {"pattern": "Rather than", "use": "A rather than B", "example": "a helpful companion to happiness rather than the source of it", "try": "It’s ______ rather than ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Things & ideas"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000058', 1058, 'Topic 58', 'Helping someone', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 58, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a situation when you helped someone", "bullets": ["what the situation was", "who the person was", "how you helped them", "how you felt after helping them"], "explain": "", "notes": ["What", "Who", "How", "Feelings"], "rounding": {"q": "Do you think you would help a stranger in the same way?", "model": {"answer": "I hope so. It would depend on the situation, but after what happened with Zulfiya-opa, I’m far more willing to step in, even if it feels slightly awkward at first.", "phrases": [], "grammar": []}}, "model": {"answer": "Let me tell you about the time I taught my neighbour, Zulfiya-opa, to make video calls. It was two winters ago. She’s in her seventies, lives alone on the floor below us, and her son works in Seoul, so she hadn’t seen his face for almost three years. She’s the kind of person who would give you the shirt off her back; there was always a plate of samsa waiting outside our door. She had bought a smartphone, but it was gathering dust in a drawer because she was afraid of pressing the wrong button. One evening, out of the blue, she asked if I could show her “the thing with faces”. So for a week I would pop down for twenty minutes after dinner. I wrote the steps on a card in large print, since her eyesight isn’t good, and we practised over and over until she got the hang of it. On the first call she held the phone at arm’s length, shouting, “Can you hear me?”, and then burst into tears when his face appeared. I felt a warm glow I hadn’t expected. What stayed with me was how little effort it took. Had I turned a blind eye, she might still be missing him through a silent phone. These days she insists on inviting me for plov, and I can never talk her out of it. It taught me that the most valuable help is often small, and that a few quiet evenings can mean the world to someone.", "sections": [{"label": "What", "text": "Let me tell you about the time I taught my neighbour, Zulfiya-opa, to make video calls. It was two winters ago. She’s in her seventies, lives alone on the floor below us, and her son works in Seoul, so she hadn’t seen his face for almost three years."}, {"label": "Who", "text": "She’s the kind of person who would give you the shirt off her back; there was always a plate of samsa waiting outside our door. She had bought a smartphone, but it was gathering dust in a drawer because she was afraid of pressing the wrong button."}, {"label": "How", "text": "One evening, out of the blue, she asked if I could show her “the thing with faces”. So for a week I would pop down for twenty minutes after dinner. I wrote the steps on a card in large print, since her eyesight isn’t good, and we practised over and over until she got the hang of it. On the first call she held the phone at arm’s length, shouting, “Can you hear me?”, and then burst into tears when his face appeared."}, {"label": "Feelings", "text": "I felt a warm glow I hadn’t expected. What stayed with me was how little effort it took. Had I turned a blind eye, she might still be missing him through a silent phone. These days she insists on inviting me for plov, and I can never talk her out of it."}, {"label": "Reflection", "text": "It taught me that the most valuable help is often small, and that a few quiet evenings can mean the world to someone."}], "phrases": [["give you the shirt off her back", "be extremely generous"], ["gathering dust", "not being used for a long time"], ["out of the blue", "unexpectedly"], ["pop down", "go to a lower floor for a short visit"], ["over and over", "many times"], ["got the hang of it", "learned how to do it"], ["burst into tears", "suddenly began to cry"], ["a warm glow", "a pleasant feeling of satisfaction"], ["turned a blind eye", "deliberately ignored a problem"], ["talk her out of it", "persuade her not to do something"], ["mean the world", "be extremely important"]], "grammar": [{"pattern": "Relative clause with who", "use": "the kind of person who + would", "example": "She’s the kind of person who would give you the shirt off her back", "try": "He’s the kind of person who would ______."}, {"pattern": "Past perfect", "use": "had + past participle for an earlier time", "example": "she hadn’t seen his face for almost three years", "try": "She hadn’t ______ for ______."}, {"pattern": "Would for past habit", "use": "would + infinitive for repeated past action", "example": "I would pop down for twenty minutes after dinner", "try": "Every evening I would ______."}, {"pattern": "Until clause", "use": "until + subject + past simple", "example": "we practised over and over until she got the hang of it", "try": "We practised until ______."}, {"pattern": "Cleft sentence", "use": "What + verb + was + clause", "example": "What stayed with me was how little effort it took.", "try": "What stayed with me was ______."}, {"pattern": "Inverted third conditional", "use": "Had + subject + past participle, ... might", "example": "Had I turned a blind eye, she might still be missing him", "try": "Had I ______, ______ might ______."}]}}, "part3": {"intro": "We’ve been talking about a situation when you helped someone, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Helping someone", "title": "Helping someone", "questions": [{"q": "Should children help their parents with household chores?", "model": {"answer": "Yes, within reason. Chores teach responsibility: a child who pitches in learns that a home runs on shared effort, not one person’s sacrifice. The tasks should be age-appropriate, though, such as setting the table for a seven-year-old or cooking simple meals for a teenager. When families divide up the work fairly, children grow into adults who don’t expect others to clean up after them.", "phrases": [["within reason", "up to a sensible limit"], ["pitches in", "helps with a shared task"], ["age-appropriate", "suitable for a child’s age"], ["divide up", "share out"], ["clean up after them", "tidy the mess they make"]], "grammar": [{"pattern": "Relative clause", "use": "a child who + verb", "example": "a child who pitches in learns that a home runs on shared effort", "try": "A child who ______ learns that ______."}, {"pattern": "Grow into", "use": "grow into + noun + relative clause", "example": "children grow into adults who don’t expect others to clean up after them", "try": "Children grow into adults who ______."}]}}, {"q": "Should children be taught to help other people?", "model": {"answer": "Without a doubt, because kindness doesn’t come naturally; it has to be practised. Children who volunteer, even by collecting clothes for a charity drive, learn that other people’s problems are real, which nurtures compassion. It also gives them a sense of purpose and builds confidence. If children never learn this, they risk growing up self-absorbed and blind to the needs around them.", "phrases": [["come naturally", "happen without effort or training"], ["nurtures compassion", "helps kindness grow"], ["a sense of purpose", "feeling that your actions matter"], ["builds confidence", "makes someone feel more self-assured"], ["blind to", "unable to notice"]], "grammar": [{"pattern": "Passive modal", "use": "has to be + past participle", "example": "it has to be practised", "try": "Good manners have to be ______."}, {"pattern": "First conditional with risk", "use": "If + present, they risk + -ing", "example": "If children never learn this, they risk growing up self-absorbed", "try": "If they never ______, they risk ______."}]}}, {"q": "Should parents reward children when they help others?", "model": {"answer": "Occasionally, but not routinely. A small treat or warm praise can reinforce good behaviour, especially with young children. However, if every kind act earns a prize, children may come to expect one, which defeats the purpose. I’d suggest verbal appreciation instead: “That was thoughtful.” Once helping becomes second nature, rewards are unnecessary, because the real payoff is seeing someone smile.", "phrases": [["reinforce", "make stronger by repeating"], ["come to expect", "gradually start to assume"], ["defeats the purpose", "makes the effort pointless"], ["second nature", "something done automatically"], ["the real payoff", "the true benefit"]], "grammar": [{"pattern": "Once clause", "use": "Once + present, main clause", "example": "Once helping becomes second nature, rewards are unnecessary", "try": "Once ______ becomes ______, ______."}, {"pattern": "Relative clause", "use": "which referring to a whole clause", "example": "which defeats the purpose", "try": "______, which defeats the purpose."}]}}, {"q": "Who should teach children to help others, parents or teachers?", "model": {"answer": "Both, but parents have the first and strongest influence. Children take their cue from what they see at home; if parents help neighbours, the lesson sinks in without a word. Schools can back up that example through group projects and community service. Where parents are too busy, teachers fill the gap. Ideally, the two work hand in hand, so the message stays consistent.", "phrases": [["take their cue from", "copy the behaviour of"], ["sinks in", "is fully understood"], ["back up", "support"], ["fill the gap", "provide what is missing"], ["work hand in hand", "cooperate closely"]], "grammar": [{"pattern": "Relative noun clause", "use": "what + subject + verb", "example": "what they see at home", "try": "Children copy what they ______."}, {"pattern": "Where clause", "use": "Where + situation, main clause", "example": "Where parents are too busy, teachers fill the gap", "try": "Where ______, ______."}]}}, {"q": "Why do some people help strangers while others do not?", "model": {"answer": "Partly personality, partly experience. People who were once rescued by a stranger often pay it forward, whereas others, wary of scams, prefer to keep their distance. Upbringing matters, too: if you grew up in a close-knit community, helping feels normal. In big cities, people are in a hurry and assume somebody else will step in. Nobody is simply selfish; hesitation often comes from fear of embarrassment.", "phrases": [["pay it forward", "help others because someone helped you"], ["wary of", "cautious about"], ["keep their distance", "avoid getting involved"], ["close-knit", "with strong, friendly bonds"], ["step in", "get involved to help"], ["fear of embarrassment", "worry about looking foolish"]], "grammar": [{"pattern": "Past passive", "use": "were + once + past participle", "example": "People who were once rescued by a stranger often pay it forward", "try": "People who were once ______ often ______."}, {"pattern": "Second-type conditional in the past", "use": "if + past simple, present result", "example": "if you grew up in a close-knit community, helping feels normal", "try": "If you grew up ______, ______ feels normal."}]}}, {"q": "Do you think people help each other less now than in the past?", "model": {"answer": "I wouldn’t say less, but differently. In the past, neighbours popped in all the time and shared food or tools, and that sense of community has weakened in apartment blocks. On the other hand, technology lets people come to the rescue instantly through crowdfunding and volunteer groups. So the spirit of generosity hasn’t vanished; it has simply moved online, and arguably reaches further.", "phrases": [["popped in", "visited briefly without much notice"], ["sense of community", "feeling of belonging to a group"], ["come to the rescue", "help someone in trouble"], ["the spirit of generosity", "the general attitude of giving"], ["moved online", "shifted to the internet"]], "grammar": [{"pattern": "Present perfect", "use": "has + past participle for change", "example": "has weakened in apartment blocks", "try": "That has ______ in recent years."}, {"pattern": "Contrast with on the other hand", "use": "On the other hand, + contrast", "example": "On the other hand, technology lets people come to the rescue instantly", "try": "On the other hand, ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Events & experiences"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000059', 1059, 'Topic 59', 'Happy person', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 59, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a happy person you know", "bullets": ["who this person is", "what this person is like", "how this person shows happiness", "why you think this person is happy"], "explain": "", "notes": ["Who", "What", "How", "Why"], "rounding": {"q": "Do you think you are a happy person yourself?", "model": {"answer": "Most of the time, yes. I get stressed during exams like anyone else, but I’ve learned from my uncle to notice the small pleasures, and that keeps me fairly cheerful.", "phrases": [], "grammar": []}}, "model": {"answer": "If I had to pick one person, it would be my uncle Botir, my mother’s younger brother, who runs a small bakery in Margilan. I’ve spent most of my summers helping in his shop, so I know him well. He isn’t rich or famous, but he’s down-to-earth, wonderfully easy-going, and the sort of person who strikes up a conversation with everyone: customers, delivery drivers, even stray cats. He’s also a bit of a joker, always teasing his regular customers. You can tell when he’s happy because he whistles off-key while kneading dough, usually some old tune from the nineties. He has a contagious laugh that fills the whole shop, and when a loaf comes out perfectly, he holds it up like a trophy and shouts, “Look at that beauty!” I think the reason he’s so content is that he has his priorities straight. Years ago he was offered a well-paid job at a factory in Tashkent, and he turned it down to stay near his family. I once asked whether he regretted it. He shrugged and said, “I wake up to the smell of fresh bread. What more could I want?” He never worries about keeping up with the Joneses, and he counts his blessings every day. Being around him has taught me that happiness isn’t about having more; it’s about appreciating what you already have. Whenever I’m stressed, I picture him whistling, and it puts a smile on my face.", "sections": [{"label": "Who", "text": "If I had to pick one person, it would be my uncle Botir, my mother’s younger brother, who runs a small bakery in Margilan. I’ve spent most of my summers helping in his shop, so I know him well."}, {"label": "What", "text": "He isn’t rich or famous, but he’s down-to-earth, wonderfully easy-going, and the sort of person who strikes up a conversation with everyone: customers, delivery drivers, even stray cats. He’s also a bit of a joker, always teasing his regular customers."}, {"label": "How", "text": "You can tell when he’s happy because he whistles off-key while kneading dough, usually some old tune from the nineties. He has a contagious laugh that fills the whole shop, and when a loaf comes out perfectly, he holds it up like a trophy and shouts, “Look at that beauty!”"}, {"label": "Why", "text": "I think the reason he’s so content is that he has his priorities straight. Years ago he was offered a well-paid job at a factory in Tashkent, and he turned it down to stay near his family. I once asked whether he regretted it. He shrugged and said, “I wake up to the smell of fresh bread. What more could I want?” He never worries about keeping up with the Joneses, and he counts his blessings every day."}, {"label": "Reflection", "text": "Being around him has taught me that happiness isn’t about having more; it’s about appreciating what you already have. Whenever I’m stressed, I picture him whistling, and it puts a smile on my face."}], "phrases": [["down-to-earth", "practical and unpretentious"], ["easy-going", "relaxed and not easily upset"], ["strikes up a conversation", "starts talking to someone naturally"], ["a bit of a joker", "someone who likes making jokes"], ["off-key", "not in tune musically"], ["a contagious laugh", "a laugh that makes others laugh"], ["has his priorities straight", "knows what is truly important"], ["turned it down", "refused an offer"], ["keeping up with the Joneses", "competing with neighbours to own as much as them"], ["counts his blessings", "feels grateful for what he has"], ["puts a smile on my face", "makes me happy"]], "grammar": [{"pattern": "Second conditional", "use": "If + past simple, it would be...", "example": "If I had to pick one person, it would be my uncle Botir", "try": "If I had to choose one person, it would be ______."}, {"pattern": "Relative clause", "use": "the sort of person who + verb", "example": "the sort of person who strikes up a conversation with everyone", "try": "She’s the sort of person who ______."}, {"pattern": "Passive voice", "use": "was offered + noun", "example": "he was offered a well-paid job at a factory in Tashkent", "try": "He was offered ______, but ______."}, {"pattern": "Reported question", "use": "asked + whether + clause", "example": "I once asked whether he regretted it", "try": "I asked whether ______."}, {"pattern": "Reason clause", "use": "the reason + subject + is + that...", "example": "the reason he’s so content is that he has his priorities straight", "try": "The reason ______ is that ______."}, {"pattern": "Whenever clause", "use": "Whenever + present, present", "example": "Whenever I’m stressed, I picture him whistling", "try": "Whenever I’m ______, I ______."}]}}, "part3": {"intro": "We’ve been talking about a happy person you know, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Happy person", "title": "Happy person", "questions": [{"q": "How would you define happiness?", "model": {"answer": "For me, happiness is a steady sense of contentment rather than constant excitement. It means feeling at peace with your life: having people you love, work that matters and enough time to unwind. Moments of joy, like a good exam result or a holiday, are lovely, but they come and go. I’d say happiness is what remains in the background when nothing is going wrong.", "phrases": [["sense of contentment", "a calm feeling of satisfaction"], ["at peace with", "accepting and calm about"], ["unwind", "relax after stress"], ["come and go", "appear for a time and then disappear"], ["in the background", "quietly present, not obvious"]], "grammar": [{"pattern": "Gerund after feel", "use": "feeling + adjective + preposition", "example": "It means feeling at peace with your life", "try": "Happiness means feeling ______."}, {"pattern": "Relative clause", "use": "what remains + when", "example": "what remains in the background when nothing is going wrong", "try": "Happiness is what remains when ______."}]}}, {"q": "What kinds of things make people in your country happy?", "model": {"answer": "Family gatherings come first for most people. A big table, three generations and plenty of plov are hard to beat. Weddings and festivals such as Navruz also bring communities together. Beyond that, stability matters: a steady income, a decent home and good health. Younger people, meanwhile, increasingly value travel and career prospects, though family remains the common thread. Pride in local traditions plays a part as well.", "phrases": [["hard to beat", "better than almost anything else"], ["bring communities together", "unite people in a group"], ["steady income", "regular, reliable earnings"], ["career prospects", "chances of professional progress"], ["the common thread", "the shared element"]], "grammar": [{"pattern": "Present simple for general truth", "use": "come first / are hard to beat", "example": "A big table, three generations and plenty of plov are hard to beat.", "try": "______ are hard to beat."}, {"pattern": "Concession with though", "use": "clause, though + clause", "example": "though family remains the common thread", "try": "______, though ______."}]}}, {"q": "Can money make people happy?", "model": {"answer": "Up to a point. When people are struggling to make ends meet, extra money genuinely reduces stress and opens doors, such as better healthcare. Beyond a comfortable level, though, the effect fades; the wealthiest people I know are not noticeably happier. What money can’t buy is time with loved ones or peace of mind. So it’s a means to an end, not happiness itself.", "phrases": [["Up to a point.", "partly but not completely"], ["struggling to make ends meet", "hardly able to pay for basic needs"], ["opens doors", "creates opportunities"], ["peace of mind", "freedom from worry"], ["a means to an end", "a way of getting something else"]], "grammar": [{"pattern": "Time clause with when", "use": "When + present continuous, present simple", "example": "When people are struggling to make ends meet, extra money genuinely reduces stress", "try": "When people are ______, ______."}, {"pattern": "Cleft sentence", "use": "What + subject + can’t + verb + is", "example": "What money can’t buy is time with loved ones or peace of mind.", "try": "What money can’t buy is ______."}]}}, {"q": "How do people express their happiness in your culture?", "model": {"answer": "Quite openly, I’d say. People give each other bear hugs, laugh out loud and, above all, share food. Even a passing neighbour gets invited in for tea. When someone gets good news, relatives drop by unannounced with sweets, and soon the whole street has joined in. Hospitality is a way of saying “I’m happy, so let’s celebrate,” which is how people spread the joy.", "phrases": [["bear hugs", "tight, warm hugs"], ["laugh out loud", "laugh in an open, noisy way"], ["drop by", "visit casually"], ["joined in", "started taking part"], ["spread the joy", "share happiness with others"]], "grammar": [{"pattern": "Present perfect with soon", "use": "soon + subject + has + past participle", "example": "soon the whole street has joined in", "try": "Soon everyone has ______."}, {"pattern": "Relative clause with which", "use": "comma + which is how...", "example": "which is how people spread the joy", "try": "______, which is how ______."}]}}, {"q": "Why do some people say that happiness never lasts long?", "model": {"answer": "Because we adapt so quickly. A new phone thrills you for a week, then it becomes part of the furniture. Happiness linked to events, such as promotions, wears off because events are temporary. People who feel lasting satisfaction usually cultivate habits like friendships and hobbies instead of chasing the next high. In that sense, happiness is less a destination than a practice.", "phrases": [["part of the furniture", "so familiar that you no longer notice it"], ["wears off", "gradually disappears"], ["cultivate", "develop with care"], ["chasing the next high", "constantly seeking another thrill"], ["less a destination than a practice", "more of a continuing habit than a final goal"]], "grammar": [{"pattern": "Past participle clause", "use": "noun + linked to + noun", "example": "Happiness linked to events, such as promotions, wears off", "try": "______ linked to ______ wears off."}, {"pattern": "Instead of + gerund", "use": "instead of + -ing", "example": "instead of chasing the next high", "try": "instead of ______ing."}]}}, {"q": "Are people in your country happier now than they were thirty years ago?", "model": {"answer": "Materially, life has improved: more choice, better technology and easier travel. But happiness isn’t just material. Thirty years ago, many people had less but felt a stronger sense of belonging, whereas today the pace of life and social media fuel comparison. People are better off but not necessarily happier, although younger generations enjoy freedoms their parents could only dream of.", "phrases": [["a stronger sense of belonging", "a closer feeling of being part of a group"], ["the pace of life", "how fast daily life moves"], ["fuel comparison", "encourage people to compare themselves"], ["better off", "richer or more comfortable"], ["could only dream of", "never had the chance to have"]], "grammar": [{"pattern": "Comparison with whereas", "use": "whereas + contrast", "example": "whereas today the pace of life and social media fuel comparison", "try": "Then ______, whereas today ______."}, {"pattern": "Relative clause without pronoun", "use": "noun + subject + verb + of", "example": "freedoms their parents could only dream of", "try": "opportunities their grandparents ______ of."}]}}, {"q": "Do you agree that real happiness comes from making other people happy?", "model": {"answer": "To a large extent. Many of my happiest moments have involved doing someone a good turn, such as cooking for a sick friend. Giving takes you out of yourself, which eases worry. Still, it can’t be the whole story: people who neglect their own needs burn out and eventually resent others. So real happiness probably needs a healthy balance between giving and looking after yourself.", "phrases": [["To a large extent", "mostly"], ["doing someone a good turn", "helping someone"], ["takes you out of yourself", "stops you thinking only about your own worries"], ["burn out", "become exhausted"], ["a healthy balance", "a good proportion of two things"]], "grammar": [{"pattern": "Present perfect", "use": "have + involved", "example": "Many of my happiest moments have involved doing someone a good turn", "try": "Many of my best moments have involved ______."}, {"pattern": "Relative clause", "use": "people who + verb", "example": "people who neglect their own needs burn out", "try": "People who ______ eventually ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "People"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000060', 1060, 'Topic 60', 'Person who has healthy habits', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 60, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a person you know who has healthy habits and a healthy daily routine", "bullets": ["who this person is", "how you got to know each other", "what this person does to keep this lifestyle", "how you feel about this person"], "explain": "", "notes": ["Who", "How We Met", "What He Does", "Feelings"], "rounding": {"q": "Would you like to follow the same routine as him?", "model": {"answer": "I’d love to, at least part of it. Five-thirty runs are a stretch for me, but I’m trying to copy his sleep habits first, since that seems the easiest place to start.", "phrases": [], "grammar": []}}, "model": {"answer": "The first person who comes to mind is my friend Timur, a fourth-year medical student, who is the picture of health. He’s twenty-two, tall, and always looks rested, which is remarkable for someone who spends half his life in hospital wards. We met two years ago in the university swimming pool. I had joined hoping to keep fit, but I was out of my depth, quite literally, and could barely finish a single length. Timur, who was swimming in the next lane, noticed and showed me how to breathe properly. We’ve been friends ever since. His routine is remarkably consistent. He gets up at the crack of dawn, around five-thirty, and runs along the canal rain or shine. He doesn’t follow a strict diet, but he steers clear of fizzy drinks and fast food, and he’s firm about sleep, switching off his phone by ten. Even during exams, he sticks to it. What I admire most is that he never preaches. He doesn’t look down on people who eat badly; he simply leads by example. Honestly, he’s a role model to me. Since we met, I’ve cut back on sugar and I swim twice a week, although I envy his self-discipline, which I’m still working on. Knowing him has shown me that health isn’t about dramatic changes. It’s about small habits, repeated daily, until they stop feeling like effort. That, to me, is the real lesson.", "sections": [{"label": "Who", "text": "The first person who comes to mind is my friend Timur, a fourth-year medical student, who is the picture of health. He’s twenty-two, tall, and always looks rested, which is remarkable for someone who spends half his life in hospital wards."}, {"label": "How We Met", "text": "We met two years ago in the university swimming pool. I had joined hoping to keep fit, but I was out of my depth, quite literally, and could barely finish a single length. Timur, who was swimming in the next lane, noticed and showed me how to breathe properly. We’ve been friends ever since."}, {"label": "What He Does", "text": "His routine is remarkably consistent. He gets up at the crack of dawn, around five-thirty, and runs along the canal rain or shine. He doesn’t follow a strict diet, but he steers clear of fizzy drinks and fast food, and he’s firm about sleep, switching off his phone by ten. Even during exams, he sticks to it."}, {"label": "Feelings", "text": "What I admire most is that he never preaches. He doesn’t look down on people who eat badly; he simply leads by example. Honestly, he’s a role model to me. Since we met, I’ve cut back on sugar and I swim twice a week, although I envy his self-discipline, which I’m still working on."}, {"label": "Reflection", "text": "Knowing him has shown me that health isn’t about dramatic changes. It’s about small habits, repeated daily, until they stop feeling like effort. That, to me, is the real lesson."}], "phrases": [["the picture of health", "looking extremely healthy"], ["keep fit", "stay in good physical shape"], ["out of my depth", "in a situation too difficult for me"], ["gets up at the crack of dawn", "wakes very early at sunrise"], ["rain or shine", "in any weather"], ["steers clear of", "deliberately avoids"], ["sticks to", "continues to follow"], ["look down on", "think you are better than"], ["leads by example", "shows others how to behave by acting that way"], ["a role model", "a person others want to copy"], ["cut back on", "reduce"], ["self-discipline", "the ability to control yourself"]], "grammar": [{"pattern": "Non-defining relative clause", "use": "Name, who + verb, ...", "example": "Timur, who was swimming in the next lane, noticed", "try": "My friend, who ______, ______."}, {"pattern": "Past continuous interrupted", "use": "past continuous + noticed", "example": "who was swimming in the next lane, noticed", "try": "I was ______ when ______."}, {"pattern": "Present perfect with ever since", "use": "We’ve + past participle + ever since", "example": "We’ve been friends ever since.", "try": "We’ve been ______ ever since."}, {"pattern": "Cleft sentence", "use": "What + I + verb + is that", "example": "What I admire most is that he never preaches.", "try": "What I admire most is that ______."}, {"pattern": "Contrast with although", "use": "although + clause", "example": "although I envy his self-discipline", "try": "Although ______, I ______."}, {"pattern": "Present perfect for experience", "use": "Knowing him has shown me that...", "example": "Knowing him has shown me that health isn’t about dramatic changes.", "try": "Knowing ______ has shown me that ______."}]}}, "part3": {"intro": "We’ve been talking about a person you know who has healthy habits and a healthy daily routine, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Person who has healthy habits", "title": "Person who has healthy habits", "questions": [{"q": "What kinds of things make people stressed in everyday life?", "model": {"answer": "Mostly pressure from money, work and time. Many people juggle a demanding job with family responsibilities, so they feel permanently stretched thin. Commuting in heavy traffic, tight deadlines and constant notifications make it worse, as small irritations pile up. Students, meanwhile, worry about exams and the future. What really hurts is bottling it up: those who talk about their problems usually cope far better.", "phrases": [["juggle", "manage several demands at once"], ["stretched thin", "having too many commitments"], ["tight deadlines", "very short time limits"], ["pile up", "accumulate"], ["bottling it up", "not expressing feelings"]], "grammar": [{"pattern": "Cleft sentence", "use": "What + verb + is + gerund", "example": "What really hurts is bottling it up", "try": "What really hurts is ______ing."}, {"pattern": "Relative clause", "use": "those who + verb", "example": "those who talk about their problems usually cope far better", "try": "Those who ______ usually ______."}]}}, {"q": "Is it hard for people to live a healthy lifestyle nowadays?", "model": {"answer": "In many ways, yes, because temptation is everywhere. Fast food is cheap and delivered to your door, and sitting at a desk all day has become the norm. Healthy choices demand willpower and often cost more. That said, workout videos and nutrition advice are easier to find than ever, so those who make an effort can succeed; the real obstacle is consistency.", "phrases": [["delivered to your door", "brought directly to your home"], ["the norm", "what is usual"], ["willpower", "the strength to control yourself"], ["make an effort", "try hard"], ["the real obstacle", "the true difficulty"]], "grammar": [{"pattern": "Present perfect", "use": "has become", "example": "sitting at a desk all day has become the norm", "try": "______ has become the norm."}, {"pattern": "Comparative with than ever", "use": "easier + than ever", "example": "are easier to find than ever", "try": "It’s ______er than ever to ______."}]}}, {"q": "What can parents do to improve their children’s health awareness?", "model": {"answer": "They can start by leading by example: children rarely eat vegetables if their parents don’t. Cooking together, explaining why sugary snacks should stay occasional treats, and walking to school all instil good habits. Parents should also limit screen time without turning it into a battle. If health feels enjoyable rather than imposed, children are likelier to carry it into adulthood.", "phrases": [["leading by example", "showing the behaviour you want"], ["sugary snacks", "sweets and similar foods"], ["instil good habits", "gradually teach positive routines"], ["limit screen time", "restrict time on devices"], ["carry it into adulthood", "continue it when they grow up"]], "grammar": [{"pattern": "Zero/first conditional", "use": "if + present, present", "example": "children rarely eat vegetables if their parents don’t", "try": "Children rarely ______ if ______."}, {"pattern": "Gerund as subject", "use": "Cooking together... all instil", "example": "Cooking together, explaining why sugary snacks should stay occasional treats, and walking to school all instil good habits", "try": "Cooking together and ______ all ______."}]}}, {"q": "Do schools have a responsibility to provide health education?", "model": {"answer": "Yes, I’d argue they do, because school is where children spend the bulk of their day. Not every family can teach nutrition or first aid, so schools level the playing field. Lessons on hygiene, mental health and exercise should be built into the curriculum, not treated as an afterthought. That said, schools can only lay the groundwork; families must follow through.", "phrases": [["spend the bulk of", "spend most of"], ["level the playing field", "make opportunities equal"], ["built into the curriculum", "included as a regular part of lessons"], ["an afterthought", "something added late and treated as unimportant"], ["lay the groundwork", "prepare a base for later progress"]], "grammar": [{"pattern": "Place clause", "use": "school is where + subject + verb", "example": "school is where children spend the bulk of their day", "try": "School is where ______."}, {"pattern": "Passive modal", "use": "should be + past participle", "example": "should be built into the curriculum", "try": "______ should be ______ into ______."}]}}, {"q": "Where can people find information about staying healthy?", "model": {"answer": "Nowadays, mostly online, though quality varies enormously. Reputable hospital websites are reliable, whereas social media is full of miracle cures and fad diets. I’d advise cross-checking anything surprising. Traditional sources still matter: a family doctor can tailor advice to your situation, and pharmacists are often a first port of call for minor problems. Public health leaflets and local clinics help, too.", "phrases": [["miracle cures", "remedies claimed to work wonders"], ["fad diets", "trendy diets with little lasting value"], ["cross-checking", "verifying with another source"], ["tailor advice", "adapt advice to one person"], ["a first port of call", "the first place to go for help"]], "grammar": [{"pattern": "Contrast with whereas", "use": "whereas + contrast", "example": "whereas social media is full of miracle cures", "try": "______ is reliable, whereas ______."}, {"pattern": "Advice with I’d advise + gerund", "use": "I’d advise + -ing", "example": "I’d advise cross-checking anything surprising", "try": "I’d advise ______ing."}]}}, {"q": "How can the media influence people’s knowledge about health?", "model": {"answer": "Considerably, for better or worse. A well-made documentary can raise awareness of issues such as sugar or smoking, and campaigns spread the word quickly. On the downside, headlines often oversimplify research, so people hear that one food “causes” or “cures” something. Constant adverts for snacks also normalise unhealthy eating. Documentaries and short videos reach audiences that textbooks never will. That’s why media literacy matters.", "phrases": [["for better or worse", "with both good and bad effects"], ["raise awareness", "make people notice an issue"], ["spread the word", "communicate widely"], ["oversimplify", "make something seem simpler than it is"], ["normalise", "make something seem normal"]], "grammar": [{"pattern": "clause, so + clause", "use": "", "example": "causes” or “cures” something", "try": "______, so ______."}, {"pattern": "Cleft sentence", "use": "That’s why + clause", "example": "That’s why media literacy matters.", "try": "That’s why ______."}]}}, {"q": "Should governments use celebrities to promote healthy lifestyles?", "model": {"answer": "It can work, provided the celebrity is credible. A footballer who genuinely trains can strike a chord with young fans who look up to them. The danger is that a paid endorsement can ring hollow, or the star may later contradict the message. So governments should tread carefully and combine campaigns with concrete measures, like cheaper sports facilities. Otherwise the campaign is simply advertising, and people notice.", "phrases": [["strike a chord with", "appeal strongly to"], ["look up to", "admire"], ["ring hollow", "seem insincere"], ["tread carefully", "act with caution"], ["concrete measures", "practical actions"]], "grammar": [{"pattern": "Provided that", "use": "provided + clause", "example": "provided the celebrity is credible", "try": "It works provided ______."}, {"pattern": "Relative clause", "use": "footballer who + verb", "example": "A footballer who genuinely trains can strike a chord", "try": "A ______ who ______ can ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "People"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000061', 1061, 'Topic 61', 'Very organized person', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 61, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a person you know who is very organized", "bullets": ["who this person is", "what this person does to stay organized", "in what situations you notice this", "why you think being organized is important to them"], "explain": "", "notes": ["Who", "How", "When", "Why"], "rounding": {"q": "Do you think you are an organised person yourself?", "model": {"answer": "Not as much as Dilnoza, to be honest. I’m fairly good with deadlines, but my desk tends to turn into a battlefield, so I’m trying to copy her Sunday planning habit.", "phrases": [], "grammar": []}}, "model": {"answer": "If I had to pick one person, it would be my cousin Dilnoza, who works as a project coordinator for a construction company in Tashkent. She’s thirty-two, and without a shadow of a doubt she’s the most organised person I know. What strikes you first is her notebook, a thick paper planner in which every task has a colour, a deadline and a backup plan. Every Sunday evening she maps out the week ahead over a cup of tea, and she never goes to bed before ticking off what she’s finished. She also sticks to one simple rule: if something takes less than two minutes, she does it straight away instead of putting it off. I notice it most when things go wrong. Last spring, my sister’s wedding was suddenly brought forward by a month, and while the rest of us were panicking, Dilnoza calmly opened her planner and took charge. Within an hour she had split the jobs between us, booked the hall and drawn up a guest list. Had she not stepped in, we would have ended up in a mess. Even on holiday, she’s the one who has printed the tickets and checked the weather. As for why it matters to her, she grew up in a household where, as she once told me, nobody could ever find the car keys. Being organised gives her peace of mind; it’s less about control than about leaving room to enjoy life. Looking back, what she has taught me is that a good system frees up your head for the things that really matter, and I’m slowly trying to pick up that habit myself.", "sections": [{"label": "Who", "text": "If I had to pick one person, it would be my cousin Dilnoza, who works as a project coordinator for a construction company in Tashkent. She’s thirty-two, and without a shadow of a doubt she’s the most organised person I know."}, {"label": "How", "text": "What strikes you first is her notebook, a thick paper planner in which every task has a colour, a deadline and a backup plan. Every Sunday evening she maps out the week ahead over a cup of tea, and she never goes to bed before ticking off what she’s finished. She also sticks to one simple rule: if something takes less than two minutes, she does it straight away instead of putting it off."}, {"label": "When", "text": "I notice it most when things go wrong. Last spring, my sister’s wedding was suddenly brought forward by a month, and while the rest of us were panicking, Dilnoza calmly opened her planner and took charge. Within an hour she had split the jobs between us, booked the hall and drawn up a guest list. Had she not stepped in, we would have ended up in a mess. Even on holiday, she’s the one who has printed the tickets and checked the weather."}, {"label": "Why", "text": "As for why it matters to her, she grew up in a household where, as she once told me, nobody could ever find the car keys. Being organised gives her peace of mind; it’s less about control than about leaving room to enjoy life. Looking back, what she has taught me is that a good system frees up your head for the things that really matter, and I’m slowly trying to pick up that habit myself."}], "phrases": [["without a shadow of a doubt", "completely certain, with no doubt at all"], ["maps out", "plans in detail, step by step"], ["ticking off", "marking a task as done on a list"], ["sticks to", "keeps following a rule or plan"], ["putting it off", "delaying something you should do now"], ["took charge", "took control of a situation and led it"], ["drawn up", "prepared a written document or plan"], ["ended up in a mess", "finally found ourselves in a bad, chaotic situation"], ["gives her peace of mind", "makes her feel calm and free from worry"], ["frees up", "makes space or time available"], ["pick up", "learn or acquire a habit naturally"]], "grammar": [{"pattern": "Relative clause with a preposition", "use": "noun + in which + clause", "example": "a thick paper planner in which every task has a colour, a deadline and a backup plan", "try": "My phone is a tool in which I ______."}, {"pattern": "Cleft sentence", "use": "What + subject + verb + is ...", "example": "What strikes you first is her notebook", "try": "What impresses me most about him is ______."}, {"pattern": "Inverted third conditional", "use": "Had + subject + not + past participle, would have + past participle", "example": "Had she not stepped in, we would have ended up in a mess", "try": "Had I not ______, I would have ______."}, {"pattern": "Past perfect after a time phrase", "use": "Within + time, subject + had + past participle", "example": "Within an hour she had split the jobs between us", "try": "Within a week, I had ______."}, {"pattern": "", "use": "Comparison: less ... than it’s less about A than about B", "example": "it’s less about control than about leaving room to enjoy life", "try": "For me, learning is less about ______ than about ______."}]}}, "part3": {"intro": "We’ve been talking about a person you know who is very organized, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Very organized person", "title": "Very organized person", "questions": [{"q": "How can parents help children to be organised?", "model": {"answer": "Mostly by setting an example. Children pick up habits from what they see, so if parents keep on top of their own schedules, kids tend to copy them. Small responsibilities help too, such as getting into the habit of packing a school bag the night before or keeping a to-do list on the fridge. A nagged child will often rebel, whereas a trusted one rises to the occasion.", "phrases": [["pick up", "learn naturally by watching others"], ["keep on top of", "manage well, without falling behind"], ["getting into the habit of", "starting to do something regularly"], ["to-do list", "a written list of tasks to complete"], ["rises to the occasion", "behaves well when given responsibility"]], "grammar": [{"pattern": "Contrast with whereas", "use": "A ..., whereas B ...", "example": "A nagged child will often rebel, whereas a trusted one rises to the occasion", "try": "Some students ______, whereas others ______."}, {"pattern": "Conditional with if + present", "use": "if + present simple, subject + tend to", "example": "if parents keep on top of their own schedules, kids tend to copy them", "try": "If teachers ______, students tend to ______."}]}}, {"q": "Why are some people more organised than others?", "model": {"answer": "Partly it’s upbringing and partly personality. People who grew up in households with clear routines tend to take structure for granted, whereas others have to learn it deliberately. Temperament also plays a part: some of us are naturally detail-oriented, while others prefer to go with the flow. That said, it isn’t fixed. I know several disorganised people who turned over a new leaf after starting their first proper job.", "phrases": [["take structure for granted", "assume order is normal and never notice it"], ["plays a part", "has an influence"], ["detail-oriented", "careful about small details"], ["go with the flow", "relax and accept whatever happens"], ["turned over a new leaf", "changed their behaviour for the better"]], "grammar": [{"pattern": "Concession", "use": "That said, + clause", "example": "That said, it isn’t fixed", "try": "That said, ______."}, {"pattern": "Relative clause with who", "use": "people who + verb", "example": "People who grew up in households with clear routines tend to take structure for granted", "try": "People who ______ tend to ______."}]}}, {"q": "Is being organised more important at work or at home?", "model": {"answer": "If I had to choose, I’d say work, because more is at stake. Missing a deadline can damage your reputation or even cost you a job, whereas a messy kitchen is merely an inconvenience. That said, they’re connected. Someone who can’t get their act together at home, constantly losing keys, will usually let that stress spill over into the office, so the habits go hand in hand.", "phrases": [["more is at stake", "there is more to gain or lose"], ["damage your reputation", "harm how others see you"], ["can’t get their act together", "are unable to organise themselves properly"], ["go hand in hand", "are closely connected and happen together"], ["spill over", "affect another area of life"]], "grammar": [{"pattern": "Second conditional opening", "use": "If I had to + verb, I’d say", "example": "If I had to choose, I’d say work", "try": "If I had to pick, I’d say ______."}, {"pattern": "Relative clause with who", "use": "Someone who + verb, will usually ...", "example": "Someone who can’t get their act together at home, constantly losing keys, will usually let that stress spill over into the office", "try": "Someone who ______ will usually ______."}]}}, {"q": "Does technology help people to become more organised?", "model": {"answer": "Up to a point. Calendar apps and reminders are brilliant for people who have a lot on their plate, and I rely on my phone to keep track of deadlines. But the same device bombards us with notifications, so it can just as easily become a distraction. The more apps we install, the more time we spend managing them. Ultimately, technology works only for people who already have discipline.", "phrases": [["Up to a point", "partly, but not completely"], ["have a lot on their plate", "have many tasks to deal with"], ["keep track of", "follow and remember"], ["bombards us with", "attacks us with a constant stream of"], ["a distraction", "something that stops you concentrating"]], "grammar": [{"pattern": "The more ... the more", "use": "The more + clause, the more + clause", "example": "The more apps we install, the more time we spend managing them", "try": "The more I ______, the more ______."}, {"pattern": "Relative clause with who", "use": "people who + verb", "example": "people who have a lot on their plate", "try": "It is useful for people who ______."}]}}, {"q": "What problems can being disorganised cause?", "model": {"answer": "The most obvious one is wasted time. I once spent twenty minutes searching for my passport on the morning of a flight, and it was a close call. Beyond that, disorganisation takes a toll on relationships, since colleagues and friends get tired of picking up the slack. Over time it can also lead to chronic stress, which snowballs because every missed task creates two new ones.", "phrases": [["a close call", "a situation where something bad nearly happened"], ["takes a toll on", "causes gradual damage to"], ["picking up the slack", "doing work that someone else has not done"], ["chronic stress", "long-lasting, continuous stress"], ["snowballs", "grows bigger and faster out of control"]], "grammar": [{"pattern": "Past continuous/past simple with", "use": "spent spend + time + -ing", "example": "I once spent twenty minutes searching for my passport", "try": "I once spent an hour ______."}, {"pattern": "Non-defining relative clause", "use": "..., which + verb", "example": "chronic stress, which snowballs because every missed task creates two new ones", "try": "______, which ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "People"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000062', 1062, 'Topic 62', 'Person who loves history', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 62, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a person you know who loves history", "bullets": ["who this person is", "how this person learns about history", "why this person loves history", "and explain how you feel about this person"], "explain": "", "notes": ["Who", "How", "Why", "Feelings"], "rounding": {"q": "Would you like to study history yourself one day?", "model": {"answer": "Not formally, perhaps, but I’d love to read much more of it. My uncle has already lent me two books, so I’m slowly becoming a hobbyist.", "phrases": [], "grammar": []}}, "model": {"answer": "Let me tell you about my uncle Rustam, a retired history teacher who lives in Samarkand, not far from the Registan. He’s in his late sixties now, but he still has energy to spare whenever the conversation turns to the past. He learns in every way imaginable. His flat is crammed with books, mostly about the Silk Road, and he pores over old maps with a magnifying glass. He also tracks down elderly neighbours and records their memories on his phone. At weekends you’ll often find him at the ruins of Afrosiyab, notebook in hand, piecing together what the old city must once have looked like. When I asked him why he loved history, he gave me an answer I’ve never forgotten. “Nobody really understands a place until they know how it came to be,” he said. For him, history isn’t a list of dates; it’s a long conversation between generations. I remember standing with him in front of Ulugh Beg’s observatory, where he explained how a ruler had been ahead of his time by studying the stars with such precision. As for how I feel, I admire him enormously. Had it not been for him, I would probably have written off history as just another school subject, but he taught me to look beneath the surface of things. Whenever I visit, I leave with a head full of stories and a deeper respect for where I come from. If anything, he has shown me that curiosity is the habit worth cultivating above all others.", "sections": [{"label": "Who", "text": "Let me tell you about my uncle Rustam, a retired history teacher who lives in Samarkand, not far from the Registan. He’s in his late sixties now, but he still has energy to spare whenever the conversation turns to the past."}, {"label": "How", "text": "He learns in every way imaginable. His flat is crammed with books, mostly about the Silk Road, and he pores over old maps with a magnifying glass. He also tracks down elderly neighbours and records their memories on his phone. At weekends you’ll often find him at the ruins of Afrosiyab, notebook in hand, piecing together what the old city must once have looked like."}, {"label": "Why", "text": "When I asked him why he loved history, he gave me an answer I’ve never forgotten. “Nobody really understands a place until they know how it came to be,” he said. For him, history isn’t a list of dates; it’s a long conversation between generations. I remember standing with him in front of Ulugh Beg’s observatory, where he explained how a ruler had been ahead of his time by studying the stars with such precision."}, {"label": "Feelings", "text": "As for how I feel, I admire him enormously. Had it not been for him, I would probably have written off history as just another school subject, but he taught me to look beneath the surface of things. Whenever I visit, I leave with a head full of stories and a deeper respect for where I come from. If anything, he has shown me that curiosity is the habit worth cultivating above all others."}], "phrases": [["has energy to spare", "is very energetic, with more than enough energy"], ["crammed with", "completely full of"], ["pores over", "studies something very carefully"], ["tracks down", "finds after searching"], ["piecing together", "slowly working out by combining small clues"], ["came to be", "developed or came into existence"], ["been ahead of his time", "had ideas far more advanced than others of his era"], ["written off", "decided something is not worth attention"], ["look beneath the surface", "examine what is not obvious at first"], ["deeper respect", "a stronger feeling of admiration"], ["worth cultivating", "good to develop carefully over time"]], "grammar": [{"pattern": "Relative clause with who", "use": "noun + who + verb", "example": "a retired history teacher who lives in Samarkand", "try": "My neighbour, a doctor who ______."}, {"pattern": "Time clause with whenever", "use": "whenever + clause", "example": "whenever the conversation turns to the past", "try": "Whenever I ______, I ______."}, {"pattern": "Modal of deduction in the past", "use": "must + have + past participle", "example": "what the old city must once have looked like", "try": "It must have ______."}, {"pattern": "Inverted third conditional", "use": "Had it not been for + noun, would have + past participle", "example": "Had it not been for him, I would probably have written off history as just another school subject", "try": "Had it not been for ______, I would have ______."}, {"pattern": "Participle clause", "use": "noun + in hand / -ing clause", "example": "notebook in hand, piecing together what the old city must once have looked like", "try": "______, notebook in hand, ______."}]}}, "part3": {"intro": "We’ve been talking about a person you know who loves history, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Person who loves history", "title": "Person who loves history", "questions": [{"q": "Do you agree that learning history helps people understand the present?", "model": {"answer": "Largely, yes, because most current situations have deep roots. Borders, languages and even food habits in Central Asia only make sense once you know how trade and migration shaped the region. Without that background, we jump to conclusions about why societies behave as they do. That said, history rarely gives clear answers; it should shed light on our decisions rather than dictate them.", "phrases": [["deep roots", "long historical origins"], ["make sense", "become understandable"], ["jump to conclusions", "judge too quickly without enough information"], ["shed light on", "help explain"], ["dictate", "tell someone exactly what to do"]], "grammar": [{"pattern": "Only ... once", "use": "only make sense once + clause", "example": "only make sense once you know how trade and migration shaped the region", "try": "This only makes sense once ______."}, {"pattern": "Concession", "use": "That said, + clause", "example": "That said, history rarely gives clear answers", "try": "That said, ______."}]}}, {"q": "Does modern society have much to learn from the past?", "model": {"answer": "Quite a lot, particularly when it comes to sustainability. Our grandparents’ generation made do with much less: they repaired clothes, shared tools and wasted very little. Today we’re used to a throwaway culture, and the consequences are becoming hard to ignore. I’m not suggesting we return to the old ways, but borrowing the best of them, such as strong neighbourhood ties, would make modern life healthier.", "phrases": [["made do with", "managed with limited resources"], ["throwaway culture", "a habit of discarding things instead of repairing them"], ["the consequences are becoming hard to ignore", "the bad effects are now too obvious to overlook"], ["borrowing the best of", "taking the most useful parts of"], ["when it comes to", "regarding, on the subject of"]], "grammar": [{"pattern": "Particularly when it comes to", "use": "when it comes to + noun", "example": "particularly when it comes to sustainability", "try": "when it comes to ______."}, {"pattern": "Conditional with would", "use": "subject + would + verb", "example": "borrowing the best of them, such as strong neighbourhood ties, would make modern life healthier", "try": "Doing ______ would make ______."}]}}, {"q": "What are the differences between learning history from books and from videos?", "model": {"answer": "On the one hand, books go into far greater depth, and reading forces you to imagine events yourself, which tends to make them stick in your memory. Videos, on the other hand, bring the past to life through footage, reconstructions and music, and they’re far easier to absorb after a long day. I’d start with a documentary to spark your interest, then turn to books to get the full picture.", "phrases": [["go into far greater depth", "explain much more thoroughly"], ["stick in your memory", "be remembered easily"], ["to life", "vivid and real"], ["spark your interest", "make you curious"], ["get the full picture", "understand everything about a subject"]], "grammar": [{"pattern": "Two-sided contrast", "use": "On the one hand ..., on the other hand ...", "example": "On the one hand, books go into far greater depth", "try": "On the one hand, ______. On the other hand, ______."}, {"pattern": "Non-defining relative clause", "use": "..., which + verb", "example": "which tends to make them stick in your memory", "try": "______, which tends to ______."}]}}, {"q": "How can people learn about the history of their own area?", "model": {"answer": "The easiest starting point is talking to older residents, whose memories rarely appear in textbooks. On top of that, local museums, old photographs and even street names can be a goldmine of information. If I were setting out to research my own neighbourhood, I’d pay a visit to the city archive and then walk the streets with a notebook, matching up what I’d read with what I could see.", "phrases": [["a goldmine of information", "a very rich source of facts"], ["setting out to", "starting with the aim of"], ["pay a visit", "go and see"], ["matching up", "connecting two things that correspond"], ["on top of that", "in addition"]], "grammar": [{"pattern": "Relative clause with whose", "use": "noun, whose + noun + verb", "example": "older residents, whose memories rarely appear in textbooks", "try": "______, whose ______."}, {"pattern": "Second conditional", "use": "If I were + -ing, I’d + verb", "example": "If I were setting out to research my own neighbourhood, I’d pay a visit to the city archive", "try": "If I were ______, I’d ______."}]}}, {"q": "How can technology make history more interesting for students?", "model": {"answer": "Virtual reality is probably the most exciting example, as it lets students walk through an ancient city rather than just read about it. Interactive maps and timelines also make abstract dates tangible. Not only does this hold students’ attention, but it encourages them to explore independently. The risk, though, is that flashy visuals take the place of real analysis, so teachers still need to ask probing questions.", "phrases": [["walk through", "explore by moving around inside"], ["make abstract dates tangible", "turn ideas into something you can see and touch"], ["hold students’ attention", "keep students interested"], ["take the place of", "replace"], ["ask probing questions", "ask deep questions that test understanding"]], "grammar": [{"pattern": "Inversion with not only", "use": "Not only does + subject + verb, but ...", "example": "Not only does this hold students’ attention, but it encourages them to explore independently", "try": "Not only does it ______, but it ______."}, {"pattern": "Participle result clause", "use": "lets + object + verb", "example": "it lets students walk through an ancient city rather than just read about it", "try": "It lets people ______ rather than just ______."}]}}, {"q": "Why do some people find history boring?", "model": {"answer": "Mostly because of how it’s taught. When history is reduced to memorising dates and names, it feels disconnected from real life, and students switch off. I certainly found it dull at school until a teacher started telling the stories behind the facts. Perspective matters too: people who live very much in the present tend to see the past as irrelevant, even though it shaped the world they live in.", "phrases": [["feels disconnected from", "seems unrelated to"], ["switch off", "stop paying attention"], ["very much in the present", "focused only on now"], ["shaped", "formed or influenced"], ["reduced to", "simplified to just"]], "grammar": [{"pattern": "Passive in a time clause", "use": "When + noun + is reduced to + noun", "example": "When history is reduced to memorising dates and names", "try": "When a subject is reduced to ______."}, {"pattern": "Concession with even though", "use": "even though + clause", "example": "even though it shaped the world they live in", "try": "______, even though ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "People"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000063', 1063, 'Topic 63', 'Party that impressed you', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 63, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a party for a special event that impressed you a lot", "bullets": ["when and where it was held", "what the party was held for", "how many people attended it", "why it impressed you a lot"], "explain": "", "notes": ["When/Wher E", "What For", "How Many", "Why"], "rounding": {"q": "Do you usually enjoy big parties like that?", "model": {"answer": "Yes, especially family ones, because there’s always someone new to talk to. That said, I’m just as happy with a quiet dinner among close friends.", "phrases": [], "grammar": []}}, "model": {"answer": "One occasion I’ll never forget is my grandparents’ golden wedding anniversary, held last August in a restored courtyard house in old Bukhara. It was a sweltering evening, but the vine-covered terrace kept everything pleasantly cool, and lanterns had been strung up between the trees, glowing softly as it got dark. The party was thrown to celebrate fifty years of marriage, something my grandfather had always claimed he would never live to see. My aunts had kept it under wraps for months, so when my grandparents walked in and the whole room stood up, my grandmother was lost for words. Around a hundred and twenty people attended, including relatives, all dressed in their best, who had come from as far afield as Moscow and Istanbul, and even my grandfather’s old school friend, whom he hadn’t seen in decades. What impressed me most wasn’t the food, although the plov was outstanding. It was the attention to detail. My cousins had put together a short film of my grandparents’ life, from their black-and-white wedding photos to their first flat, and there was not a dry eye in the house. Then, to everyone’s surprise, my grandfather took to the dance floor and stole the show, twirling my grandmother as if they were twenty again. Looking back, I realised the best parties aren’t about extravagance; they’re about people who go the extra mile to make someone feel valued. It was truly a night to remember.", "sections": [{"label": "When/Wher E", "text": "One occasion I’ll never forget is my grandparents’ golden wedding anniversary, held last August in a restored courtyard house in old Bukhara. It was a sweltering evening, but the vine-covered terrace kept everything pleasantly cool, and lanterns had been strung up between the trees, glowing softly as it got dark."}, {"label": "What For", "text": "The party was thrown to celebrate fifty years of marriage, something my grandfather had always claimed he would never live to see. My aunts had kept it under wraps for months, so when my grandparents walked in and the whole room stood up, my grandmother was lost for words."}, {"label": "How Many", "text": "Around a hundred and twenty people attended, including relatives, all dressed in their best, who had come from as far afield as Moscow and Istanbul, and even my grandfather’s old school friend, whom he hadn’t seen in decades."}, {"label": "Why", "text": "What impressed me most wasn’t the food, although the plov was outstanding. It was the attention to detail. My cousins had put together a short film of my grandparents’ life, from their black-and-white wedding photos to their first flat, and there was not a dry eye in the house. Then, to everyone’s surprise, my grandfather took to the dance floor and stole the show, twirling my grandmother as if they were twenty again. Looking back, I realised the best parties aren’t about extravagance; they’re about people who go the extra mile to make someone feel valued. It was truly a night to remember."}], "phrases": [["sweltering", "extremely hot and uncomfortable"], ["strung up", "hung in a line, such as lights or flags"], ["thrown", "organised, as in a party"], ["kept it under wraps", "kept it secret"], ["lost for words", "so surprised or moved that you cannot speak"], ["as far afield as", "from places a long way away, such as"], ["not a dry eye in the house", "everyone was crying with emotion"], ["took to the dance floor", "started dancing"], ["stole the show", "got more attention and praise than anyone else"], ["go the extra mile", "make more effort than is expected"], ["a night to remember", "an evening that is never forgotten"]], "grammar": [{"pattern": "Participle clause", "use": "noun + past participle + place/time", "example": "my grandparents’ golden wedding anniversary, held last August in a restored courtyard house", "try": "My birthday, held ______, was ______."}, {"pattern": "Past perfect passive", "use": "had been + past participle", "example": "lanterns had been strung up between the trees", "try": "By the time we arrived, ______ had been ______."}, {"pattern": "Relative clause with whom", "use": "person + whom + subject + verb", "example": "my grandfather’s old school friend, whom he hadn’t seen in decades", "try": "______, whom I hadn’t seen for ______."}, {"pattern": "Cleft sentence", "use": "What + verb + most + was ...", "example": "What impressed me most wasn’t the food", "try": "What impressed me most was ______."}, {"pattern": "As if + past", "use": "as if + subject + were/past simple", "example": "as if they were twenty again", "try": "He acted as if he ______."}]}}, "part3": {"intro": "We’ve been talking about a party for a special event that impressed you a lot, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Party that impressed you", "title": "Party that impressed you", "questions": [{"q": "What kinds of parties are common in your country?", "model": {"answer": "Family celebrations are by far the most common, especially weddings, which can go on for hours and involve hundreds of guests. Beyond that, people throw engagement parties, baby celebrations and big gatherings at home for national holidays such as Navruz. What they all share is generous hospitality; nobody would dream of letting a guest leave hungry. A table laden with food is almost the symbol of an Uzbek party.", "phrases": [["go on for hours", "continue for a very long time"], ["throw", "organise a party"], ["would dream of", "would ever consider"], ["laden with", "heavily loaded with"], ["generous hospitality", "warm, welcoming treatment of guests"]], "grammar": [{"pattern": "Relative clause", "use": "wedding, which + verb", "example": "especially weddings, which can go on for hours and involve hundreds of guests", "try": "______, which can ______."}, {"pattern": "Cleft sentence", "use": "What + subject + share + is ...", "example": "What they all share is generous hospitality", "try": "What ______ share is ______."}]}}, {"q": "How do people usually celebrate personal events such as birthdays?", "model": {"answer": "It used to be a simple family dinner, but celebrations have become far more elaborate. These days, many people book a café or rent a room, hire a host and post photos online. Still, the core tradition hasn’t changed: relatives gather around a big table, and the birthday person is showered with good wishes and small gifts. Personally, I prefer the quieter style, because it feels more genuine.", "phrases": [["book a café", "reserve a venue"], ["post photos online", "share pictures on social media"], ["hasn’t changed", "has stayed the same"], ["showered with", "given a large amount of"], ["genuine", "sincere and real"]], "grammar": [{"pattern": "Used to + contrast with present", "use": "It used to be ..., but ... have become", "example": "It used to be a simple family dinner, but celebrations have become far more elaborate", "try": "It used to be ______, but now ______."}, {"pattern": "Passive", "use": "is + past participle + with", "example": "the birthday person is showered with good wishes and small gifts", "try": "The guest of honour is ______ with ______."}]}}, {"q": "What do children do at birthday parties?", "model": {"answer": "Mostly they run around, play games and eat too much cake. Organisers often hire an entertainer, such as a clown, who leads party games like musical chairs. Children get carried away quickly, so there’s usually a little chaos, and by the end half of them are in tears or fast asleep on a sofa. But they love it, and it’s often where they form their first friendships outside school.", "phrases": [["party games", "organised games played at parties"], ["get carried away", "become too excited and lose control"], ["fast asleep", "deeply asleep"], ["form their first friendships", "begin to make friends"], ["a little chaos", "some disorder and noise"]], "grammar": [{"pattern": "Relative clause with who", "use": "an entertainer, such as a clown, who + verb", "example": "an entertainer, such as a clown, who leads party games", "try": "A teacher, such as ______, who ______."}, {"pattern": "Cleft with where", "use": "it’s often where + clause", "example": "it’s often where they form their first friendships outside school", "try": "It’s often where ______."}]}}, {"q": "Why do some people dislike parties?", "model": {"answer": "For some it comes down to personality. Introverts find crowds draining, and small talk with strangers can feel like hard work. Others dislike the pressure: if you’re expected to dress up, bring a gift and stay late, a party can feel like an obligation rather than fun. And then there’s noise. I’ve been to events where I could barely hear the person next to me, which, frankly, put me off.", "phrases": [["draining", "making you feel tired and without energy"], ["small talk", "polite, light conversation"], ["feel like an obligation", "seem like something you must do"], ["put me off", "made me dislike something"], ["comes down to", "depends mainly on"]], "grammar": [{"pattern": "Conditional with passive", "use": "if you’re expected to + verb, ...", "example": "if you’re expected to dress up, bring a gift and stay late", "try": "If you’re expected to ______, ______."}, {"pattern": "Non-defining relative clause", "use": "..., which, frankly, + verb", "example": "which, frankly, put me off", "try": "______, which, honestly, ______."}]}}, {"q": "Do you think people can make more friends if they often go to parties?", "model": {"answer": "Up to a point. Parties are a quick way to meet new faces, particularly if a friend introduces you around. However, a real friendship needs more than one night; it only takes root when you meet again and have something in common. So someone who goes to parties but never follows up will end up with a long list of acquaintances rather than close friends. Quality matters more than quantity.", "phrases": [["meet new faces", "get to know new people"], ["takes root", "starts to become firmly established"], ["have something in common", "share interests or experiences"], ["close friends", "friends you are very attached to"], ["follows up", "contacts someone again afterwards"]], "grammar": [{"pattern": "Only when", "use": "it only + verb + when + clause", "example": "it only takes root when you meet again", "try": "It only works when ______."}, {"pattern": "Comparison", "use": "matters more than", "example": "Quality matters more than quantity", "try": "______ matters more than ______."}]}}, {"q": "Why do families organise parties for special occasions?", "model": {"answer": "Largely to mark the moment. Occasions like a graduation or a wedding are milestones, and a gathering lets everyone share the joy. There’s a practical side too: relatives who live in different cities rarely meet, so a party brings the family together. And for older generations, hosting generously is a matter of pride. Were it not for such events, families would drift apart much faster.", "phrases": [["mark", "celebrate or recognise an occasion"], ["milestones", "important stages in life"], ["brings the family together", "unites relatives"], ["a matter of pride", "something people feel proud about"], ["drift apart", "slowly become less close"]], "grammar": [{"pattern": "Inverted second conditional", "use": "Were it not for + noun, would + verb", "example": "Were it not for such events, families would drift apart much faster", "try": "Were it not for ______, ______ would ______."}, {"pattern": "Relative clause", "use": "relatives who + verb", "example": "relatives who live in different cities rarely meet", "try": "Friends who ______ rarely ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Events & experiences"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000064', 1064, 'Topic 64', 'Public building you enjoy visiting', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 64, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a public building you enjoy visiting (e.g. a library, a shopping centre, a sports hall)", "bullets": ["where it is", "how you know about it", "what it looks like", "and explain why you enjoy visiting it"], "explain": "", "notes": ["Where", "How I Know", "Looks", "Why"], "rounding": {"q": "Do many other people of your age go to this library?", "model": {"answer": "Yes, quite a few. On weekday afternoons it’s full of students, and during exams you have to arrive early to find a free desk.", "phrases": [], "grammar": []}}, "model": {"answer": "The first place that comes to mind is the central library in Tashkent, a short walk from the metro and tucked away behind a row of plane trees. I go there so often that the librarians know me by sight. I found out about it years ago, when my English teacher, who was always harping on about the value of reading, took our whole class there on a school trip. I was fifteen and mildly sceptical, but one hour among those shelves changed my mind. Since then it has become my second home, especially during exam season. From the outside it’s a large, pale stone building with tall arched windows, and in front there’s a small garden where students sit with their notes. Inside, the main reading hall has soaring ceilings, long wooden desks and green-shaded lamps, giving the place a calm, almost old-fashioned feel. Natural light pours in through the windows all afternoon, and you can hear nothing but the faint rustle of pages. The reason I enjoy it is simple: it takes me out of my own head. At home I’m constantly sidetracked by my phone, but the moment I step through those doors, I settle down and concentrate. There’s something motivating about being surrounded by people who are all working quietly on their own goals. Looking back, I’m convinced I wouldn’t have passed my university entrance exams with flying colours had I studied anywhere else. For me, it’s a place that brings out the best in people.", "sections": [{"label": "Where", "text": "The first place that comes to mind is the central library in Tashkent, a short walk from the metro and tucked away behind a row of plane trees. I go there so often that the librarians know me by sight."}, {"label": "How I Know", "text": "I found out about it years ago, when my English teacher, who was always harping on about the value of reading, took our whole class there on a school trip. I was fifteen and mildly sceptical, but one hour among those shelves changed my mind. Since then it has become my second home, especially during exam season."}, {"label": "Looks", "text": "From the outside it’s a large, pale stone building with tall arched windows, and in front there’s a small garden where students sit with their notes. Inside, the main reading hall has soaring ceilings, long wooden desks and green-shaded lamps, giving the place a calm, almost old-fashioned feel. Natural light pours in through the windows all afternoon, and you can hear nothing but the faint rustle of pages."}, {"label": "Why", "text": "The reason I enjoy it is simple: it takes me out of my own head. At home I’m constantly sidetracked by my phone, but the moment I step through those doors, I settle down and concentrate. There’s something motivating about being surrounded by people who are all working quietly on their own goals. Looking back, I’m convinced I wouldn’t have passed my university entrance exams with flying colours had I studied anywhere else. For me, it’s a place that brings out the best in people."}], "phrases": [["know me by sight", "recognise me because they see me regularly"], ["harping on about", "talking repeatedly and annoyingly about"], ["mildly sceptical", "slightly doubtful"], ["changed my mind", "made me think differently"], ["soaring ceilings", "very high ceilings that create a sense of space"], ["pours in", "flows in large amounts"], ["faint rustle", "a soft sound like paper moving"], ["takes me out of my own head", "stops me overthinking and distracts me from worries"], ["sidetracked", "distracted from what I should be doing"], ["with flying colours", "with excellent results"], ["brings out the best in", "makes people perform or behave at their best"]], "grammar": [{"pattern": "Past simple with relative clause", "use": "noun, who + past continuous", "example": "my English teacher, who was always harping on about the value of reading", "try": "My teacher, who was always ______."}, {"pattern": "Participle clause of result", "use": "..., giving + object + ...", "example": "giving the place a calm, almost old-fashioned feel", "try": "______, giving it a ______ feel."}, {"pattern": "So ... that", "use": "so + adverb + that + clause", "example": "I go there so often that the librarians know me by sight", "try": "I go there so often that ______."}, {"pattern": "Inverted third conditional", "use": "I wouldn’t have + pp ... had + subject + pp", "example": "I wouldn’t have passed my university entrance exams with flying colours had I studied anywhere else", "try": "I wouldn’t have ______ had I ______."}, {"pattern": "Time clause with the moment", "use": "the moment + clause, main clause", "example": "the moment I step through those doors, I settle down and concentrate", "try": "The moment I ______, I ______."}]}}, "part3": {"intro": "We’ve been talking about a public building you enjoy visiting, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Public building you enjoy visiting", "title": "Public building you enjoy visiting", "questions": [{"q": "Is it difficult to protect historic buildings?", "model": {"answer": "Yes, mainly because it’s so expensive. Old structures need specialist craftsmen and traditional materials, so the costs add up quickly. Then there’s pressure from developers who want the land for something more profitable. Weather and pollution take their toll as well. In my view, it’s a constant balancing act between preserving the past and meeting the needs of a growing city, and the balance often tips in favour of money.", "phrases": [["the costs add up", "small expenses together become very large"], ["take their toll", "cause gradual damage"], ["balancing act", "the difficulty of keeping two things in proportion"], ["meeting the needs", "providing what is required"], ["tips in favour of", "moves towards one side"]], "grammar": [{"pattern": "Relative clause", "use": "developers who want + noun", "example": "developers who want the land for something more profitable", "try": "People who want ______ often ______."}, {"pattern": "Between ... and ...", "use": "a balancing act between A and B", "example": "a constant balancing act between preserving the past and meeting the needs of a growing city", "try": "It’s a balancing act between ______ and ______."}]}}, {"q": "Should old buildings be preserved?", "model": {"answer": "Generally, yes, although not every old building deserves it. Those with genuine historical value are irreplaceable; once demolished, they’re gone for good. They also give a city its character, which no glass tower can replicate. On the other hand, a crumbling, unsafe building may not be worth saving, so we should be selective rather than preserving everything out of sentiment.", "phrases": [["are irreplaceable", "cannot be replaced once lost"], ["character", "the special quality of a place"], ["replicate", "copy exactly"], ["may not be worth saving", "may not deserve the effort to protect"], ["preserving everything out of sentiment", "keeping things just for emotional reasons"]], "grammar": [{"pattern": "Concession with although", "use": "although + clause", "example": "although not every old building deserves it", "try": "Generally yes, although ______."}, {"pattern": "Passive in time clause", "use": "once + past participle", "example": "once demolished, they’re gone for good", "try": "Once ______, it’s gone for good."}]}}, {"q": "Who should pay for the preservation of historic buildings?", "model": {"answer": "I’d argue the cost should be shared. The government has a duty to fund buildings of national importance, since they belong to everyone. However, private owners and businesses that benefit, such as hotels near a famous monument, could chip in as well, and visitors can contribute through ticket sales. If the whole burden fell on a single party, whether the state or a family, it would simply be unsustainable.", "phrases": [["has a duty to", "is responsible for"], ["burden", "a heavy responsibility or cost"], ["chip in", "contribute some money"], ["through ticket sales", "by buying entry tickets"], ["unsustainable", "impossible to continue for long"]], "grammar": [{"pattern": "Second conditional", "use": "If + past simple, would + verb", "example": "If the whole burden fell on a single party, whether the state or a family, it would simply be unsustainable", "try": "If the cost fell on ______, it would be ______."}, {"pattern": "Whether ... or ...", "use": "whether A or B", "example": "whether the state or a family", "try": "whether the ______ or the ______."}]}}, {"q": "What makes a public building attractive?", "model": {"answer": "Light and space, I’d say. A building with high ceilings, large windows and clear signs feels welcoming from the moment you walk in. Design matters, but so does upkeep: a beautiful hall with peeling paint soon loses its appeal. Comfort counts too, such as decent seating and fresh air. What makes people want to linger is not grandeur but a sense that the place was designed with them in mind.", "phrases": [["feels welcoming", "makes you feel comfortable and wanted"], ["upkeep", "regular maintenance"], ["loses its appeal", "becomes less attractive"], ["makes people want to linger", "encourages people to stay"], ["grandeur", "impressive size or beauty"]], "grammar": [{"pattern": "Cleft sentence", "use": "What + verb + is not A but B", "example": "What makes people want to linger is not grandeur but a sense that the place was designed with them in mind", "try": "What matters is not ______ but ______."}, {"pattern": "Not only / so does", "use": "X matters, but so does Y", "example": "Design matters, but so does upkeep", "try": "______ matters, but so does ______."}]}}, {"q": "How do public buildings contribute to a community?", "model": {"answer": "They give people somewhere to meet, which is the foundation of any community. A library or a sports hall brings together people from different backgrounds, and that fosters a sense of belonging. They also provide services many families could not afford privately, such as free study space. In my neighbourhood the community centre hosts everything from language classes to elections, so it has become the beating heart of the area.", "phrases": [["brings together", "unites"], ["fosters a sense of belonging", "encourages people to feel part of a group"], ["the beating heart", "the most important centre of activity"], ["the foundation", "the base on which something is built"], ["hosts", "holds an event or activity"]], "grammar": [{"pattern": "Non-defining relative clause", "use": "..., which is + noun", "example": "somewhere to meet, which is the foundation of any community", "try": "______, which is the ______ of ______."}, {"pattern": "Reduced relative clause", "use": "services + subject + verb", "example": "services many families could not afford privately", "try": "services many people ______."}]}}, {"q": "Do you think architecture should reflect the culture of a place?", "model": {"answer": "Ideally, yes. When a building uses local patterns, materials or proportions, it tells a story about the people who built it; think of the blue tiles on mosques in Uzbekistan. At the same time, I wouldn’t want cities to become museum pieces. The best architects take traditional elements and give them a modern twist, which keeps the identity alive while meeting practical needs such as energy efficiency.", "phrases": [["tells a story", "shows history or meaning"], ["museum pieces", "things only for display, not for living in"], ["give them a modern twist", "adapt them in a new, contemporary way"], ["keeps the identity alive", "preserves what makes a place unique"], ["meeting practical needs", "satisfying everyday requirements"]], "grammar": [{"pattern": "When-clause generalisation", "use": "When + subject + present, it + present", "example": "When a building uses local patterns, materials or proportions, it tells a story about the people who built it", "try": "When a building ______, it ______."}, {"pattern": "Non-defining relative clause", "use": "..., which + verb", "example": "which keeps the identity alive while meeting practical needs", "try": "______, which keeps ______ while ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Places"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000065', 1065, 'Topic 65', 'Person who likes taking photos', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 65, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a person you know who really likes taking photos", "bullets": ["who the person is", "when and how you got to know this person", "where this person takes photos", "how you feel about this person"], "explain": "", "notes": ["Who", "When/How", "Where", "Feelings"], "rounding": {"q": "Do you enjoy having your photo taken?", "model": {"answer": "Not really, to be honest. I’m much happier behind the camera than in front of it, although Timur never lets me escape for long.", "phrases": [], "grammar": []}}, "model": {"answer": "The person who immediately comes to mind is my friend Timur, who is studying architecture and who, quite frankly, is never seen without a camera around his neck. We met three years ago on the first day of university, when I bumped into him in a corridor, flustered and hopelessly lost. He raised his camera, took a picture of my panicked face and, before I could protest, showed me the screen. I laughed so much that I forgot I was lost, and we’ve been inseparable ever since. He takes photos everywhere, but his favourite spots are the old quarters of Bukhara and Khiva, where he can spend hours waiting for the right light. He loves early mornings, when the lanes are empty and the sun spills over the clay walls. I once joined him at five o’clock, grumbling the whole way, and ended up standing there speechless at the golden glow on the minarets. What I admire is his patience: he’ll wait for ages for a single stranger to walk through the frame. I feel enormously grateful to him. Before I met Timur, I would have walked straight past a crumbling doorway, but he has taught me to notice the little things. Admittedly, he can be a bit of a perfectionist, and trips with him tend to take twice as long, but I wouldn’t change that. If he hadn’t taken that first picture, we might never have spoken, so our friendship, in a sense, was born from a photograph. I’d say he has helped me see the world through fresh eyes.", "sections": [{"label": "Who", "text": "The person who immediately comes to mind is my friend Timur, who is studying architecture and who, quite frankly, is never seen without a camera around his neck."}, {"label": "When/How", "text": "We met three years ago on the first day of university, when I bumped into him in a corridor, flustered and hopelessly lost. He raised his camera, took a picture of my panicked face and, before I could protest, showed me the screen. I laughed so much that I forgot I was lost, and we’ve been inseparable ever since."}, {"label": "Where", "text": "He takes photos everywhere, but his favourite spots are the old quarters of Bukhara and Khiva, where he can spend hours waiting for the right light. He loves early mornings, when the lanes are empty and the sun spills over the clay walls. I once joined him at five o’clock, grumbling the whole way, and ended up standing there speechless at the golden glow on the minarets. What I admire is his patience: he’ll wait for ages for a single stranger to walk through the frame."}, {"label": "Feelings", "text": "I feel enormously grateful to him. Before I met Timur, I would have walked straight past a crumbling doorway, but he has taught me to notice the little things. Admittedly, he can be a bit of a perfectionist, and trips with him tend to take twice as long, but I wouldn’t change that. If he hadn’t taken that first picture, we might never have spoken, so our friendship, in a sense, was born from a photograph. I’d say he has helped me see the world through fresh eyes."}], "phrases": [["never seen without a camera", "always has a camera with him"], ["flustered", "nervous and confused"], ["inseparable", "always together, very close"], ["waiting for the right light", "patiently waiting for the best natural lighting"], ["spills over", "flows across a surface"], ["standing there speechless", "unable to speak because of amazement"], ["wait for ages", "wait for a very long time"], ["walked straight past", "ignored something completely"], ["notice the little things", "pay attention to small details"], ["a bit of a perfectionist", "someone who wants everything to be exactly right"], ["take twice as long", "need double the time"], ["was born from a photograph", "began because of a photo"], ["see the world through fresh eyes", "look at familiar things in a new way"]], "grammar": [{"pattern": "Relative clause with who", "use": "The person who + verb", "example": "The person who immediately comes to mind is my friend Timur", "try": "The person who ______ is ______."}, {"pattern": "Before + could", "use": "before + subject + could + verb", "example": "before I could protest", "try": "Before I could ______, ______."}, {"pattern": "Present perfect continuous with", "use": "ever since we’ve been + adjective + ever since", "example": "we’ve been inseparable ever since", "try": "We’ve been ______ ever since ______."}, {"pattern": "Cleft sentence", "use": "What + subject + verb + is ...", "example": "What I admire is his patience", "try": "What I admire is ______."}, {"pattern": "Third conditional", "use": "if + past perfect, might + have + pp", "example": "If he hadn’t taken that first picture, we might never have spoken", "try": "If ______ hadn’t ______, we might never have ______."}]}}, "part3": {"intro": "We’ve been talking about a person you know who really likes taking photos, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Person who likes taking photos", "title": "Person who likes taking photos", "questions": [{"q": "Why do people like to keep photos?", "model": {"answer": "Because photographs preserve moments that memory alone would let fade. Looking at an old picture can instantly bring back details you’d forgotten, like the clothes you wore or the person standing beside you. They’re also precious as a link to family members who are no longer with us. My grandmother treasures a shoebox of faded prints more than anything she owns, which says a lot.", "phrases": [["preserve", "keep safe and unchanged"], ["bring back", "make you remember"], ["treasures", "values very highly"], ["says a lot", "reveals something important"], ["a link to", "a connection with"]], "grammar": [{"pattern": "Would for hypothetical", "use": "memory alone would + verb", "example": "moments that memory alone would let fade", "try": "things that time would ______."}, {"pattern": "Non-defining relative clause", "use": "..., which + verb", "example": "which says a lot", "try": "______, which says a lot about ______."}]}}, {"q": "On what occasions do most people take photos?", "model": {"answer": "Typically on special occasions such as weddings, graduations, birthdays and holidays. People feel such days are once in a lifetime, so they want proof. That is changing, though, because with smartphones we photograph everyday things too, like a meal or a sunset. The common thread is the urge to share: whenever something looks good or feels significant, most people reach for their phones almost automatically.", "phrases": [["once in a lifetime", "happening only once"], ["the common thread", "what connects different things"], ["the urge to share", "a strong wish to show others"], ["reach for their phones", "automatically pick up their phones"], ["proof", "evidence that something happened"]], "grammar": [{"pattern": "Whenever", "use": "whenever + clause, subject + verb", "example": "whenever something looks good or feels significant, most people reach for their phones", "try": "Whenever ______, people ______."}, {"pattern": "Continuous change", "use": "That is changing, though", "example": "That is changing, though", "try": "That is changing, though, because ______."}]}}, {"q": "Where do people like to take photos?", "model": {"answer": "Mostly in places that are scenic or symbolic. Tourist landmarks, such as the Registan in Samarkand, are obvious photo spots, and parks are popular for family portraits. Increasingly, though, people photograph trendy cafés, because the setting looks good on social media. Personally, I find the most interesting pictures are taken in ordinary places, like a busy bazaar, where real life unfolds naturally.", "phrases": [["photo spots", "places popular for taking pictures"], ["trendy cafés", "fashionable cafés"], ["looks good on social media", "is attractive in online posts"], ["unfolds", "develops or happens naturally"], ["scenic", "with beautiful views"]], "grammar": [{"pattern": "Passive", "use": "are + past participle", "example": "the most interesting pictures are taken in ordinary places", "try": "The best pictures are taken ______."}, {"pattern": "Relative clause with where", "use": "place, where + clause", "example": "a busy bazaar, where real life unfolds naturally", "try": "______, where ______."}]}}, {"q": "What are the advantages and disadvantages of travelling with a camera?", "model": {"answer": "The obvious advantage is that you come home with memories you can look back on for years. A good camera also captures details that a phone might miss. The downside is the weight and the worry: lugging around expensive equipment can be exhausting, and there’s always the risk of theft. Worse still, you may spend so much time framing the perfect shot that you forget to enjoy the place itself.", "phrases": [["look back on", "remember and think about the past"], ["captures details", "records small features"], ["lugging around", "carrying with effort"], ["framing the perfect shot", "arranging a photo carefully"], ["the downside", "the disadvantage"]], "grammar": [{"pattern": "So much ... that", "use": "so much time ... that + clause", "example": "you may spend so much time framing the perfect shot that you forget to enjoy the place itself", "try": "I spent so much time ______ that ______."}, {"pattern": "Relative clause", "use": "memories you can + verb", "example": "memories you can look back on for years", "try": "memories you can ______."}]}}, {"q": "Who takes more photos, young people or older people?", "model": {"answer": "Young people, without question. They’ve grown up with smartphones, so photography is almost a reflex, and they document everything, from lunch to their outfit. Older people tend to take fewer pictures, usually on special occasions, and are more selective. Interestingly, though, many grandparents have recently taken to photography after receiving a smartphone, and they send my family endless pictures of their gardens, so the gap is narrowing.", "phrases": [["document", "record in detail, usually with photos or writing"], ["are more selective", "choose more carefully"], ["taken to", "started to like and do regularly"], ["narrowing", "getting smaller"], ["a reflex", "an automatic reaction"]], "grammar": [{"pattern": "Present perfect", "use": "have + recently + past participle", "example": "many grandparents have recently taken to photography", "try": "Many people have recently taken to ______."}, {"pattern": "Comparative", "use": "more + adjective", "example": "are more selective", "try": "Older people are more ______."}]}}, {"q": "Do you think taking photos can spoil the experience of a moment?", "model": {"answer": "It can, if you let it. Having a phone in front of your face means you’re watching life through a screen rather than being fully present. I noticed this at a concert once: half the audience was filming, and the atmosphere felt strangely flat. The trick is to take one or two pictures and then put the phone away, which lets you live in the moment.", "phrases": [["watching life through a screen", "experiencing things only via a device"], ["fully present", "giving full attention to the moment"], ["put the phone away", "stop using the phone"], ["live in the moment", "enjoy the present fully"], ["the atmosphere felt strangely flat", "the mood seemed lifeless"]], "grammar": [{"pattern": "Gerund subject", "use": "Having + noun + means + clause", "example": "Having a phone in front of your face means you’re watching life through a screen", "try": "Having ______ means ______."}, {"pattern": "Past continuous for background", "use": "half the audience was + -ing", "example": "half the audience was filming", "try": "Everyone was ______ when ______."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "People"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values ('5e7a0002-0000-4000-8000-000000000066', 1066, 'Topic 66', 'Natural place in your city', $tp${"source": "Parts 2 & 3 Model Answers · Sep–Dec 2026", "topic_no": 66, "part1": [], "part2": {"intro": "Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. You have one minute to prepare, and you can make notes. Here is your topic.", "cue": "Describe a natural place in your city that you enjoy visiting", "bullets": ["where it is", "how often you go there", "who you go there with", "why you enjoy visiting it"], "explain": "", "notes": ["Where", "How Often", "Who With", "Why"], "rounding": {"q": "Do you think your city has enough green spaces?", "model": {"answer": "Not really, since the city keeps growing so fast. There are lovely parks, but I’d like to see more of them in the new districts.", "phrases": [], "grammar": []}}, "model": {"answer": "A place I never get tired of is the Botanical Garden in Tashkent, tucked away on the edge of the city, far enough from the main roads that the traffic noise fades away within a few minutes of walking in. I try to go about twice a month, usually on a Saturday morning, rain or shine. In spring I go even more often, because the fruit trees are in full bloom and I simply can’t resist them. Most of the time I go with my younger brother Aziz, who is fourteen and has a short attention span unless there are ducks involved. We always follow the same route: a loop around the pond, then a rest on our favourite bench, where we share a bag of sunflower seeds. Occasionally I go alone with a book, which is a very different experience. What draws me there is the sense of calm. Within ten minutes of walking under those huge old trees, my shoulders drop and the week’s worries melt away. One morning last October, as leaves were drifting down through the sunlight, Aziz, who never says anything profound, whispered, “It’s like the garden is breathing.” I’ve remembered that ever since. Were I living anywhere else, I would miss it terribly. It’s the one place where I can recharge my batteries without even trying, and a city this size badly needs more of them.", "sections": [{"label": "Where", "text": "A place I never get tired of is the Botanical Garden in Tashkent, tucked away on the edge of the city, far enough from the main roads that the traffic noise fades away within a few minutes of walking in."}, {"label": "How Often", "text": "I try to go about twice a month, usually on a Saturday morning, rain or shine. In spring I go even more often, because the fruit trees are in full bloom and I simply can’t resist them."}, {"label": "Who With", "text": "Most of the time I go with my younger brother Aziz, who is fourteen and has a short attention span unless there are ducks involved. We always follow the same route: a loop around the pond, then a rest on our favourite bench, where we share a bag of sunflower seeds. Occasionally I go alone with a book, which is a very different experience."}, {"label": "Why", "text": "What draws me there is the sense of calm. Within ten minutes of walking under those huge old trees, my shoulders drop and the week’s worries melt away. One morning last October, as leaves were drifting down through the sunlight, Aziz, who never says anything profound, whispered, “It’s like the garden is breathing.” I’ve remembered that ever since. Were I living anywhere else, I would miss it terribly. It’s the one place where I can recharge my batteries without even trying, and a city this size badly needs more of them."}], "phrases": [["fades away", "gradually becomes weaker and disappears"], ["rain or shine", "whatever the weather"], ["in full bloom", "with all the flowers fully open"], ["can’t resist", "find it impossible not to enjoy"], ["short attention span", "unable to concentrate for long"], ["sense of calm", "a feeling of peace"], ["melt away", "gradually disappear"], ["drifting down", "falling slowly and gently"], ["miss", "feel sad about not having"], ["recharge my batteries", "regain energy by resting"], ["badly needs", "really needs"]], "grammar": [{"pattern": "So far enough that", "use": "far enough from + noun + that + clause", "example": "far enough from the main roads that the traffic noise fades away", "try": "It’s far enough from ______ that ______."}, {"pattern": "Relative clause with who", "use": "Aziz, who + verb", "example": "Most of the time I go with my younger brother Aziz, who is fourteen", "try": "my friend ______, who ______."}, {"pattern": "Cleft sentence", "use": "What + verb + me + there is ...", "example": "What draws me there is the sense of calm", "try": "What draws me to ______ is ______."}, {"pattern": "Within + time", "use": "Within + time, + clause", "example": "Within ten minutes of walking under those huge old trees, my shoulders drop", "try": "Within ______ minutes, I ______."}, {"pattern": "Inverted second conditional", "use": "Were I + -ing, I would + verb", "example": "Were I living anywhere else, I would miss it terribly", "try": "Were I living in ______, I would ______."}]}}, "part3": {"intro": "We’ve been talking about a natural place in your city that you enjoy visiting, and now I’d like to discuss with you one or two general questions related to this.", "theme": "Natural place in your city", "title": "Natural place in your city", "questions": [{"q": "What kind of people like to visit natural places?", "model": {"answer": "It’s a very broad group, but I’d single out two types. Active people, such as hikers and cyclists, see nature as a playground, whereas those with stressful jobs go there simply to unwind. Families are also regular visitors, especially at weekends. Interestingly, the older people I know are drawn to quiet green spaces more than the young, probably because they value peace and quiet as they age.", "phrases": [["single out", "choose from a group"], ["playground", "a place for activity and fun"], ["unwind", "relax after stress"], ["are drawn to", "are attracted to"], ["value peace and quiet", "care a great deal about calm and silence"]], "grammar": [{"pattern": "Contrast with whereas", "use": "A ..., whereas B ...", "example": "hikers and cyclists, see nature as a playground, whereas those with stressful jobs go there simply to unwind", "try": "Some ______, whereas others ______."}, {"pattern": "Relative clause", "use": "the older people I know", "example": "the older people I know are drawn to quiet green spaces more than the young", "try": "The people I know ______."}]}}, {"q": "What can people gain from spending time in nature?", "model": {"answer": "First and foremost, a clear head. After an hour among trees, worries tend to fade into the background, and many people find they sleep better too. There are physical benefits as well, since walking on uneven ground is good exercise. Perhaps most valuable of all is perspective: standing in front of a mountain reminds you that your problems are small, which can put things in perspective very quickly.", "phrases": [["a clear head", "a calm, focused mind"], ["fade into the background", "become less important"], ["perspective", "a sensible way of judging what matters"], ["reminds you", "makes you remember"], ["put things in perspective", "help you see what really matters"]], "grammar": [{"pattern": "Superlative with of all", "use": "Perhaps most valuable of all is", "example": "Perhaps most valuable of all is perspective", "try": "Perhaps most important of all is ______."}, {"pattern": "Gerund as subject", "use": "standing in front of ... reminds you", "example": "standing in front of a mountain reminds you that your problems are small", "try": "Standing ______ reminds you that ______."}]}}, {"q": "Should all scenic spots charge an entry fee?", "model": {"answer": "Not necessarily. Charging a small fee makes sense for popular sites, because the money pays for cleaning, paths and security. But if every beautiful place had a ticket office, nature would become a luxury that low-income families couldn’t afford. A fair compromise might be reduced prices for locals and students, or free entry on certain days. If access is restricted by cost, we lose one of the simplest pleasures available.", "phrases": [["makes sense", "is logical and reasonable"], ["luxury", "something expensive that is not a necessity"], ["low-income families", "families with little money"], ["restricted by cost", "limited because of price"], ["a fair compromise", "a solution where both sides give something"]], "grammar": [{"pattern": "Second conditional", "use": "If + past simple, would + verb", "example": "if every beautiful place had a ticket office, nature would become a luxury", "try": "If every ______ had ______, ______ would become ______."}, {"pattern": "Relative clause with that", "use": "a luxury that + verb", "example": "a luxury that low-income families couldn’t afford", "try": "______ that many people couldn’t afford."}]}}, {"q": "Do people really relax when they see nature?", "model": {"answer": "In my experience, yes, although it depends on how they go about it. If you spend the whole walk checking your phone, you’ll hardly switch off. But sit by a river for twenty minutes without distractions and you can feel your shoulders drop. Greenery and birdsong also have a calming effect, which our brains seem to find soothing. It certainly works for me after a hectic week.", "phrases": [["switch off", "stop thinking about work or worries"], ["drop", "relax and lower"], ["which our brains seem to find soothing", "something that appears to calm the mind"], ["hectic", "very busy"], ["go about", "approach or do"]], "grammar": [{"pattern": "First conditional", "use": "If + present, will + verb", "example": "If you spend the whole walk checking your phone, you’ll hardly switch off", "try": "If you ______, you’ll hardly ______."}, {"pattern": "Imperative + and", "use": "Sit ... and you can ...", "example": "sit by a river for twenty minutes without distractions and you can feel your shoulders drop", "try": "Spend ______ and you can ______."}]}}, {"q": "How is a natural place different from a city?", "model": {"answer": "The most striking difference is the pace. In the city, everything is fast-moving, noisy and scheduled, whereas in nature time seems to slow down. The air is cleaner, and instead of traffic you hear wind and water. The city, however, offers convenience, such as shops and public transport, which a forest can’t match. Put simply, one stimulates you while the other soothes you, and we need a bit of both.", "phrases": [["fast-moving", "changing or moving quickly"], ["stimulates", "excites and energises"], ["soothes", "calms"], ["the pace", "the speed of life"], ["offers convenience", "provides easy access to things"]], "grammar": [{"pattern": "Instead of", "use": "instead of + noun, you + verb", "example": "instead of traffic you hear wind and water", "try": "Instead of ______, you hear ______."}, {"pattern": "Contrast with however", "use": "The city, however, offers", "example": "The city, however, offers convenience", "try": "The ______, however, offers ______."}]}}, {"q": "Is going to a park the only way to get close to nature?", "model": {"answer": "Far from it. Parks are convenient, but they’re carefully landscaped, so they’re only a watered-down version of nature. You can get closer by hiking in the mountains, camping beside a river or simply growing herbs on your balcony. Even keeping a few houseplants counts. What matters is the attitude: paying attention to the natural world around you, wherever you happen to be.", "phrases": [["watered-down", "weaker or less intense than the original"], ["growing herbs", "cultivating small plants"], ["counts", "is valid or important"], ["paying attention", "noticing carefully"], ["landscaped", "designed and arranged artificially"]], "grammar": [{"pattern": "Cleft sentence", "use": "What + verb + is + noun", "example": "What matters is the attitude", "try": "What matters is ______."}, {"pattern": "Wherever", "use": "wherever + subject + happen to be", "example": "wherever you happen to be", "try": "______, wherever you happen to be."}]}}], "closing": "Thank you. That is the end of the speaking test."}, "category": "Places"}$tp$::jsonb, null)
on conflict (id) do update set number = excluded.number, title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

-- Check: 33 topics here, 3 pages each.
select count(*) as topics,
       (select count(*) from public.materials where collection like 'Speaking Topics%' and storage_path like any (array(select 'speaking:' || id || '#%' from public.speaking_sets where (content->>'topic_no')::int between 34 and 66))) as pages
  from public.speaking_sets where (content->>'topic_no')::int between 34 and 66;
